-- Manual review rationale for each prompt learning contract.
-- Generated from infra/mysql/data/prompt-task-metadata-reviewed.json.

DELIMITER $$

DROP PROCEDURE IF EXISTS sp_writeloop_add_prompt_task_review_rationale $$
CREATE PROCEDURE sp_writeloop_add_prompt_task_review_rationale()
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA = DATABASE()
          AND TABLE_NAME = 'prompt_task_profiles'
          AND COLUMN_NAME = 'review_rationale'
    ) THEN
        ALTER TABLE prompt_task_profiles
            ADD COLUMN review_rationale TEXT NULL
                COMMENT 'Manual rationale for the question learning contract'
                AFTER minimum_depth_slots;
    END IF;
END $$

CALL sp_writeloop_add_prompt_task_review_rationale() $$
DROP PROCEDURE IF EXISTS sp_writeloop_add_prompt_task_review_rationale $$

DELIMITER ;

DROP TEMPORARY TABLE IF EXISTS tmp_reviewed_prompt_rationales;
CREATE TEMPORARY TABLE tmp_reviewed_prompt_rationales (
    prompt_id VARCHAR(64) NOT NULL PRIMARY KEY,
    review_rationale TEXT NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


UPDATE prompt_task_profiles profile
JOIN tmp_reviewed_prompt_rationales reviewed ON reviewed.prompt_id = profile.prompt_id
SET profile.review_rationale = reviewed.review_rationale;

DROP TEMPORARY TABLE IF EXISTS tmp_reviewed_prompt_rationales;
