INSERT INTO tmp_reviewed_prompt_rationales (prompt_id, review_rationale) VALUES
    ('prompt-a-1', '질문은 학습자가 저녁 식사 후 보통 하는 행동을 묻는다. 초급 답변이 단순한 활동 하나에 그치지 않도록 다른 단계, 시점 또는 이유와 같은 독립적인 세부 내용 하나가 필요하다.'),
    ('prompt-a-2', '두 절은 빠른 식사를 만드는 상황이나 시점과 보통 선택하는 식사를 직접 요구한다. 이 두 가지 구체적인 초급 수준 요소만으로도 충분한 답변이 된다.'),
    ('prompt-a-3', '표현이 보통 주말 활동을 폭넓게 묻고 있으므로, 핵심 행동 외에 다른 활동, 시점, 장소 또는 동기에 관한 별도의 세부 내용 하나가 필요하다.'),
    ('prompt-a-4', '학습자는 퇴근 후 보통 하는 행동을 말하고 그것이 즐거운 이유를 설명해야 한다. 행동과 이유로 이루어진 구조가 이 초급 질문에 충분한 깊이를 제공한다.'),
    ('prompt-b-1', '질문은 직장이나 학교에서 반복되는 어려움과 학습자가 이를 처리하는 방법을 명시적으로 묻는다. 따라서 요구된 문제와 해결 방법만으로도 완전한 중급 답변이 된다.'),
    ('prompt-b-2', '특정 도시를 방문하고 싶다는 내용이 미래의 목표를 제시하고, 그곳에서 하고 싶은 활동이 계획을 제시한다. 두 절에서 요구하는 내용만으로 충분하므로 추가 깊이는 필수가 아니다.'),
    ('prompt-b-3', '질문은 올해 만들고 싶은 습관의 목표와 그 중요성에 대한 설명을 요구한다. 습관을 만드는 계획은 유용하지만 직접 요구된 내용은 아니다.'),
    ('prompt-b-4', '원하는 여행의 종류가 미래의 목표이고, 준비 방법이 계획이다. 이 두 가지는 명시적이고 서로 독립적인 의무 사항이므로 추가 항목은 필요하지 않다.'),
    ('prompt-b-5', '질문은 개선하고 싶은 목표와 연습 방법을 직접 요구하며, 이는 목표와 계획으로 나타난다. 두 요소가 함께 중급 수준에 충분한 전개를 제공한다.'),
    ('prompt-balance-01', '소셜 미디어가 일상생활을 어떻게 바꾸었는지 설명하려면 과거와 현재의 상태가 필요하고, 두 번째 절에서는 그 변화가 대체로 긍정적인지에 대한 판단을 요구한다. 이 세 단위로 충분한 깊이가 제공된다.'),
    ('prompt-balance-02', '표현이 소셜 미디어의 이점, 단점, 그리고 학습자의 견해를 명시적으로 요구한다. 균형 잡힌 답변의 세 측면이 모두 필요하며, 이 자체로 충분한 깊이가 형성된다.'),
    ('prompt-balance-03', '학습자는 소셜 미디어가 사람들에게 미친 영향을 설명하고 그 영향이 대체로 좋은지 판단해야 한다. 이 고급 수준에서는 폭넓은 영향에 대한 주장을 뒷받침할 예시나 설명 하나도 필요하다.'),
    ('prompt-balance-04', '소셜 미디어가 사람들에게 도움을 준 정도가 해를 끼친 정도보다 큰지 판단하려면 도움이 된 측면과 해로운 측면을 비교하고, 비교에 대한 의견을 밝히며, 명시적인 이유 절에 답해야 한다. 추가 항목은 필요하지 않다.'),
    ('prompt-balance-05', '답변은 소셜 미디어 이전과 이후에 사람들이 생활하거나 소통한 방식을 대조한 다음 전체적인 의견을 제시해야 하므로, 서로 독립적인 세 가지 필수 요소가 있다.'),
    ('prompt-balance-06', '질문은 원격 근무가 일상생활을 어떻게 바꾸었는지와 그 변화가 대체로 긍정적인지를 묻는다. 따라서 이전과 현재의 대조와 평가적 입장이 필요하며, 이 의무 사항만으로 충분하다.'),
    ('prompt-balance-07', '원격 근무의 이점과 단점이 학습자의 견해와 함께 직접 요구된다. 따라서 세 가지 필수 항목만으로도 충분히 전개된 균형 잡힌 답변이 보장된다.'),
    ('prompt-balance-08', '질문은 원격 근무가 사람들에게 영향을 준 방식과 그 영향이 대체로 좋은지에 대한 판단을 요구한다. 이처럼 폭넓은 고급 수준의 주장에는 독립적인 예시나 이유 하나가 적절하다.'),
    ('prompt-balance-09', '도움이 되었는지 해를 끼쳤는지를 비교하려면 원격 근무의 긍정적인 측면과 부정적인 측면을 비교하고, 어느 쪽이 더 강한지 선택하며, 그 이유를 설명해야 한다. 이 네 가지 요구 사항이면 충분하다.'),
    ('prompt-balance-10', '원격 근무가 생활하거나 소통하는 방식을 어떻게 바꾸었는지 설명하려면 이전 상황과 현재 상황을 대조해야 하고, 마지막 절에서는 전체적인 의견을 요구한다. 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-balance-11', '학습자는 교육에서 인공지능이 등장하기 전과 후의 일상생활을 설명하고 그 변화가 대체로 긍정적인지 판단해야 한다. 따라서 실질적으로 요구되는 세 단위가 있다.'),
    ('prompt-balance-1101', '질문은 무인 계산대의 이점, 단점, 그리고 학습자 자신의 견해를 명시적으로 요구한다. 이 세 가지 독립적인 요소가 고급 답변에 필요한 깊이를 충족한다.'),
    ('prompt-balance-1102', '지문은 개방형 사무실의 양면을 설명하도록 직접 요구하므로 도움이 되는 측면과 해로운 측면이 필요하고, 마지막 지시에서는 전체적인 의견을 요구한다. 더 추가할 내용은 필수가 아니다.'),
    ('prompt-balance-1103', '재사용 포장 규정의 강점과 약점은 장점과 단점에 해당하며, 어느 쪽이 더 강한지 결정하는 내용이 의견을 제시한다. 요구된 분석의 모든 부분이 필요하다.'),
    ('prompt-balance-1104', '구독 서비스는 학습자가 견해를 제시하기 전에 이점과 단점을 모두 다루어야 한다. 따라서 명시적인 세 항목만으로도 충분히 전개된 답변이 된다.'),
    ('prompt-balance-1105', '질문은 온라인 청원의 양면을 설명하고 의견을 제시하라고 하므로, 도움이 되는 측면, 해로운 측면, 최종 판단이 모두 필수이며 이 세 가지로 충분하다.'),
    ('prompt-balance-1106', '학습자는 스마트 홈 기기의 강점과 약점을 밝히고 어느 쪽이 더 강한지 결정해야 한다. 따라서 양면과 의견이 모두 직접 요구되며 추가적인 깊이 의무는 없다.'),
    ('prompt-balance-1107', '학교 순위는 이점, 단점, 그리고 학습자의 견해를 통해 평가해야 한다. 이 세 가지 독립적으로 요구된 요소가 고급 수준에 충분한 깊이를 제공한다.'),
    ('prompt-balance-1108', '질문은 현금 없는 학교 식당의 양면을 명시적으로 설명하도록 하므로 도움이 되는 측면과 해로운 측면이 필요하고, 이어서 학습자의 전체적인 판단을 요구한다. 이 요구 사항만으로도 충분히 실질적이다.'),
    ('prompt-balance-1109', '반려동물 친화적 사무실의 강점과 약점을 논의하고 어느 쪽이 더 강한지 선택하면 장점, 단점, 의견이 직접 형성된다. 따라서 선택적인 항목을 반드시 추가할 필요는 없다.'),
    ('prompt-balance-1110', '질문은 관광세의 이점과 단점에 더해 개인적인 견해를 명시적으로 요구한다. 따라서 균형 잡힌 의견의 세 요소가 모두 필수이며 충분하다.'),
    ('prompt-balance-1111', '디지털 교과서는 도움이 되는 측면과 해로운 측면을 모두 고려해야 하고, 학습자는 의견을 밝혀야 한다. 명시적인 세 부분의 과제에 추가로 요구되는 깊이는 없다.'),
    ('prompt-balance-1112', '지역 보안 카메라는 강점과 약점, 그리고 어느 쪽이 더 강한지에 대한 판단을 통해 다루어진다. 따라서 장점, 단점, 의견이 모두 직접적이고 충분한 의무 사항이다.'),
    ('prompt-balance-1113', '질문은 식품 유통기한 표시의 이점과 단점을 모두 제시한 뒤 견해를 밝히도록 하므로, 필수적인 균형 구조 자체가 충분한 깊이를 제공한다.'),
    ('prompt-balance-1114', '학습자는 인공지능 고객 서비스의 유익한 측면과 해로운 측면을 설명하고 의견을 제시해야 하므로, 서로 독립적인 세 가지 단위가 필요하며 필수적인 추가 내용은 없다.'),
    ('prompt-balance-1115', '자전거 공유 시스템의 강점과 약점이 양쪽 측면을 제공하고, 어느 쪽이 더 강한지 선택하는 부분이 의견을 제공하므로, 이 완결된 구조에는 추가 항목이 필요하지 않다.'),
    ('prompt-balance-1116', '공유 업무 공간은 이점, 단점, 학습자의 견해를 통해 평가해야 하며, 명시적으로 요구된 이 세 요소만으로도 이 고급 질문에 충분하다.'),
    ('prompt-balance-1117', '질문은 주 4일 근무제의 유익한 측면과 해로운 측면을 모두 제시하고 최종 의견을 밝히도록 하므로, 균형 잡힌 의견의 세 항목이 모두 필요하며 이미 충분한 깊이를 보장한다.'),
    ('prompt-balance-1118', '친구 간 위치 공유는 강점과 약점을 통해 분석한 뒤 어느 쪽이 더 강한지 판단해야 하므로, 필수적인 세 항목만으로 충분하다.'),
    ('prompt-balance-1119', '질문은 도시의 전동 킥보드의 이점과 단점 및 전반적인 견해를 직접 요구하므로, 균형 잡힌 세 부분의 답변에 추가 깊이 항목은 필요하지 않다.'),
    ('prompt-balance-1120', '실시간 판매 방송의 유익한 측면과 해로운 측면을 모두 설명한 뒤 학습자가 의견을 제시해야 하므로, 필수적인 의미 단위 세 개로 충분하다.'),
    ('prompt-balance-1121', '재사용 컵 보증금 제도의 강점과 약점 및 어느 쪽이 더 강한지에 대한 판단이 모두 요구되므로, 그 결과인 세 가지 요구 사항으로 충분하다.'),
    ('prompt-balance-1122', '여행용 번역 애플리케이션은 이점과 단점을 통해 논의한 뒤 학습자의 견해를 제시해야 하므로, 직접적인 필수 내용만으로 이미 충분한 깊이를 제공한다.'),
    ('prompt-balance-1123', '밀키트 서비스의 양쪽 측면을 설명하라는 지시로 이점과 단점이 필수가 되며, 요구된 의견이 충분히 전개된 답변을 완성한다.'),
    ('prompt-balance-1124', '개인 정보 보상 프로그램은 강점, 약점, 어느 쪽이 더 강한지에 대한 판단의 관점에서 제시되므로, 양쪽 측면과 학습자의 전반적인 판단이 직접적으로 모두 요구된다.'),
    ('prompt-balance-1125', '학습자는 자동 출석 시스템의 이점과 단점을 밝힌 뒤 견해를 제시해야 하므로, 명시적인 세 부분만으로 충분하며 선택적 내용은 필수가 아니다.'),
    ('prompt-balance-1126', '사무실의 자유 좌석제는 유익한 측면과 해로운 측면을 모두 설명하고 전반적으로 평가해야 하므로, 이점, 단점, 의견이 필수 항목으로 충분하다.'),
    ('prompt-balance-1127', '질문은 두 번째 화면을 함께 보는 습관의 강점과 약점 및 어느 쪽이 더 강한지에 대한 판단을 요구하므로, 필수적인 세 가지 분석 요소만으로 이미 충분한 깊이를 만든다.'),
    ('prompt-balance-12', '교육에서 인공지능의 이점과 단점을 학습자의 견해와 함께 모두 명시적으로 요구하므로, 완전한 균형 구조에 추가 항목은 필요하지 않다.'),
    ('prompt-balance-13', '답변은 교육에서 인공지능이 사람들에게 미친 영향을 밝히고 그 영향이 대체로 긍정적인지 판단해야 하므로, 고급 수준에 충분하려면 뒷받침하는 예시나 이유가 하나 필요하다.'),
    ('prompt-balance-14', '질문은 교육용 인공지능이 사람들에게 도움을 준 정도가 해를 끼친 정도보다 큰지와 그 이유를 요구하므로, 양쪽 측면을 비교하고 비교 결과를 밝히며 근거를 설명해야 한다. 이는 이미 충분한 깊이에 해당한다.'),
    ('prompt-balance-15', '학습자는 인공지능이 교육에 들어오기 전과 후에 사람들이 생활하거나 관계를 맺은 방식을 대조한 뒤 전반적인 의견을 제시해야 하므로, 필수 내용만으로 충분한 깊이가 나온다.'),
    ('prompt-balance-16', '온라인 쇼핑이 일상생활을 어떻게 변화시켰는지 설명하려면 이전 상태와 현재 상태가 필요하고, 두 번째 절은 그 변화에 대한 판단을 요구하므로, 이 세 가지 의무만으로 충분하다.'),
    ('prompt-balance-17', '질문은 온라인 쇼핑의 이점, 단점, 학습자의 견해를 직접 요구하므로, 균형 잡힌 의견의 세 항목이 모두 필수이며 이미 실질적인 내용을 이룬다.'),
    ('prompt-balance-18', '학습자는 온라인 쇼핑이 사람들에게 영향을 미친 방식을 설명하고 그 영향이 대체로 긍정적인지 판단해야 하므로, 이 폭넓은 고급 수준의 판단을 전개하려면 독립적인 뒷받침 내용이 하나 필요하다.'),
    ('prompt-balance-19', '온라인 쇼핑이 사람들에게 도움을 준 정도가 해를 끼친 정도보다 큰지 판단하려면 양쪽 측면, 비교에 근거한 의견, 명시적으로 요구된 이유가 필요하므로, 이를 합치면 추가 깊이는 필요하지 않다.'),
    ('prompt-balance-20', '질문은 온라인 쇼핑이 생활하거나 관계를 맺는 방식을 과거와 현재에 어떻게 변화시켰는지와 전반적인 의견을 요구하므로, 직접적인 의미 단위 세 개로 충분한 깊이를 제공한다.'),
    ('prompt-balance-21', '학습자는 일상적인 스마트폰 사용이 일반화되기 전과 후의 사람들의 삶을 대조하고 그 변화가 대체로 긍정적인지 평가해야 하므로, 이 요구 사항만으로 충분하다.'),
    ('prompt-balance-22', '일상적인 스마트폰 사용은 이점, 단점, 학습자의 견해를 통해 명시적으로 제시되므로, 필수적인 세 부분의 균형 잡힌 답변만으로도 깊이의 목표를 충족한다.'),
    ('prompt-balance-23', '질문은 일상적인 스마트폰 사용이 사람들에게 미친 영향과 그 영향이 대체로 긍정적인지에 대한 판단을 요구하므로, 고급 답변을 뒷받침하려면 예시나 설명하는 이유가 하나 필요하다.'),
    ('prompt-balance-24', '도움을 준 정도와 해를 끼친 정도를 비교하려면 일상적인 스마트폰 사용의 긍정적·부정적 영향, 전반적인 판단, 어느 쪽이 더 강한지에 대한 설명이 필요하므로, 추가 항목은 필요하지 않다.'),
    ('prompt-balance-25', '답변은 일상적인 스마트폰 사용 전후에 생활하거나 관계를 맺는 방식이 어떻게 달랐는지 보여 준 뒤 전반적인 의견을 밝혀야 하므로, 필수 내용 세 단위로 충분한 깊이가 나온다.'),
    ('prompt-balance-26', '현금 없는 결제는 학습자가 견해를 제시하기 전에 이점과 단점을 통해 논의해야 하므로, 직접 요구된 세 부분만으로 충분하다.'),
    ('prompt-balance-27', '현금 없는 결제가 일상생활을 어떻게 변화시켰는지 설명하려면 이전 상태와 현재 상태가 필요하고, 그 변화가 대체로 긍정적인지 판단하는 내용이 필수 의견을 더하므로, 이 정도면 충분하다.'),
    ('prompt-balance-28', '학습자는 현금 없는 결제가 사람들에게 미친 영향을 밝히고 그 영향이 대체로 긍정적인지 판단해야 하므로, 고급 답변이 폭넓은 주장에 머물지 않도록 독립적인 뒷받침 내용이 하나 필요하다.'),
    ('prompt-balance-29', '현금 없는 결제가 사람들에게 이로운지 해로운지를 판단하려면 양쪽 측면, 비교에 근거한 입장, 그리고 요구된 이유가 모두 필요하므로, 필수 구조만으로도 충분한 깊이가 있다.'),
    ('prompt-balance-30', '장점과 단점을 모두 고려하라는 표현은 현금 없는 결제의 양쪽 측면을 필수로 하며, 질문은 전반적인 의견도 직접 요구하므로 보충 내용이 필요하지 않다.'),
    ('prompt-balance-31', '학습자는 짧은 형식의 동영상의 이점과 단점뿐 아니라 자신의 견해도 제시해야 하므로, 균형 잡힌 의견을 구성하는 세 요소가 명확하고 충분하다.'),
    ('prompt-balance-32', '질문은 짧은 형식의 동영상이 등장하기 전과 후의 일상생활을 대조하고 그 변화가 대체로 긍정적인지 판단하도록 요구하므로, 필수 내용의 깊이가 충분하다.'),
    ('prompt-balance-33', '학습자는 짧은 형식의 동영상이 사람들에게 미친 영향을 설명하고 그것이 대체로 좋은지 평가해야 하므로, 폭넓은 주제와 높은 난도를 고려할 때 예시나 이유를 하나 추가하는 것이 적절하다.'),
    ('prompt-balance-34', '질문은 짧은 형식의 동영상이 사람들에게 이로운지 해로운지, 그리고 그 이유를 직접 요구하므로, 양쪽 측면과 비교에 근거한 판단 및 그 이유만으로도 충분하다.'),
    ('prompt-balance-35', '짧은 형식의 동영상에 대한 전반적인 의견은 장점과 단점을 모두 명시적으로 고려해야 하므로, 양쪽 측면과 최종 입장이 완전한 답변을 구성한다.'),
    ('prompt-balance-36', '음식 배달 앱은 이점, 단점, 그리고 학습자의 견해를 통해 평가해야 하므로, 명시적인 균형 구조만으로도 충분한 깊이를 제공한다.'),
    ('prompt-balance-37', '질문은 음식 배달 앱이 일상생활을 어떻게 변화시켰는지와 그 변화가 대체로 긍정적인지를 묻고 있으므로, 과거와 현재의 상태 및 의견이라는 세 요소로 충분하다.'),
    ('prompt-balance-38', '과제는 음식 배달 앱이 사람들에게 미친 영향과 그 영향이 대체로 좋은지에 대한 판단을 직접 요구하므로, 고급 답변을 발전시키려면 독립적인 예시나 설명을 하나 추가해야 한다.'),
    ('prompt-balance-39', '음식 배달 앱이 사람들에게 어떻게 이롭고 해로운지 비교하려면 긍정적 측면과 부정적 측면, 어느 쪽이 더 큰지에 대한 결론, 그리고 명시적으로 요구된 설명이 필요하므로 깊이의 부족이 없다.'),
    ('prompt-balance-40', '음식 배달 앱에 대한 학습자의 전반적인 의견은 장점과 단점을 모두 고려해야 하므로, 이 세 요소가 직접적이고 충분한 필수 내용이 된다.'),
    ('prompt-balance-41', '질문은 온라인 리뷰의 이점과 단점 및 학습자의 견해를 명시적으로 요구하므로, 균형 잡힌 답변을 구성하는 세 가지 필수 요소만으로도 충분한 깊이가 있다.'),
    ('prompt-balance-42', '온라인 리뷰가 일상생활을 어떻게 변화시켰는지 설명하려면 이전 상태와 현재 상태가 필요하며, 그 변화가 대체로 긍정적인지 판단하는 내용이 세 번째 필수 요소가 된다.'),
    ('prompt-balance-43', '답변은 온라인 리뷰가 사람들에게 영향을 미친 방식을 밝히고 그 영향이 대체로 좋은지 평가해야 하므로, 충분히 발전된 고급 답변을 위해 별도의 뒷받침 내용을 하나 추가해야 한다.'),
    ('prompt-balance-44', '학습자는 온라인 리뷰가 사람들에게 어떻게 이롭고 해로운지 따져 보고, 어느 영향이 더 큰지 밝히며, 그 이유에 답해야 하므로, 이 네 가지 직접적 요구만으로 선택적 심화 내용이 필요하지 않다.'),
    ('prompt-balance-45', '표현상 온라인 리뷰에 대한 전반적인 의견을 제시하면서 장점과 단점을 모두 고려해야 하므로, 세 가지 필수 요소가 과제의 내용을 완전히 담는다.'),
    ('prompt-balance-46', '착용형 기기는 이점, 단점, 그리고 학습자의 견해를 통해 논의해야 하며, 이 세 가지 명시적 요구만으로도 적절한 수준의 고급 답변이 보장된다.'),
    ('prompt-balance-47', '질문은 착용형 기기가 등장하기 전과 후의 일상생활 및 그 변화가 대체로 긍정적인지에 대한 판단을 요구하므로, 그에 따른 세 부분의 성찰만으로도 깊이가 충분하다.'),
    ('prompt-balance-48', '학습자는 착용형 기기가 사람들에게 미친 영향을 설명하고 그 영향이 대체로 좋은지 판단해야 하므로, 고급 수준에서는 독립적인 예시나 설명을 하나 추가해야 한다.'),
    ('prompt-balance-49', '착용형 기기가 사람들에게 이로운지 해로운지 판단하려면 긍정적 측면과 부정적 측면을 고려하고, 입장을 정하며, 그 이유를 설명해야 하므로 이미 완전한 분석이 된다.'),
    ('prompt-balance-50', '착용형 기기에 대한 전반적인 의견은 장점과 단점을 모두 고려하여 형성해야 하므로, 균형 잡힌 답변의 세 요소가 모두 필요하고 충분하다.'),
    ('prompt-c-1', '학습자는 기술 변화 전후의 관계 형성을 대조하고 그 변화가 대체로 긍정적인지 판단해야 하므로, 이 세 가지 중요한 요구만으로도 고급 수준에 적절한 깊이가 제공된다.'),
    ('prompt-c-2', '질문은 성공한 기업의 사회적 책임에 대한 입장을 요구하지만 여러 뒷받침 항목을 별도로 요구하지 않는다. 구체적인 이유, 예시 또는 결과 중 하나면 입장을 충분히 뒷받침한다.'),
    ('prompt-c-3', '변화한 신념을 설명하려면 이전의 신념, 현재의 신념, 그리고 변화의 원인이라는 명시적으로 요구된 내용이 필요하므로, 이 세 가지 독립적인 성찰 요소만으로도 충분하다.'),
    ('prompt-general-01', '학습자는 자주 사용하는 유용한 앱을 설명하고 그것이 왜 의미 있는지 밝혀야 하므로, 구체적인 설명과 의미를 뒷받침하는 이유가 두 조항을 모두 충족한다.'),
    ('prompt-general-02', '표현상 유용한 앱에서 눈에 띄는 점을 밝히고 설명하는 것만 직접 요구하므로, 내용이 빈약한 중급 설명을 피하려면 독립적인 이유, 용도, 또는 예시를 하나 추가해야 한다.'),
    ('prompt-general-03', '유용한 앱을 소개하려면 설명 정보가 필요하고, 이를 추천하면서 그 이유를 설명하려면 추천에 대한 판단과 그 이유가 필요하므로, 이 세 가지 요구만으로 충분하다.'),
    ('prompt-general-04', '학습자는 자주 사용하는 앱의 특별한 점과 그것이 계속 기억에 남는 이유를 설명해야 하므로, 차별적인 세부 내용과 기억에 남는 이유가 질문을 직접 완성한다.'),
    ('prompt-general-05', '앱에 대해 말하려면 구체적인 설명이 필요하고, 그것이 학습자의 삶에서 왜 중요한지 설명하려면 이유가 필요하므로, 이 두 가지 직접적 조항만으로도 중급 수준에 적절한 깊이가 제공된다.'),
    ('prompt-general-06', '답변은 학습자의 마을에서 좋아하는 장소를 밝히고, 그곳을 설명하며, 개인적으로 어떤 의미가 있는지 설명해야 하므로, 이 세 가지 필수 요소만으로도 발전된 답변이 된다.'),
    ('prompt-general-07', '학습자는 지역의 장소를 밝히고 그곳에서 눈에 띄는 점을 말해야 하므로, 이 두 가지 구체적인 내용만으로도 별도로 요구된 설명 없이 중급 질문에 충분히 답할 수 있다.'),
    ('prompt-general-08', '장소를 밝혀야 하며, 학습자는 추천을 제시하고 그 근거를 설명해야 한다. 장소, 추천 의견, 이유가 모든 직접적인 의무 내용을 충족한다.'),
    ('prompt-general-09', '질문은 마을의 장소, 그곳을 특별하게 만드는 점, 기억에 남는 이유를 요구하므로 장소, 차별화되는 세부 내용, 기억에 남은 이유가 충분한 깊이를 제공한다.'),
    ('prompt-general-10', '학습자는 마을에서 좋아하는 장소를 밝히고 설명한 뒤, 그 장소가 개인적으로 중요한 이유를 설명해야 한다. 이는 추가적인 깊이가 필요 없는 세 가지 직접적인 의미 단위로 구성된다.'),
    ('prompt-general-11', '교사 또는 멘토의 영향력은 질문에서 선택을 위한 전제의 일부이지, 학습자가 직접 말하도록 요구받는 별도의 결과가 아니다. 인물에 대한 설명과 그 인물이 중요한 이유가 필수 내용이며, 구체적인 영향력은 관련성이 매우 높은 선택적 결과로 남는다.'),
    ('prompt-general-1101', '축제를 설명하고 개인적으로 중요한 의미를 설명해야 하지만, 폭넓은 고급 질문이므로 설명을 발전시키기 위해 독립적인 사건, 장소, 감정 또는 사례 하나를 추가하는 것이 적절하다.'),
    ('prompt-general-1102', '학습자는 매일 사용하는 책상 물건을 설명하고 그것이 의미 있게 느껴지는 이유를 설명해야 한다. 고급 수준의 깊이를 위해 그 물건의 사용, 영향 또는 관련 경험에 대한 별도의 설명 하나가 적절하다.'),
    ('prompt-general-1103', '버스 노선은 눈에 띄는 점을 중심으로 설명해야 하며, 학습자는 그 노선이 기억에 남은 이유를 설명해야 한다. 독립적인 배경, 경험 또는 감정 하나가 이 고급 기억 질문에 충분한 깊이를 더한다.'),
    ('prompt-general-1104', '간직하고 있는 선물을 설명하고 그것이 중요한 이유를 설명해야 하며, 고급 개인 설명을 짧은 두 절 이상으로 발전시키려면 독립적인 기억, 감정, 사용 경험 또는 결과 하나가 필요하다.'),
    ('prompt-general-1105', '방의 한쪽 구석을 특정하고 설명한 뒤, 그것이 개인적으로 어떤 의미인지 설명해야 한다. 이 세 가지 독립적인 필수 요소만으로도 충분히 발전된 답변이 된다.'),
    ('prompt-general-1106', '지역의 다리 또는 보행로를 장소로 특정하고, 눈에 띄는 점을 중심으로 설명하며, 기억에 남은 이유와 연결해야 한다. 이 세 가지 의무만으로 충분하다.'),
    ('prompt-general-1107', '공부할 때 듣는 재생 목록을 설명하고 그 중요성을 설명해야 한다. 이 고급 개인 설명을 발전시키려면 사용 사례, 감정, 영향 또는 시점에 대한 독립적인 예시 하나가 필요하다.'),
    ('prompt-general-1108', '스스로 배운 요리에 대해 이야기하고 그 요리가 지니는 의미를 설명해야 하며, 고급 답변을 구체화하기 위해 별도의 요리 행동, 기억, 감정 또는 결과 하나를 추가하는 것이 적절하다.'),
    ('prompt-general-1109', '카페를 장소로 특정하고, 두드러지는 특징을 중심으로 설명하며, 그곳이 계속 기억에 남는 이유와 연결해야 한다. 이 세 가지 필수 부분만으로도 충분한 깊이를 제공한다.'),
    ('prompt-general-1110', '가족사진을 설명하고 개인적으로 중요한 이유를 설명해야 하지만, 고급 회상에 충분한 내용을 더하려면 독립적인 기억, 감정, 시점 또는 결과 하나가 필요하다.'),
    ('prompt-general-1111', '자주 의지하는 휴대전화 기능을 설명하고 그 중요성을 설명해야 한다. 고급 수준으로 발전시키려면 그 기능의 독립적인 사용 사례, 이점, 예시 또는 해결하는 문제 하나가 필요하다.'),
    ('prompt-general-1112', '자주 가지고 다니는 수첩을 설명하고 그 의미를 설명해야 하며, 고급 답변을 완전히 발전시키려면 별도의 사용 사례, 상황, 기억 또는 영향 하나가 필요하다.'),
    ('prompt-general-1113', '책상 위 물건을 구체적으로 설명하고 그것이 중요한 이유를 설명해야 한다. 사용, 놓인 위치, 기억 또는 감정에 대한 독립적인 내용 하나가 이 고급 질문에서 기대되는 깊이를 더한다.'),
    ('prompt-general-1114', '봉사 행사에 참여했다는 내용은 이미 전제로 제시되어 있으므로, 학습자에게 행동을 설명하도록 직접 요구하는 것은 아니다. ACTION을 선택 사항으로 두면, 폭넓은 C수준 행사 회고에 적절한 독립적인 행동, 결과, 감정, 사례, 장소 또는 시점 세부 정보 하나가 필요하다.'),
    ('prompt-general-1115', '주제를 설명하고 그것이 계속 중요한 이유를 설명해야 하며, 고급 답변을 발전시키려면 별도의 사례, 대화 활동, 감정 또는 영향 하나가 필요하다.'),
    ('prompt-general-1116', '오래된 재킷 또는 코트를 설명하고 그 의미를 설명해야 한다. 충분한 고급 답변을 위해 독립적인 착용 경험, 감정, 기억 또는 영향 하나를 추가하는 것이 적절하다.'),
    ('prompt-general-1117', '시장 가판대를 장소로 특정하고 설명한 뒤, 그곳을 방문하는 것이 의미 있게 느껴지는 이유와 연결해야 한다. 이 세 가지 필수 요소만으로도 완전한 답변이 된다.'),
    ('prompt-general-1118', '비 오는 날 특히 인상적인 소리를 설명하고 그 소리가 기억에 남은 이유를 설명해야 한다. 고급 수준의 깊이를 위해 독립적인 감정, 상황, 배경 또는 영향 하나가 필요하다.'),
    ('prompt-general-1119', '기억에 남는 창밖 풍경을 설명하고 그 중요성을 설명해야 하며, 고급 답변을 완성하려면 독립적인 위치, 감정, 기억 또는 시점 세부 정보 하나가 필요하다.'),
    ('prompt-general-1120', '지역 사회 수업을 설명하고 개인적으로 어떤 의미인지 설명해야 한다. 이 고급 수준의 경험이 유용했던 이유를 뒷받침하려면 독립적인 이점, 활동, 사례 또는 감정 하나가 필요하다.'),
    ('prompt-general-1121', '식물을 특정하고 설명한 뒤, 그것이 개인적으로 중요한 이유를 설명해야 한다. 이 세 가지 명시적인 요소만으로도 C수준 질문에 충분한 깊이를 제공한다.'),
    ('prompt-general-1122', '여전히 좋아하는 어린 시절 간식을 고르고, 그것을 설명하며, 지금도 개인적으로 중요한 이유를 말하도록 요구하므로 추가적인 선택적 뒷받침 내용은 필요하지 않다.'),
    ('prompt-general-1123', '학습자는 익숙한 가까운 길 또는 거리를 고르고 설명한 뒤, 그것이 지니는 의미를 설명해야 한다. 이러한 구별되는 의무만으로 완전한 C수준 답변이 된다.'),
    ('prompt-general-1124', '질문은 집에서 만드는 요리를 고르고 설명하며, 그 요리가 기억에 남은 이유를 설명하도록 직접 요구한다. 따라서 이미 세 가지 독립적인 의미 단위를 제공한다.'),
    ('prompt-general-1125', '완전한 답변은 중고로 구매한 물건의 이름을 밝히고 설명하며, 그것이 중요한 이유를 설명해야 한다. 따라서 필수 내용 자체가 충분히 발전되어 있다.'),
    ('prompt-general-1126', '지름길을 특정하고 설명한 뒤, 그것이 개인적으로 어떤 의미인지 설명해야 한다. 이러한 명시적인 내용만으로도 요구된 C수준 깊이를 충족한다.'),
    ('prompt-general-12', '학습자는 영향을 준 교사 또는 멘토를 특정하고, 그 사람에게서 두드러지는 점을 말해야 한다. 영향력이나 사례와 같은 추가적인 독립 요소 하나가 빈약한 특정 답변이 되는 것을 막는다.'),
    ('prompt-general-13', '질문은 학습자에게 교사 또는 멘토를 소개하고 자신이 무엇을 배웠는지 말하도록 요구한다. 따라서 인물과 학습 결과만으로도 충분한 B수준 답변이 된다.'),
    ('prompt-general-14', '답변은 영향력 있는 인물을 밝히고, 무엇이 특별했는지 설명하며, 그 경험이 기억에 남아 있는 이유를 제시해야 한다. 이 절들 외에 추가적인 선택 내용은 필요하지 않다.'),
    ('prompt-general-15', '교사 또는 멘토를 소개하고 설명해야 하며, 학습자는 그 사람이 자신의 삶에서 중요한 이유를 충분한 필수 깊이로 설명해야 한다.'),
    ('prompt-general-16', '답변은 추천할 만한 취미를 선택해 설명하고, 그 취미가 개인적으로 어떤 의미가 있는지 설명해야 한다. 추천 맥락과 설명만으로도 이미 충분한 내용이 구성된다.'),
    ('prompt-general-17', '학습자는 취미 하나를 선택하고 그 취미에서 두드러지는 점을 설명하여 추천해야 한다. 이 두 가지 명시적 요소만으로도 B단계 질문에 충분히 답할 수 있다.'),
    ('prompt-general-18', '질문이 학습자가 어떤 취미를 추천하는지와 그 이유를 직접 묻고 있으므로, 추천 대상의 선택과 이를 뒷받침하는 이유만으로 과제가 완성되며 추가적인 깊이는 필요하지 않다.'),
    ('prompt-general-19', '답변은 취미를 밝히고, 무엇이 특별한지 말하며, 왜 기억에 남는지 설명해야 한다. 이는 답변 전개에 필요한 세 가지 요소이다.'),
    ('prompt-general-20', '학습자는 취미에 대해 말하고 그것이 자신의 삶에서 중요한 이유를 설명해야 한다. 취미의 식별과 설명은 이유와 별개의 요소로 제시되어야 한다.'),
    ('prompt-general-21', '기억에 남는 일 자체를 설명하고 그 일이 계속 의미 있는 이유를 설명해야 한다. 이 두 가지 실질적 의무만으로 B단계 답변에 충분하다.'),
    ('prompt-general-22', '기억에 남는 일과 두드러지는 점에 대한 말하기는 하나의 설명 요소로 충족될 수 있다. 따라서 B단계 깊이를 위해 독립적인 이유, 느낌, 결과, 시점 또는 장소 하나가 필요하다.'),
    ('prompt-general-23', '학습자는 구체적인 정보로 기억에 남는 일을 소개하고 그것이 개인적으로 어떤 의미가 있는지 설명해야 한다. 따라서 필수 설명과 이유만으로 충분하다.'),
    ('prompt-general-24', '질문은 기억에 남는 일에서 무엇이 특별한지와 왜 계속 기억에 남는지를 별도로 묻는다. 따라서 세부 내용과 이유를 제시하면 B단계 과제가 완성된다.'),
    ('prompt-general-25', '기억에 남는 일을 설명하고 그것이 학습자의 삶에서 중요한 이유를 설명하면 서로 독립적인 두 가지 필수 요소가 충족되므로, 선택 요소를 반드시 추가할 필요는 없다.'),
    ('prompt-general-26', '학습자는 좋아하는 작은 가게를 선택해 설명하고 그것이 개인적으로 중요한 이유를 설명해야 한다. 이 내용만으로도 충분히 발전된 선호 답변이 된다.'),
    ('prompt-general-27', '답변은 작은 가게를 밝히고 그곳에 대해 말하며 추천하는 이유를 제시해야 한다. 따라서 추천은 명시적인 설명 내용으로 이미 뒷받침된다.'),
    ('prompt-general-28', '직접적인 의무는 그 가게에서 가장 좋아하는 부분을 선택하는 것이다. B단계 답변이 단순한 명칭에 그치지 않도록 그 선택을 뒷받침하는 독립적인 설명이나 예시 하나가 필요하다.'),
    ('prompt-general-29', '질문은 그 가게가 일상생활에서 중요한 이유를 직접 요구한다. 별개의 영향, 예, 일상적 이용, 시점 또는 느낌 하나를 제시하면 B단계 설명에 충분한 깊이가 생긴다.'),
    ('prompt-general-30', '학습자는 좋아하는 가게를 밝히고 구체적으로 요청된 기억에 남는 설명을 제시해야 한다. 이 두 가지 필수 요소만으로도 질문에 충분히 답할 수 있다.'),
    ('prompt-general-31', '완전한 답변은 유용한 웹사이트를 밝히고 설명하며, 그 웹사이트가 개인적으로 중요한 이유를 제시한다. 따라서 추가적인 깊이는 선택 사항이다.'),
    ('prompt-general-32', '학습자는 유용한 웹사이트의 이름을 말하고 그것에 대해 설명하며 추천하는 이유를 설명해야 한다. 따라서 의견의 핵심 부분은 이미 모두 필수 내용에 포함된다.'),
    ('prompt-general-33', '문자 그대로의 유일한 의무는 가장 좋아하는 기능을 선택하는 것이다. 따라서 그 선택을 넘어서는 이유, 활용 사례, 행동, 결과 또는 구체적인 세부 내용 하나가 필요하다.'),
    ('prompt-general-34', '학습자는 그 웹사이트가 일상생활에서 중요한 이유를 설명해야 한다. 별개의 결과, 예, 사용 방식, 시점에 관한 세부 내용 또는 기능 하나를 제시해야 B단계 설명이 일반적인 말에 그치지 않는다.'),
    ('prompt-general-35', '답변은 유용한 웹사이트를 밝히고 요청된 기억에 남는 세부 내용을 제시해야 한다. 이 정도면 필수 내용이 충분하므로 또 다른 선택 요소를 요구할 필요가 없다.'),
    ('prompt-general-36', '가족 전통을 설명하려면 반복되는 행동을 밝혀야 하며, 질문은 그 전통이 중요한 이유도 묻는다. 이 두 요소만으로도 그 일상적 활동을 충분히 전개할 수 있다.'),
    ('prompt-general-37', '학습자는 소중하게 여기는 가족 전통이 무엇을 포함하는지와 그것을 추천하는 이유를 설명해야 한다. 따라서 그 활동과 추천 이유만으로 B단계 과제가 완성된다.'),
    ('prompt-general-38', '질문은 가족 전통에서 가장 좋아하는 부분을 묻는다. 그 부분의 이름을 말하는 것에 더해 독립적인 이유, 행동, 느낌, 영향 또는 예시 하나가 필요하다.'),
    ('prompt-general-39', '전통이 일상생활에서 중요한 이유를 설명해야 한다. 별개의 실천 방식, 영향, 예, 시점에 관한 세부 내용 또는 느낌 하나를 제시하면 B단계에 적절한 단일 이유의 근거가 된다.'),
    ('prompt-general-40', '답변은 반복되는 가족 전통이 무엇을 포함하는지 설명하고 기억에 남는 세부 내용 하나를 포함해야 한다. 이는 서로 구별되는 두 가지 필수 요소이다.'),
    ('prompt-general-41', '학습자는 좋아하는 산책 장소를 선택하고 설명하며, 그 장소가 중요한 이유를 설명해야 한다. 필수적인 선호, 설명 및 중요성만으로도 충분하다.'),
    ('prompt-general-42', '답변은 산책 장소를 밝히고 그곳에 대해 말하며 추천하는 이유를 제시해야 한다. 따라서 추가적인 선택 깊이는 필요하지 않다.'),
    ('prompt-general-43', '직접적인 요구 사항은 산책 장소에서 가장 좋아하는 특징을 말하는 것이다. 그 선택을 전개하려면 독립적인 설명, 묘사, 느낌, 활동 또는 결과 하나가 필요하다.'),
    ('prompt-general-44', '학습자는 그 장소가 일상생활에서 중요한 이유를 설명해야 한다. 그 이유를 뒷받침하려면 별개의 산책 활용 방식, 영향, 예, 시간 또는 느낌 하나가 필요하다.'),
    ('prompt-general-45', '질문은 산책 장소를 밝히고 기억에 남는 묘사 세부 내용을 제시하도록 요구한다. 이 내용만으로도 충분한 B단계 답변이 구성된다.'),
    ('prompt-general-46', '완전한 답변은 자주 사용하는 가정용품의 이름과 특징을 말하고, 그것이 개인적으로 중요한 이유를 설명한다. 따라서 추가적인 선택 항목은 필요하지 않다.'),
    ('prompt-general-47', '학습자는 가정용품을 식별하여 설명하고, 그것을 추천하는 이유를 명시해야 한다. 추천 내용과 그 근거를 모두 분명하게 다루어야 한다.'),
    ('prompt-general-48', '자주 사용하는 물건에서 가장 좋아하는 특징을 말하는 것이 필수이다. B단계의 발전된 답변을 위해 별도의 이유, 용도, 결과, 예시 또는 세부 정보 하나가 필요하다.'),
    ('prompt-general-49', '질문은 해당 가정용품이 일상생활에서 중요한 이유를 묻는다. 그 이유를 뒷받침하는 독립적인 용도, 영향, 예시, 시점에 관한 세부 정보 또는 특징 하나가 필요하다.'),
    ('prompt-general-50', '학습자는 가정용품을 식별하고 요청된 기억에 남는 세부 정보를 제시해야 한다. 따라서 명시된 의무만으로도 충분한 B단계 내용이 구성된다.'),
    ('prompt-goal-01', '학습자는 올해 향상하고 싶은 기술의 이름을 말하고, 그 기술을 향상하기 위해 어떻게 노력할지 밝혀야 한다. 이 두 가지 명시적 단위가 B단계 과제를 완성한다.'),
    ('prompt-goal-02', '향상하고 싶은 기술을 설명하면 목표가 설정되고, 계획을 설명하면 두 번째 필수 단위가 충족된다. 따라서 추가적인 선택적 심화 내용은 필요하지 않다.'),
    ('prompt-goal-03', '질문은 향상하고 싶은 기술과 발전을 이루는 방법을 요구한다. 따라서 목표와 발전 계획이 필수 내용을 충족한다.'),
    ('prompt-goal-04', '학습자는 향상하고 있는 기술을 식별하고, 이를 위해 취할 단계를 제시해야 한다. 따라서 명시된 목표와 실행 가능한 계획만으로 이미 B단계 질문에 답할 수 있다.'),
    ('prompt-goal-05', '이 유형은 기술 향상 목표와 이를 추구하는 방법이 아니라 그 목표가 중요한 이유를 묻는다. 이 두 가지 필수 요소만으로 충분하다.'),
    ('prompt-goal-06', '답변은 학습자가 형성하고 싶은 습관과 이를 위해 어떻게 노력할지를 밝혀야 한다. 따라서 미래의 목표와 방법이 모두 명시된다.'),
    ('prompt-goal-07', '새로 형성하고 싶은 습관이 목표이고, 계획에 대한 요청된 설명이 별도의 의무이다. 따라서 필수 내용만으로 충분하다.'),
    ('prompt-goal-08', '학습자는 형성하고 싶은 습관의 목표를 식별하고, 어떻게 발전할지 설명해야 한다. 이로써 실질적인 B단계 단위 두 개가 제공된다.'),
    ('prompt-goal-09', '답변에는 형성하고 싶은 습관을 밝히고 이를 형성하기 위한 단계를 개괄하는 내용이 필요하다. 따라서 추가적인 선택 항목은 필수가 아니다.'),
    ('prompt-goal-10', '질문은 학습자가 형성하고 싶은 습관과 그 미래의 변화가 중요한 이유를 직접 묻는다. 따라서 목표와 이유만으로 답변이 완성된다.'),
    ('prompt-goal-11', '달성하려는 건강상의 결과와 이를 위해 노력하는 방법이 모두 명시적으로 요청된다. 따라서 B단계 답변에 충분한 내재적 깊이가 있다.'),
    ('prompt-goal-1101', '학습자는 수면 일정 개선 목표를 정하고, 이를 어떻게 실천할지 설명해야 한다. 따라서 목표와 방법만으로 질문의 요구를 충분히 충족한다.'),
    ('prompt-goal-1102', '매일 일기를 쓰는 것은 질문에 이미 제시되어 있다. 따라서 학습자에게는 그 목표를 반복하는 것이 아니라 계획과 지속 방법만 요구된다. 난이도 B에서 필수 계획 항목이 하나이므로, 독립적인 뒷받침 세부 정보 하나가 필요하다.'),
    ('prompt-goal-1103', '답변은 어떤 요리 능력을 향상해야 하는지 구체적으로 밝히고, 이를 향상하기 위한 단계를 제시해야 한다. 따라서 완전한 목표와 계획의 답변이 구성된다.'),
    ('prompt-goal-1104', '학습자는 디지털 파일 정리 목표를 밝히고, 이를 위해 어떻게 노력할지 설명해야 한다. 이 별도의 요구 사항들이 이미 B단계의 깊이를 제공한다.'),
    ('prompt-goal-1105', '회의에서 더 자신 있게 말하는 것은 질문에 이미 제시된 목표이므로 학습자가 독립적으로 제시해야 하는 내용이 아니다. 답변은 꾸준히 실천하기 위한 계획을 제시해야 하며, 별도의 상황, 장애물, 시점에 관한 세부 정보, 결과 또는 감정 하나가 적절한 B단계 깊이를 제공한다.'),
    ('prompt-goal-1106', '학습자는 밤에 화면을 사용하는 습관에서 원하는 변화를 식별하고, 이를 위한 단계를 개괄해야 한다. 따라서 개선 목표와 계획만으로 충분하다.'),
    ('prompt-goal-1107', '질문은 정기적으로 사진을 찍는 목표와 이를 달성하는 방법을 명시적으로 요구한다. 따라서 B단계 답변을 완성하기 위한 선택적 근거는 필요하지 않다.'),
    ('prompt-goal-1108', '매주 식사를 미리 준비하는 것은 질문에 이미 정해져 있다. 학습자에게 필요한 것은 계획과 지속 방법뿐이므로 GOAL은 제거해야 한다. 예상되는 B단계의 발전은 독립적인 시점, 장소, 장애물, 결과 또는 이유 하나로 제공해야 한다.'),
    ('prompt-goal-1109', '답변은 매주 긴 글을 읽는 습관에서 원하는 개선을 정하고 구체적인 단계를 제시해야 한다. 이로써 목표와 계획이 모두 충분히 설정된다.'),
    ('prompt-goal-1110', '학습자는 더 나은 스트레칭 습관이라는 목표를 밝히고, 이를 어떻게 실천할지 설명해야 한다. 따라서 필수적인 두 요소만으로 충분한 답변이 된다.'),
    ('prompt-goal-1111', '메모 작성 체계를 개선하는 것은 요청된 계획의 목적에 이미 제시되어 있으므로, GOAL을 요구하면 학습자가 전제를 반복하게 된다. PLAN은 직접적인 의무를 포착하며, 난이도 B에서는 독립적인 체계 세부 정보, 장애물, 결과, 이유 또는 예시 하나가 적절하다.'),
    ('prompt-goal-1112', '학습자는 집안일을 제시간에 끝내는 데서 원하는 개선을 구체적으로 밝히고, 이를 위한 단계를 제시해야 한다. 따라서 완전한 목표와 방법의 답변이 구성된다.'),
    ('prompt-goal-1113', '더 차분한 아침이라는 미래의 상태와 이를 이루는 방법이 별도로 요청된다. 따라서 추가적인 선택 항목은 필요하지 않다.'),
    ('prompt-goal-1114', '질문은 수업에서 더 명확한 질문을 하는 목표를 이미 제시한다. 학습자는 그 목표를 GOAL로 반복하는 것이 아니라 이를 꾸준히 실천하기 위한 계획을 제시해야 하며, B단계의 깊이를 위해 독립적인 상황, 예시, 장애물, 결과 또는 이유 하나가 필요하다.'),
    ('prompt-goal-1115', '답변은 향상하고 싶은 기초 디자인 기술을 식별하고, 취할 단계를 설명해야 한다. 따라서 명시된 목표와 계획만으로 충분하다.'),
    ('prompt-goal-1116', '가정에서 음식물 쓰레기를 줄이는 것이 원하는 결과이며, 질문은 이를 위해 노력하는 방법도 요구한다. 따라서 필수 내용만으로 충분한 깊이가 제공된다.'),
    ('prompt-goal-1117', '한 주를 돌아보는 습관을 기르는 내용은 질문에 이미 제시되어 있으므로 GOAL로 다시 요구해서는 안 된다. 요청된 꾸준한 실행 계획이 유일한 직접 응답 항목이므로, 독립적인 시점 세부 사항, 장애물, 결과, 이유 또는 감정 중 하나를 추가 깊이로 제시하는 것이 적절하다.'),
    ('prompt-goal-1118', '학습자는 지도 읽기에서 어떤 점을 향상하고 싶은지와 이를 위해 취할 단계를 말해야 하므로, 완전한 B단계 목표 및 계획 답변이 된다.'),
    ('prompt-goal-1119', '주말 재정비 루틴이 의도된 미래의 습관이며, 질문에서 이를 어떻게 만들지 별도로 묻고 있으므로 필수 내용만으로 충분하다.'),
    ('prompt-goal-1120', '간단한 수리 기술을 배우는 것은 학습자가 제공하는 목표가 아니라 계획의 제시된 목적이다. PLAN은 질문이 학습자에게 설명하도록 요구하는 내용을 포괄하며, B단계 답변을 발전시키려면 독립적인 기술 예시, 장애물, 결과, 이유 또는 연습 장소 중 하나가 필요하다.'),
    ('prompt-goal-1121', '답변은 책상을 깔끔하게 유지하는 데서 원하는 향상을 정의하고 그 단계를 말해야 하므로, 목표와 계획으로 과제가 완성된다.'),
    ('prompt-goal-1122', '이름을 더 쉽게 기억하는 것이 목표이고 이를 위해 노력하는 방법도 명시적으로 요구되므로, 추가적인 선택적 깊이는 필요하지 않다.'),
    ('prompt-goal-1123', '더 참을성 있게 듣는 사람이 되는 것은 이미 목표로 제시되어 있으므로, GOAL은 전제를 반복해서 요구하는 잘못된 항목이 된다. 학습자는 꾸준한 실행 계획을 설명해야 하며, 적절한 B단계 깊이를 위해 독립적인 장애물, 예시, 결과, 이유 또는 감정 중 하나를 추가해야 한다.'),
    ('prompt-goal-1124', '학습자는 식물 관리에서 무엇을 향상해야 하는지 밝히고 단계를 개괄해야 하므로, 향상 목표와 실행 계획으로 필수 내용이 충분하다.'),
    ('prompt-goal-1125', '짧은 자투리 시간을 더 잘 활용하는 것이 원하는 결과이며, 질문에서 이를 어떻게 실천할지도 묻고 있으므로 목표와 계획의 구조가 완성된다.'),
    ('prompt-goal-1126', '더 현실적인 할 일 목록을 만드는 내용은 질문에 제시되어 있으므로 필수 목표 재진술이 되어서는 안 된다. 직접적인 요구 사항은 꾸준한 실행 계획이며, 난이도 B에서 일반적으로 필요한 추가 깊이를 위해 독립적인 예시, 장애물, 결과, 시점 세부 사항 또는 이유 중 하나를 제시하면 된다.'),
    ('prompt-goal-1127', '답변은 죄책감 없이 쉬는 것에서 원하는 향상을 정의하고 이를 이루기 위한 단계를 말해야 하므로, 목표와 방법이 모두 명시된다.'),
    ('prompt-goal-12', '학습자는 올해 원하는 건강상의 결과를 설명하고 이를 이루기 위한 계획을 설명해야 하므로, 두 개의 필수 단위만으로 충분하다.'),
    ('prompt-goal-13', '건강 목표와 발전을 이루는 방법이 모두 직접적으로 요구되므로, 이 B단계 답변은 필수 깊이를 충분히 갖춘다.'),
    ('prompt-goal-14', '완전한 답변은 건강 목표를 밝히고 이를 추진하기 위한 단계를 말하므로, 독립적인 선택적 보충 내용은 필요하지 않다.'),
    ('prompt-goal-15', '이 표현은 선택한 건강 목표와 그것이 개인적으로 중요한 이유를 요구하며, 이 두 의미 단위만으로 질문이 이미 완성된다.'),
    ('prompt-goal-16', '학습자는 집중할 언어 목표를 말하고 이를 위해 어떻게 노력할지 설명해야 하므로, 목표와 방법을 모두 충분히 다룬다.'),
    ('prompt-goal-17', '언어 목표를 설명하는 것과 계획을 설명하는 것은 서로 다른 직접적 요구 사항이므로, 이 필수 항목들만으로도 B단계 내용이 충분하다.'),
    ('prompt-goal-18', '답변은 언어 향상의 목표를 밝히고 발전이 어떻게 이루어질지 말해야 하므로, 추가 깊이는 선택 사항이다.'),
    ('prompt-goal-19', '요청된 단계가 무엇을 위한 것인지 정하려면 언어 목표를 밝혀야 하며, 단계 자체가 계획을 이룬다. 두 내용이 함께 과제에 답한다.'),
    ('prompt-goal-20', '학습자는 원하는 언어 목표와 그것이 중요한 이유를 설명해야 하므로, 필수 목표와 동기만으로 이미 완전한 답변이 된다.'),
    ('prompt-goal-21', '더 자신감을 얻고 싶은 영역이 원하는 미래 상태이며, 질문에서 이를 발전시키는 방법도 요구하므로 두 핵심 단위가 모두 명시되어 있다.'),
    ('prompt-goal-22', '학습자는 자신감을 기르고 싶은 영역을 설명하고 자신의 계획을 설명해야 하므로, 난이도 B에 필요한 필수 전개가 충분하다.'),
    ('prompt-goal-23', '답변은 자신감이 향상되어야 하는 영역을 밝히고 발전이 어떻게 이루어질지 설명해야 하므로, 목표와 계획이 질문을 충족한다.'),
    ('prompt-goal-24', '답변에는 자신감을 기르고 싶은 영역을 밝히고 이를 기르는 단계를 제시해야 하므로, 서로 독립적인 두 개의 필수 단위가 제공된다.'),
    ('prompt-goal-25', '질문은 원하는 자신감의 영역과 그 변화가 중요한 이유를 묻고 있으므로, 추가 항목 없이도 미래의 목표와 이유만으로 충분하다.'),
    ('prompt-goal-26', '기르고 싶은 직업 역량과 이를 기르는 방법이 모두 직접적으로 요구되므로, 필수 내용만으로도 B단계 질문에 적절히 답한다.'),
    ('prompt-goal-27', '원하는 직업 역량을 설명하는 것이 목표를 정립하며, 계획을 설명하는 것이 두 번째 명시적 절을 충족한다.'),
    ('prompt-goal-28', '학습자는 직업 역량의 목표와 발전이 어떻게 이루어질지 말해야 하므로, 짝을 이루는 필수 항목만으로 충분하다.'),
    ('prompt-goal-29', '직업 역량을 밝히고 계획한 단계를 말해야 하므로, B단계 답변에 이미 목표와 방법이 모두 포함된다.'),
    ('prompt-goal-30', '질문은 직업 역량 목표와 그것이 개인적으로 중요한 이유를 요구하므로, 계획 세부 사항을 요구하지 않고도 서로 독립적인 두 가지 요구 사항이 성립한다.'),
    ('prompt-goal-31', '기르고 싶은 읽기 습관이 목표이고 이를 위해 노력하는 방법이 계획이므로, 명시된 절들만으로 깊이가 충분하다.'),
    ('prompt-goal-32', '학습자는 원하는 읽기 습관을 설명하고 이를 만드는 계획을 설명해야 하므로, 이 목표 및 계획 질문을 완전히 충족한다.'),
    ('prompt-goal-33', '답변은 읽기 습관을 명시하고 어떻게 발전시킬지 설명해야 하므로, 선택적 부연은 유용하지만 필수는 아니다.'),
    ('prompt-goal-34', '학습자는 의도한 읽기 습관을 밝히고 이를 형성하기 위한 단계를 나열해야 하며, 이 내용만으로 필수 답변 요건을 충분히 충족한다.'),
    ('prompt-goal-35', '원하는 읽기 습관과 그것이 중요한 이유를 별도로 요구하므로, 이 두 항목이 B 수준 답변을 완성한다.'),
    ('prompt-goal-36', '답변은 저축 목표와 이를 달성하기 위해 학습자가 어떻게 노력할지를 밝혀야 하며, 의도한 결과와 계획을 모두 포함해야 한다.'),
    ('prompt-goal-37', '저축 목표를 설명하고 계획을 밝히는 것이 질문의 두 가지 직접적인 의무이므로, 이 내용만으로 충분한 깊이를 제공한다.'),
    ('prompt-goal-38', '저축으로 이루려는 결과를 명시하고 어떻게 진전할지 설명해야 하므로, 완전한 목표와 계획의 답변이 된다.'),
    ('prompt-goal-39', '학습자는 단계가 달성하려는 저축 목표를 밝히고 그 단계를 제시해야 하므로, 선택 항목은 필요하지 않다.'),
    ('prompt-goal-40', '질문은 저축 목표와 그 목표를 달성하는 것이 중요한 이유를 요구하므로, 목표와 동기만으로도 적절한 B 수준 답변이 된다.'),
    ('prompt-goal-41', '유지하려는 운동 습관이 원하는 미래 상태이며, 질문은 이를 유지하는 방법도 요구하므로, 이 두 가지 필수 내용만으로 충분하다.'),
    ('prompt-goal-42', '학습자는 운동 습관 목표를 설명하고 이를 유지하기 위한 계획을 밝혀야 하며, 이는 과제의 명시적인 요구를 모두 충족한다.'),
    ('prompt-goal-43', '답변은 어떤 운동 습관을 유지할지와 어떻게 진전할지를 밝혀야 하므로, 필수 내용만으로도 충분히 전개된다.'),
    ('prompt-goal-44', '운동 습관을 밝히면 목표가 정해지고 단계를 말하면 계획이 정해지므로, 서로 독립적인 두 개의 B 수준 답변 단위를 제공한다.'),
    ('prompt-goal-45', '학습자는 어떤 운동 습관을 유지하고 싶은지와 그것이 중요한 이유를 설명해야 하므로, 목표와 이유가 이 과제 유형을 완성한다.'),
    ('prompt-goal-46', '완성하려는 창작 프로젝트가 목표이며, 질문은 완성을 위해 어떻게 노력할지도 명시적으로 요구하므로, 추가적인 깊이는 필요하지 않다.'),
    ('prompt-goal-47', '의도한 창작 프로젝트를 설명하고 계획을 밝히는 것은 서로 별개의 의무이며, 이 내용만으로 완전한 B 수준 답변이 된다.'),
    ('prompt-goal-48', '학습자는 창작 프로젝트의 목표를 밝히고 어떻게 진전할지 설명해야 하므로, 목표와 계획을 모두 충분히 제시하게 된다.'),
    ('prompt-goal-49', '목표를 정하려면 창작 프로젝트를 명시해야 하고, 요청된 단계가 계획을 구성하므로, 필수 항목만으로 충분하다.'),
    ('prompt-goal-50', '학습자는 완성하려는 창작 프로젝트와 그것이 개인적으로 중요한 이유를 밝혀야 하며, 이 두 가지 필수 내용만으로도 충분한 B 수준 깊이를 제공한다.'),
    ('prompt-intro-v2-0001', '두 번째 절은 학습자가 이름의 어떤 점을 좋아하는지 묻는다. OPINION은 긍정적인 태도만 포착하지만, CHOICE는 필수적인 이름 세부 정보와 함께 요청된 좋아하는 점을 포착한다.'),
    ('prompt-intro-v2-0002', '유일한 직접적인 의무는 학습자가 사는 장소를 밝히는 것이며, 이 간단한 개인 질문에는 장소만으로 충분하다.'),
    ('prompt-intro-v2-0003', '학습자는 자신의 도시에서 좋아하는 한 가지 측면을 선택해야 하며, 답변이 단순한 특징 이름에 그치지 않도록 이유나 구체적인 설명 하나가 필요하다.'),
    ('prompt-intro-v2-0004', '문구는 좋아하는 색과 그 색을 좋아하는 이유를 모두 명시적으로 요구하므로, 이 내용만으로 완전한 초급 선호 답변이 된다.'),
    ('prompt-intro-v2-0005', '학습자는 좋아하는 계절을 말하고 그 선호의 이유를 제시해야 하므로, 추가적인 뒷받침 항목은 필요하지 않다.'),
    ('prompt-intro-v2-0006', '이는 능력이나 강점 하나를 묻는 간단한 자기 설명이며, 그 강점을 말하는 것만으로 초급 질문에 완전히 답할 수 있다.'),
    ('prompt-intro-v2-0007', '질문은 학습 목표 하나를 직접 묻고 있으므로, 요청된 목표만으로도 이 입문 수준에서는 충분하다.'),
    ('prompt-intro-v2-0008', '학습자는 평소 아침에 하는 행동을 설명해야 하며, 추가 행동이나 상황 세부 정보 하나가 있어야 이 폭넓은 일과가 단순한 동사구 하나에 그치지 않는다.'),
    ('prompt-intro-v2-0009', '질문은 평소 밤에 하는 행동을 묻고 있으며, 첫 번째 행동 외에 서로 독립적인 일과 세부 정보 하나를 제시하는 것이 적절하다.'),
    ('prompt-intro-v2-0010', '답변은 학습자를 행복하게 하는 원인을 밝혀야 하며, 그 원인을 직접 말하는 것만으로 이 간단한 개인 질문을 완성한다.'),
    ('prompt-intro-v2-0011', '질문은 평온한 감정을 일으키는 것을 직접 묻고 있으므로, 명확한 원인 하나면 입문 수준 답변으로 충분하다.'),
    ('prompt-intro-v2-0012', '질문은 평일과 주말을 포함한 일주일의 요일 중 학습자가 가장 좋아하는 날과 그 이유를 명시적으로 요구하므로, 이 두 가지 필수 내용으로 완전한 답변이 된다.'),
    ('prompt-intro-v2-0013', '학습자는 자신의 성격을 설명해야 하며, 형용사 하나만 제시하는 데서 나아가려면 예시나 행동 하나가 필요하다.'),
    ('prompt-intro-v2-0014', '문구는 현재의 작은 목표 하나를 요구하므로, 원하는 결과를 명확히 진술하면 의무적인 부연 없이도 완전한 답변이 된다.'),
    ('prompt-intro-v2-0015', '학습자는 혼자 즐기는 활동을 하나 말해야 한다. 이유, 느낌 또는 상황 세부 정보가 하나 있어야 활동만 나열한 답변을 피할 수 있다.'),
    ('prompt-intro-v2-0016', '질문은 즐겨 하는 사회적 활동을 묻고 있으며, 독립적인 설명이나 상황을 하나 덧붙이면 이처럼 폭넓은 선호를 유용하게 구체화할 수 있다.'),
    ('prompt-intro-v2-0017', '직접적인 과제는 학습자가 항상 가지고 다니는 물건을 하나 밝히는 것이므로, 물건 자체로 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0018', '학습자는 가까운 곳에서 가장 좋아하는 장소를 하나 고르기만 하면 되며, 이처럼 범위가 명확한 질문에는 그 구체적인 선택만으로 충분하다.'),
    ('prompt-intro-v2-0019', '질문은 개인적인 사실 중 알려지지 않은 것을 하나 묻고 있으며, 그 사실을 직접 말하면 완결된 입문 답변이 된다.'),
    ('prompt-intro-v2-0020', '학습자는 올해 이루고 싶은 개선 사항을 말해야 하며, 개선 목표 자체가 단순한 질문의 요구를 충족한다.'),
    ('prompt-intro-v2-0021', '일어날 때의 행동은 이미 제시되어 있고, 질문은 학습자의 평소 시각만 직접 요구한다.'),
    ('prompt-intro-v2-0022', '질문은 잠에서 깬 후 가장 먼저 하는 행동을 좁혀 묻고 있으므로, 구체적인 행동 하나면 초급 학습자의 답변으로 충분하다.'),
    ('prompt-intro-v2-0023', '아침 식사를 먹는다는 내용은 질문에 제시되어 있다. 빠진 내용은 학습자가 습관적으로 고르는 음식이므로, ACTION은 요청된 항목이 아니라 제시된 전제를 요구하게 된다.'),
    ('prompt-intro-v2-0024', '바쁜 하루는 폭넓은 상황이므로, 요구되는 행동은 다른 단계, 시간 정보 또는 결과로 뒷받침되어야 한다.'),
    ('prompt-intro-v2-0025', '학습자는 쉬는 날의 행동을 설명해야 하며, 이러한 열린 일상 질문에는 추가 활동이나 상황 세부 정보가 하나 필요하다.'),
    ('prompt-intro-v2-0026', '가장 좋아하는 시간대와 그 시간을 선호하는 이유가 모두 명시적인 요구 사항이므로, 이미 완결된 답변을 만들어 낸다.'),
    ('prompt-intro-v2-0027', '질문은 의도적으로 하루의 행동 하나만 답하도록 제한하므로, 필수적인 보충 내용 없이도 그 행동만으로 충분하다.'),
    ('prompt-intro-v2-0028', '요청된 잊어버린 것은 물건일 수도 있고 행동일 수도 있다. DETAIL은 이처럼 열린 범주를 그대로 포괄하지만, ACTION은 유효한 물건 답변을 잘못 제외하고 질문에 제시된 ‘잊어버리는’ 행동을 반복하게 된다.'),
    ('prompt-intro-v2-0029', '이는 피곤하다는 조건이 질문에 이미 제시된 집중형 입문 질문이다. 명확한 대응 행동 하나면 충분히 답할 수 있으므로, 필수적인 추가 보충 내용은 학습자에게 부담을 줄 위험이 있다.'),
    ('prompt-intro-v2-0030', '여가 시간의 행동은 열린 내용이므로, 주된 활동에 더해 독립적인 보충 정보 하나를 제시하는 것이 적절하다.'),
    ('prompt-intro-v2-0031', '아침 일과에는 적어도 습관적인 행동 하나가 필요하며, 단계나 시간 정보를 하나 더 제시하면 일과가 의미 있게 구체화된다.'),
    ('prompt-intro-v2-0032', '학습자는 밤 시간의 일과를 설명해야 하므로, 주된 행동에 보충 단계나 구체적인 상황을 하나 곁들여야 한다.'),
    ('prompt-intro-v2-0033', '질문은 일이나 학교가 끝난 후의 평소 행동을 폭넓게 묻고 있으므로, 핵심 활동 외에 상황 정보나 두 번째 행동이 필요하다.'),
    ('prompt-intro-v2-0034', '학습자는 선호하는 주말 활동을 말해야 하며, 이유나 상황을 하나 덧붙여야 이러한 폭넓은 선호가 활동 이름에만 그치지 않는다.'),
    ('prompt-intro-v2-0035', '질문은 싫어하는 일상 행동을 묻고 있으며, 그러한 부정적인 선호를 설명하려면 이유, 느낌 또는 결과가 하나 필요하다.'),
    ('prompt-intro-v2-0036', '학습자는 자신의 하루를 더 좋게 만드는 것을 하나 밝혀야 하며, 그 구체적인 물건이나 사건이 질문을 직접 완성한다.'),
    ('prompt-intro-v2-0037', '직접적인 요구는 일상에서 바꾸고 싶은 것 하나이므로, 입문 수준에서는 말한 변화 목표만으로 충분하다.'),
    ('prompt-intro-v2-0038', '수면 문제는 질문에 제시되어 있고, 학습자는 그 문제를 다루기 위해 사용하는 행동을 말해야 하므로, 그 해결 방법만으로 단순한 과제를 충족한다.'),
    ('prompt-intro-v2-0039', '편의점에서 무언가를 산다는 내용은 이미 제시되어 있다. 학습자는 습관적으로 고르는 물건을 밝혀야 하므로, 직접적인 요구는 ACTION이 아니라 CHOICE이다.'),
    ('prompt-intro-v2-0040', '질문은 매일 즐거움을 주는 단순한 것 하나를 요구하며, 답변이 의도적으로 좁은 범위이므로 그 대상을 고르는 것만으로 충분하다.'),
    ('prompt-intro-v2-0041', '가장 좋아하는 음식을 말하면 이 짧은 개인 선호 질문에 직접 답할 수 있으며, 설명은 선택 사항이다.'),
    ('prompt-intro-v2-0042', '음식과 그에 대한 선호는 맥락에서 이미 정해져 있다. 이 후속 질문은 학습자가 이유만 말하도록 요구하므로, 답변 유형은 PREFERENCE가 아니라 GENERAL_DESCRIPTION이다.'),
    ('prompt-intro-v2-0043', '반복해서 먹는 행동은 질문의 전제에 포함되어 있다. 직접적인 답변은 자주 고르는 음식이므로, ACTION 대신 CHOICE가 필요하다.'),
    ('prompt-intro-v2-0044', '어떤 음식을 먹어 보고 싶다는 의도는 일반적으로 제시되어 있고, 실제로 빠진 내용은 학습자가 고르는 음식이 무엇인지이다. CHOICE가 GOAL보다 그 대상을 더 정확하게 나타낸다.'),
    ('prompt-intro-v2-0045', '직접적인 요청은 싫어하는 음식 하나를 밝히는 것뿐이므로, 부정적인 선호 자체로 충분하다.'),
    ('prompt-intro-v2-0046', '아침에 마신다는 내용은 질문에 제시되어 있다. 학습자는 평소 마시는 음료를 밝혀야 하며, 이는 새로운 행동 요구가 아니라 선택된 물건이다.'),
    ('prompt-intro-v2-0047', '질문은 커피와 차 중 하나를 선택하고 설명하도록 요구하며, 이 두 요소만으로 완전한 답변이 된다.'),
    ('prompt-intro-v2-0048', '좋아하는 간식을 고르는 것만 명시된 의무이며, 이 간단한 선호 질문에는 그것으로 충분하다.'),
    ('prompt-intro-v2-0049', '학습자에게 좋아하는 과일의 이름만 직접 묻고 있으므로, 선택한 과일이 답변을 완성한다.'),
    ('prompt-intro-v2-0050', '좋아하는 한국 음식은 구체적인 개인 선택이며, 의무적인 설명 없이 음식 이름을 말하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0051', '질문은 고향의 추억과 관련된 음식을 요구하며, 그 음식을 밝히는 것만으로 개인적 연관성에 관한 질문에 직접 답할 수 있다.'),
    ('prompt-intro-v2-0052', '먹는 행동과 피곤한 상태라는 조건은 이미 주어져 있다. 이 조건에서 습관적으로 선택하는 음식만 문자 그대로 알려지지 않은 내용이므로 CHOICE를 필수로 해야 한다.'),
    ('prompt-intro-v2-0053', '질문에는 이미 먹는 행동과 행복한 상태가 제시되어 있다. 직접 요구되는 것은 그 상황에서 선택하는 음식이므로 ACTION이 아니라 CHOICE이다.'),
    ('prompt-intro-v2-0054', '학습자는 매운 음식을 좋아하는지 여부와 그 이유 또는 그렇지 않은 이유를 말해야 하므로, 답변에는 명시적인 의미 요소가 두 가지 있다.'),
    ('prompt-intro-v2-0055', '질문은 단 음식을 좋아하는지 싫어하는지에 대한 판단과 그 판단의 이유를 직접 요구한다.'),
    ('prompt-intro-v2-0056', '학습자는 비 오는 날에 적합한 식사를 추천하거나 판단해야 하며, 단순히 음식 이름을 말하는 것 외에 이유나 설명적 세부 내용 하나가 필요하다.'),
    ('prompt-intro-v2-0057', '친구들과 함께 먹는다는 것은 제시된 맥락이다. 학습자는 그 맥락에서 좋아하는 음식을 선택해야 하므로, 필요한 선호 내용은 ACTION이 아니라 CHOICE이다.'),
    ('prompt-intro-v2-0058', '요리할 수 있다는 능력은 제시되어 있고, 질문은 학습자가 어떤 요리를 잘 만들 수 있는지 묻는다. 이미 말한 요리 행동을 요구하지 않고 요청된 요리를 나타내므로 CHOICE가 적절하다.'),
    ('prompt-intro-v2-0059', '언젠가 요리하고 싶다는 것은 미래의 의도를 제시한다. 직접 알려지지 않은 내용은 그 경험을 위해 선택하는 요리이므로, 일반적인 GOAL보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0060', '가정적 조건에서 오늘 음식 하나를 정확히 선택하도록 하므로, 선택한 음식만으로 충분하며 추가로 요구되는 뒷받침 내용은 없다.'),
    ('prompt-intro-v2-0061', '직접 요구되는 것은 좋아하는 취미의 이름뿐이므로, 선택한 취미만으로 이 짧은 선호 질문의 답변이 완성된다.'),
    ('prompt-intro-v2-0062', '취미와 그것을 좋아한다는 사실은 이미 정해져 있다. 학습자는 요청된 이유만 말하므로, 후속 내용은 PREFERENCE가 아니라 GENERAL_DESCRIPTION이다.'),
    ('prompt-intro-v2-0063', '취미를 시도하려는 의도는 질문에 제시되어 있다. 필요한 미제공 내용은 학습자가 선택하는 취미이므로, GOAL보다 CHOICE가 더 문자 그대로 정확하다.'),
    ('prompt-intro-v2-0064', '질문은 평소 즐거운 활동에 대해 폭넓게 묻고 있으므로, 주요 행동을 뒷받침할 이유, 장소 또는 느낌 하나가 필요하다.'),
    ('prompt-intro-v2-0065', '지루한 상태라는 조건으로 인해 이 질문은 초급 수준의 집중적인 답변 질문이 된다. 대처 행동 하나면 완전한 답변으로 충분하므로, 난이도 I에서는 추가 필수 뒷받침 내용이 필요한지 의문이다.'),
    ('prompt-intro-v2-0066', '질문은 영화 보기에 대한 판단과 설명을 요구하므로, 필요한 두 요소가 이미 모두 요구되어 있다.'),
    ('prompt-intro-v2-0067', '학습자는 선호하는 영화 종류를 선택해야 하며, 장르 이름만 말하는 것 이상으로 답변을 발전시키려면 이유나 예시 하나가 필요하다.'),
    ('prompt-intro-v2-0068', '질문은 음악 듣기를 좋아하는지와 그 이유를 모두 명시적으로 요구하므로, 충분한 깊이가 이미 확보되어 있다.'),
    ('prompt-intro-v2-0069', '과제는 선호하는 음악 종류를 묻고 있으며, 답변이 단순한 장르 표시에 그치지 않도록 설명이나 예시 하나가 필요하다.'),
    ('prompt-intro-v2-0070', '학습자는 반복해서 듣기 위해 선택하는 노래를 밝혀야 하며, 노래 선택 자체가 이 좁은 범위의 습관 질문에 답한다.'),
    ('prompt-intro-v2-0071', '학습자는 책 읽기에 대해 좋아하거나 싫어하는 입장을 밝히고 그 입장을 설명해야 하므로, 추가적인 깊이는 필요하지 않다.'),
    ('prompt-intro-v2-0072', '온라인으로 동영상을 본다는 것은 이미 제시되어 있다. 학습자는 습관적으로 선택하는 동영상의 종류를 밝혀야 하므로, 문자 그대로 필요한 내용은 ACTION이 아니라 CHOICE이다.'),
    ('prompt-intro-v2-0073', '학습자는 좋아해서 하는 게임 하나만 밝히면 되므로, 선택한 게임의 이름을 말하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0074', '직접 요청되는 것은 좋아하는 스포츠이며, 스포츠 선택만으로도 초급 수준의 완전한 선호 답변이 된다.'),
    ('prompt-intro-v2-0075', '질문은 사진 찍기를 좋아하는지와 그 이유를 명시적으로 묻으므로, 판단과 그 설명을 모두 요구한다.'),
    ('prompt-intro-v2-0076', '학습자는 집에서 즐기는 활동의 이름을 말해야 하며, 이유, 느낌 또는 추가 행동 하나가 폭넓은 질문에 충분한 내용을 더한다.'),
    ('prompt-intro-v2-0077', '질문은 선호하는 야외 활동에 대해 일반적으로 묻고 있으므로, 그 행동에 설명이나 맥락 정보 하나를 덧붙여야 한다.'),
    ('prompt-intro-v2-0078', '학습자는 편안함과 관련된 취미를 밝혀야 하며, 선택한 취미가 집중된 질문에 직접 답한다.'),
    ('prompt-intro-v2-0079', '필수 행동이 이미 이전의 행동을 나타내고 있으며, 어린 시절도 제시되어 있다. 따라서 BEFORE_STATE는 첫 번째 보충 내용으로는 적합성이 낮고, 이유나 상황 또는 예시가 더 유용하며 독립적이다.'),
    ('prompt-intro-v2-0080', '질문은 가정적인 결과를 제시할 뿐 실제 목표나 의도를 밝히지 않는다. 학습자는 가능한 취미를 파악하므로 GENERAL_DESCRIPTION과 CHOICE가 답변에 부합하며 실제 계획을 가정하지 않는다.'),
    ('prompt-intro-v2-0081', '질문은 학습자의 가장 친한 친구가 누구인지 묻기만 하므로, 그 사람의 이름을 말하면 답변이 완성된다.'),
    ('prompt-intro-v2-0082', '학습자는 가장 친한 친구에게서 좋아하는 특성을 설명해야 한다. 한 가지 예시나 설명이 있어야 답변이 단순한 특성 단어에 그치지 않는다.'),
    ('prompt-intro-v2-0083', '학습자는 평소에 대화하는 사람을 파악하기만 하면 되므로, 선택한 그 사람이면 충분한 답변이 된다.'),
    ('prompt-intro-v2-0084', '직접적인 과제는 학습자를 웃게 하는 사람을 말하는 것이며, 간단한 질문에는 그 사람을 밝히는 것만으로 답할 수 있다.'),
    ('prompt-intro-v2-0085', '문제가 상황을 제공하지만, 질문은 구체적으로 도움을 주는 사람이 누구인지 묻고 있으므로 그 사람을 밝히는 것만으로 충분하다.'),
    ('prompt-intro-v2-0086', '오늘 누군가에게 고마움을 전하려는 의도는 이미 제시되어 있다. 직접적으로 요구되는 것은 그 사람을 선택하는 것이므로 CHOICE가 부족한 내용을 나타내며, GOAL은 전제를 단순히 반복할 뿐이다.'),
    ('prompt-intro-v2-0087', '질문은 친구들과 즐기는 활동을 폭넓게 묻고 있으며, 활동 자체를 넘어서는 이유나 상황 또는 느낌이 하나 필요하다.'),
    ('prompt-intro-v2-0088', '학습자는 어떤 특성이나 행동이 좋은 친구를 규정하는지 판단해야 한다. 한 가지 설명이나 예시가 있어야 단순한 특성만 제시하는 것을 넘어 판단을 구체화할 수 있다.'),
    ('prompt-intro-v2-0089', '친구들과 대화한다는 내용은 질문에 이미 제시되어 있다. 요구되는 내용은 대화 주제이며, 이는 구체적인 DETAIL이다. EXAMPLE은 유용하고 독립적인 첫 번째 보충 내용을 제공한다.'),
    ('prompt-intro-v2-0090', '학습자는 새로운 사람을 만나는 것을 좋아하는지와 그 이유 또는 좋아하지 않는 이유를 말해야 하므로, 필수적인 두 요소가 이미 완성되어 있다.'),
    ('prompt-intro-v2-0091', '질문은 조용한 사람인지 말이 많은 사람인지 직접 자기 분류를 요구하며, 이 이분법적인 선택만으로도 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0092', '학습자는 선호하는 사람의 유형을 설명해야 하며, 한 가지 이유나 예시가 있어야 단순한 성격 특성 하나를 넘어 내용이 구체화된다.'),
    ('prompt-intro-v2-0093', '친구가 슬퍼한다는 것이 제시된 문제이며, 학습자에게는 자신의 대응이나 해결 방법을 직접 묻고 있다. 따라서 그 대응만으로 간단한 과제가 완성된다.'),
    ('prompt-intro-v2-0094', '학습자는 친구에게 적합한 선물을 추천해야 하며, 물건의 이름만 말하는 것을 넘어서는 한 가지 이유나 구체적인 세부 내용이 필요하다.'),
    ('prompt-intro-v2-0095', '질문은 존경하는 한 사람이 누구인지 직접 묻고 있으므로, 그 사람을 말하는 것만으로 이 수준에서는 충분하다.'),
    ('prompt-intro-v2-0096', '존경하는 사람과 존경한다는 태도는 맥락에 이미 제시되어 있다. 학습자는 이유만 설명하면 되므로, 이는 OPINION_REASON이 아니라 GENERAL_DESCRIPTION인 이유만을 묻는 후속 질문이다.'),
    ('prompt-intro-v2-0097', '학습자는 효과적으로 사과하는 방법을 추천해야 하며, 한 가지 행동 세부 내용이나 이유 또는 예시가 있어야 추천 내용을 분명히 할 수 있다.'),
    ('prompt-intro-v2-0098', '과제는 감사를 표현하는 좋은 방법을 묻고 있으며, 한 가지 구체적인 행동이나 설명 또는 예시가 있어야 조언이 단순한 명칭에 그치지 않는다.'),
    ('prompt-intro-v2-0099', '질문은 이번 달에 하려는 가족 활동이 무엇인지 직접 묻고 있다. ACTION은 답변의 문자 그대로의 단위이며, GOAL은 요구된 활동보다 범위가 넓다.'),
    ('prompt-intro-v2-0100', '명시적으로 요구되는 것은 학습자의 삶에서 중요한 사람을 밝히는 것뿐이므로, 그 사람을 말하는 것으로 충분하다.'),
    ('prompt-intro-v2-0101', '학교에 다니던 시기는 이미 제시되어 있고 과거와 현재의 대비도 요구되지 않는다. 선택한 과목을 더 직접적으로 뒷받침하는 것은 BEFORE_STATE보다 예시나 과목 관련 세부 내용이다.'),
    ('prompt-intro-v2-0102', '질문은 어떤 학교 과목이 어려웠는지 묻고 있으므로, 해결 방법을 요구하지 않고 그 어려웠던 과목을 밝히는 것만으로 충분하다.'),
    ('prompt-intro-v2-0103', '학습자는 자신이 즐기는 학습의 유형이나 주제를 선택해야 하며, 한 가지 이유나 예시가 있어야 주제 이름을 넘어 이러한 폭넓은 선호를 구체화할 수 있다.'),
    ('prompt-intro-v2-0104', '직접적으로 요구되는 것은 영어를 배우는 동기를 설명하는 것이며, 분명한 이유 하나만으로도 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0105', '학습자는 영어 학습에서 쉬운 부분 하나를 밝혀야 하며, 간단한 질문에는 그 구체적인 부분만으로 충분하다.'),
    ('prompt-intro-v2-0106', '질문은 영어 학습에서 어려운 부분만 묻고 있으므로, 필수적인 해결 방법 없이 학습의 어려움을 말하는 것으로 답변이 완성된다.'),
    ('prompt-intro-v2-0107', '학습자는 좋아하는 영어 단어 하나를 선택해야 하며, 그 단어를 고르는 것만으로도 입문 단계의 답변이 완성된다.'),
    ('prompt-intro-v2-0108', '학습자는 영어로 무엇을 더 효과적으로 표현하고 싶은지 말해야 하며, 이는 필수적인 보충 내용이 필요 없는 구체적인 의사소통 목표이다.'),
    ('prompt-intro-v2-0109', '과제는 좋은 학습 방법을 추천하도록 요구하며, 한 가지 행동 세부 내용이나 이유 또는 결과가 있어야 그 추천을 뒷받침할 수 있다.'),
    ('prompt-intro-v2-0110', '질문은 학습자가 가장 효과적으로 공부하는 시간이나 시점의 조건을 직접 묻고 있으며, 그 시간이나 시점을 답하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0111', '학습자는 자신이 가장 잘 공부하는 장소만 식별하면 되므로 장소를 직접 제시하면 질문을 완성할 수 있다.'),
    ('prompt-intro-v2-0112', '질문은 혼자 공부하는 것과 다른 사람들과 공부하는 것 사이에서 명확한 선택을 제시하므로, 설명을 요구하지 않는 이 질문에서는 한 가지 선택만 해도 충분하다.'),
    ('prompt-intro-v2-0113', '학습자는 집중에 도움이 되는 요인 하나를 식별해야 하므로, 그 요인의 이름을 직접 제시하면 질문에 답할 수 있다.'),
    ('prompt-intro-v2-0114', '문구는 집중력을 잃게 되는 원인이나 계기를 요구하므로, 하나의 명확한 원인만 제시해도 완전한 입문 답변이 된다.'),
    ('prompt-intro-v2-0115', '학습자는 선호하는 일의 종류를 설명해야 하므로, 포괄적인 직업 명칭을 넘어선 한 가지 이유나 구체적인 특징이 필요하다.'),
    ('prompt-intro-v2-0116', '질문은 직업에서 무엇이 중요한지에 대한 판단을 요구하므로, 제시한 우선순위를 뒷받침할 한 가지 이유나 예시가 필요하다.'),
    ('prompt-intro-v2-0117', '학습자는 직장이나 학교에서 바꾸고 싶은 한 가지를 식별해야 하므로, 원하는 결과를 직접 제시하면 질문의 요구를 충족한다.'),
    ('prompt-intro-v2-0118', '질문은 앞으로 갖고 싶은 기술 하나를 요구하므로, 그 기술을 명확히 제시하는 것만으로도 입문 목표 과제에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0119', '학습자는 최근에 배운 것을 말해야 하므로, 배운 사실이나 기술만으로도 이 초점이 분명한 기억 질문에 답할 수 있다.'),
    ('prompt-intro-v2-0120', '질문은 가까운 시일 내의 공부 목표 하나를 직접 요구하므로, 그 작은 목표를 말하면 이 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0121', '학습자는 선호하는 방만 식별하면 되므로, 추가적인 뒷받침 없이 선택한 방을 제시하면 충분하다.'),
    ('prompt-intro-v2-0122', '방과 그 방을 좋아한다는 사실은 이미 제시되어 있다. 이 후속 질문은 이유만 묻기 때문에 학습자의 답변에는 PREFERENCE보다 GENERAL_DESCRIPTION이 적합하다.'),
    ('prompt-intro-v2-0123', '질문은 집에서 평소에 하는 활동 하나를 요구한다. 일과가 포괄적이므로, 단순한 활동 답변에 그치지 않도록 독립적인 시간 정보, 이유, 또는 두 번째 행동에 관한 세부 정보 하나가 필요하다.'),
    ('prompt-intro-v2-0124', '문구는 방에서 좋아하는 물건 하나를 요구하므로, 그 물건의 이름을 말하면 이 좁은 범위의 개인적 질문을 완성할 수 있다.'),
    ('prompt-intro-v2-0125', '선호하는 선택만으로는 책상의 외관이 충분히 구체화되지 않는다. 책상의 배치, 인상, 용도, 그리고 그렇게 꾸민 이유가 CHOICE보다 관련성 높은 선택적 추가 내용이다.'),
    ('prompt-intro-v2-0126', '학습자는 방에서 바꾸고 싶은 것을 말해야 하므로, 의도하는 미래의 상태 자체로 이 초점이 분명한 질문을 충족할 수 있다.'),
    ('prompt-intro-v2-0127', '두 절은 깨끗한 방을 좋아하는지 싫어하는지에 대한 입장과 그 이유를 모두 요구하므로, 이 두 내용만으로도 충분한 깊이가 생긴다.'),
    ('prompt-intro-v2-0128', '질문은 개인적으로 편안함을 느끼는 장소를 식별하도록 요구하므로, 입문 수준에서는 장소로 답하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0129', '직접적으로 요구되는 것은 휴식과 관련된 장소의 이름을 말하는 것뿐이며, 편안해지는 효과는 이미 질문에 제시되어 있다.'),
    ('prompt-intro-v2-0130', '질문은 학습자가 가장 좋아하는 카페를 요구하므로, 선택한 카페를 식별하면 간단한 선호 답변이 완성된다.'),
    ('prompt-intro-v2-0131', '학습자는 카페에서 즐기는 활동을 하나 말해야 하므로, 이 포괄적인 선호 답변에 충분한 내용을 더하려면 독립적인 이유, 시간 정보, 또는 추가 행동 하나가 필요하다.'),
    ('prompt-intro-v2-0132', '질문은 학습자가 가장 좋아하는 공원이 어느 곳인지 묻기만 하므로, 공원을 선택하면 답변이 완성된다.'),
    ('prompt-intro-v2-0133', '이 열린 선호 질문은 그렇지 않으면 특징의 이름만으로 답할 수 있다. 난이도 I에서도 포괄적인 동네 질문을 구체화하려면 이유, 설명, 또는 예시 하나가 적절하다.'),
    ('prompt-intro-v2-0134', '학습자는 자주 방문하는 장소만 말하면 되며, 장소를 직접 제시하면 이 입문 수준의 사실 중심 일상 질문을 완성할 수 있다. 추가적인 의미 단위를 요구하는 것은 불필요하게 어렵다.'),
    ('prompt-intro-v2-0135', '학습자는 제시된 도시에서 원하는 특정 장소만 말하며, 더 넓은 목표나 계획은 필요하지 않다. 지침은 이러한 답변 형태를 GENERAL_DESCRIPTION으로 분류한다.'),
    ('prompt-intro-v2-0136', '양자택일의 문구는 조용한 장소와 번잡한 장소 중 하나를 선택하도록 요구하므로, 명시적인 선택만으로 이 초급 항목을 완성할 수 있다.'),
    ('prompt-intro-v2-0137', '학습자는 적절한 만남의 장소를 추천해야 하므로, 단순히 추천 장소의 이름만 말하는 것이 아니라 그 추천을 뒷받침할 한 가지 이유나 구체적인 세부 정보가 필요하다.'),
    ('prompt-intro-v2-0138', '어떤 장소를 좋은 공부 장소라고 부르는 것은 추천에 해당하므로, 그 판단을 뒷받침할 독립적인 이유나 특징 하나가 필요하다.'),
    ('prompt-intro-v2-0139', '과제는 학습자의 행복과 관련된 장소를 식별하는 것이므로, 요구된 장소만 말해도 이 초점이 분명한 질문에 답할 수 있다.'),
    ('prompt-intro-v2-0140', '직접적인 답변은 원하는 미래의 장소일 뿐이며, 이주 단계나 더 넓은 목표는 요구되지 않는다. 이 초점이 분명한 장소 답변은 GENERAL_DESCRIPTION이어야 한다.'),
    ('prompt-intro-v2-0141', '학습자는 여행을 좋아하는지 여부를 말하고 그 이유 또는 그렇지 않은 이유를 설명해야 하므로, 이 두 가지 명시적 내용만으로도 완전한 답변이 된다.'),
    ('prompt-intro-v2-0142', '여행이라는 주제는 이미 제시되어 있고 학습자는 원하는 목적지만 말한다. 필수 계획 없이 원하는 특정 장소만 제시하는 경우 지침에 따라 GENERAL_DESCRIPTION이다.'),
    ('prompt-intro-v2-0143', '질문은 국가 목적지만 요구하며, 더 폭넓은 여행 목표나 준비를 요구하지 않는다. 답변 형식은 특정 장소에 대한 설명이다.'),
    ('prompt-intro-v2-0144', '방문한다는 내용은 이미 주어져 있고 계획은 필요하지 않으므로, 원하는 도시만 제시하면 된다. 특정 PLACE 답변은 GENERAL_DESCRIPTION에 해당한다.'),
    ('prompt-intro-v2-0145', '질문은 선호하는 여행 활동을 폭넓게 묻고 있으므로, 핵심 행동 외에 독립적인 이유, 장소 또는 두 번째 활동이 하나 필요하다.'),
    ('prompt-intro-v2-0146', '학습자는 미래의 여행 경험을 위해 먹고 싶은 음식을 선택하며, 그 음식을 말하는 것만으로도 좁은 범위의 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0147', '이 특정 입문 질문은 여행에 항상 가져가는 물건 하나를 묻는다. 그 물건을 말하면 완전한 답변이 되므로 필수적인 상세 설명은 필요하지 않다.'),
    ('prompt-intro-v2-0148', '질문은 혼자 여행할지 단체로 여행할지 명확한 선택지를 제시하며, 이 수준에서는 선택만 해도 충분하다.'),
    ('prompt-intro-v2-0149', '학습자는 가장 좋았던 여행을 선택해야 하며, 폭넓은 기억의 선택을 의미 있게 만들려면 독립적인 장소, 시간, 사건의 세부 내용 또는 느낌이 하나 필요하다.'),
    ('prompt-intro-v2-0150', '여행은 이미 맥락에서 특정되어 있고, 질문은 그 여행이 특별했던 이유를 직접 묻는다.'),
    ('prompt-intro-v2-0151', '학습자는 다시 방문하고 싶은 장소를 하나만 식별하면 된다. 질문은 더 폭넓은 목표나 계획을 요구하지 않으므로, 특정 장소 답변은 GENERAL_DESCRIPTION에 해당한다.'),
    ('prompt-intro-v2-0152', '학습자는 긍정적인 여행 기억을 식별해야 하며, 그 기억을 구체적으로 말하면 이 입문 질문을 충족한다.'),
    ('prompt-intro-v2-0153', '질문은 여행 중 어떤 어려움이 발생하는지만 묻고 해결 방법은 묻지 않으므로, 문제를 말하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0154', '질문은 학습자가 여행에서 재미있다고 느끼는 알아볼 수 있는 측면을 묻고 있으며, 그 답은 활동뿐 아니라 경험, 사람, 장소, 음식 또는 상황일 수 있다. 열린 요인을 DETAIL로 받으면 행동으로 강제하지 않고 질문을 정확히 반영한다.'),
    ('prompt-intro-v2-0155', '문장은 해변과 산 중 하나를 선택하도록 요구하며, 이유를 명시적으로 요구하지 않는다.'),
    ('prompt-intro-v2-0156', '학습자는 호텔과 게스트하우스 중 하나를 선택해야 하므로, 선택한 숙박 시설이 완전한 답변이다.'),
    ('prompt-intro-v2-0157', '이는 실제 의도나 준비 계획이 아니라 가정적인 행동이다. 학습자는 자신이 무엇을 할지 설명하므로, GENERAL_DESCRIPTION이 가이드에 부합하는 방식이다.'),
    ('prompt-intro-v2-0158', '학습자는 여행 선물로 줄 수 있는 물건을 선택해야 하며, 선택한 물건을 말하면 이 좁은 범위의 가정 상황을 충족한다.'),
    ('prompt-intro-v2-0159', '질문은 학습자가 여행 중 무엇을 사진으로 찍을지 묻고 있으므로, 그 사진 대상을 선택하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0160', '조건은 가정적이며 학습자는 목적지만 제시한다. 가정적인 표현과 특정 PLACE 답변이라는 두 가지 이유로 GOAL_PLAN은 적절하지 않다.'),
    ('prompt-intro-v2-0161', '질문은 웃음의 원인이나 계기를 묻고 있으므로, 그러한 이유 하나를 말하면 답변이 직접 완성된다.'),
    ('prompt-intro-v2-0162', '학습자는 긴장감을 유발하는 것이 무엇인지 식별해야 하며, 이 특정 감정 질문에서는 명확한 계기 하나면 충분하다.'),
    ('prompt-intro-v2-0163', '문장은 화가 나는 원인을 직접 요구하며, 계기 하나를 말하는 것만으로 이 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0164', '학습자가 자부심을 느끼게 하는 것이 무엇인지 말하는 것이 직접적인 요구 사항이므로, 이유 하나만으로도 답변이 완성된다.'),
    ('prompt-intro-v2-0165', '학습자는 감사함을 느끼는 원인을 말해야 하며, 그 이유만으로도 이 간단한 요구를 충족한다.'),
    ('prompt-intro-v2-0166', '슬픈 상황이라는 조건이 일상 행동의 범위를 좁혀 주므로, 명확한 대응 행동 하나가 초급 답변으로 충분하다.'),
    ('prompt-intro-v2-0167', '질문은 학습자가 스트레스를 받을 때 보이는 일반적인 대응을 묻는다. 하나의 대처 행동이 이 한정된 상황에 직접 답한다.'),
    ('prompt-intro-v2-0168', '흥분한 상황이라는 조건이 행동을 구체화하므로, 그 결과로 하는 행동 하나를 말하면 충분하다.'),
    ('prompt-intro-v2-0169', '학습자는 기운을 나게 하는 작은 일을 하나만 식별하면 되므로, 그 구체적인 세부 내용으로 특정 질문이 완성된다.'),
    ('prompt-intro-v2-0170', '문장은 작은 짜증이나 어려움을 묻고 있으므로, 성가시게 하는 대상 자체가 요구되는 문제이다.'),
    ('prompt-intro-v2-0171', '학습자는 비 오는 날을 좋아하는지 말하고 그 이유를 설명해야 하므로, 두 가지 명시적인 요구 사항만으로 이미 충분한 깊이가 제공된다.'),
    ('prompt-intro-v2-0172', '두 부분으로 이루어진 질문은 추운 날씨에 대한 입장과 그 입장의 이유를 요구하므로, 추가적인 뒷받침은 필요하지 않다.'),
    ('prompt-intro-v2-0173', '답변에는 더운 날씨에 대한 학습자의 견해와 요청된 설명이 모두 포함되어야 하며, 이는 이 수준에서 충분하다.'),
    ('prompt-intro-v2-0174', '새로운 것을 시도하는 것에 대한 예·아니오 선호만 묻는다면 짧은 답변만 허용될 수 있으므로, 이유나 예시가 하나 필요하다.'),
    ('prompt-intro-v2-0175', '학습자는 계획 세우기에 대한 선호를 밝혀야 하며, 독립적인 이유나 예시를 하나 제시해야 단순히 예 또는 아니요로만 답하는 것을 피할 수 있다.'),
    ('prompt-intro-v2-0176', '질문은 놀라움에 대한 입장을 묻고 있으며, 단순한 예 또는 아니요를 넘어 뒷받침하는 이유, 예시 또는 느낌을 하나 제시해야 한다.'),
    ('prompt-intro-v2-0177', '학습자는 자신에게 쉬운 과업이나 능력을 하나 밝혀야 하며, 구체적인 항목 하나면 이 간단한 개인 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0178', '직접적인 요청은 학습자가 어렵게 느끼는 일을 묻는 것이므로, 그 어려움을 밝히는 것만으로도 충분한 답변이 된다.'),
    ('prompt-intro-v2-0179', '이 폭넓은 성찰 질문은 현재 학습자에게 중요한 것이 무엇인지 묻고 있으므로, 단순히 이름만 말하는 것을 넘어 이유, 관련 행동 또는 목표를 하나 제시해야 한다.'),
    ('prompt-intro-v2-0180', '질문은 오늘 감사하게 느끼는 구체적인 것을 하나 요구하며, 그것을 밝히면 이 초점이 분명한 감사 질문이 완성된다.'),
    ('prompt-intro-v2-0181', '학습자는 내일 하려고 하는 행동을 하나 말해야 하며, 분명한 행동 하나면 이 단기간 계획에 충분하다.'),
    ('prompt-intro-v2-0182', '직접적인 요구는 주말에 하려고 하는 활동을 말하는 것이며, 그 행동만으로도 이 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0183', '질문은 학습자가 다음 달에 하려고 하는 일을 묻고 있으므로, 미래의 행동 하나면 초점이 분명한 요청을 충족한다.'),
    ('prompt-intro-v2-0184', '학습자는 내년에 하려고 하는 행동을 하나 밝혀야 하며, 계획이나 동기를 덧붙이면 답변이 풍부해질 수 있지만 명시적으로 요구되지는 않는다.'),
    ('prompt-intro-v2-0185', '질문은 미래의 폭넓은 개인적 모습을 묻고 있으므로, 말한 포부를 뒷받침할 이유, 특징을 보여 주는 세부 사항 또는 계획을 하나 제시해야 한다.'),
    ('prompt-intro-v2-0186', '질문은 꿈을 하나 말하라고 요구하며, 원하는 미래의 결과를 분명히 밝히는 것만으로도 이 간단한 질문에 충분하다.'),
    ('prompt-intro-v2-0187', '오후에 시간이 있다는 것은 가정적 조건이지, 정해진 미래의 의도가 아니다. 학습자는 가능한 행동을 설명하므로, 이는 GOAL_PLAN이 아니라 GENERAL_DESCRIPTION에 해당한다.'),
    ('prompt-intro-v2-0188', '하루의 여유가 있다는 상황은 가상의 행동을 묻는 것이며 실제 계획을 세우게 하지는 않는다. 답변 구조에는 GENERAL_DESCRIPTION이 알맞다.'),
    ('prompt-intro-v2-0189', '정해진 예산은 가상의 구매 선택을 전제로 하며, 학습자가 무엇을 살지 밝히는 것이 질문에 직접 답하는 내용이다.'),
    ('prompt-intro-v2-0190', '시간이 더 많다는 것은 현실이 아닌 조건이며, 학습자는 목표나 계획을 정하는 것이 아니라 가상의 행동을 설명한다. 필요한 답변 방식은 GENERAL_DESCRIPTION이다.'),
    ('prompt-intro-v2-0191', '영어를 잘한다는 것은 가정적 전제이며, 학습자는 그 조건에서 무엇을 할지만 말한다. 그 가능한 행동은 GOAL_PLAN이 아니라 GENERAL_DESCRIPTION에 해당한다.'),
    ('prompt-intro-v2-0192', '다른 나라에서 산다는 것은 명시적으로 가정된 상황이다. 학습자는 그 상황에서 가능한 행동을 설명하므로, GOAL_PLAN으로 분류하면 이를 실제 의도로 잘못 다루게 된다.'),
    ('prompt-intro-v2-0193', '학습자는 하루 동안의 가상 상황에서 동물을 하나 선택해야 하며, 동물 자체를 고르는 것만으로 충분하다.'),
    ('prompt-intro-v2-0194', '이는 현재의 계획이 아니라 어린 시절의 진로 희망에 대한 기억이므로, 과거의 목표를 말하면 질문이 완성된다.'),
    ('prompt-intro-v2-0195', '흥미롭다는 표현은 학습자에게 현재 매력적으로 느껴지는 직업을 밝히라는 뜻이므로, 그 직업을 고르는 것이 필요한 답변이다.'),
    ('prompt-intro-v2-0196', '학습자는 곧 시도할 새로운 대상 하나를 말해야 하지만, 그 대상은 활동뿐 아니라 경험, 음식, 제품, 기술, 방법, 스타일 또는 다른 구체적인 선택지일 수 있다. DETAIL을 필수로 두면 열린 대상을 행동으로 잘못 제한하지 않는다.'),
    ('prompt-intro-v2-0197', '질문은 학습자가 만들고 싶은 습관을 묻고 있으므로, 원하는 습관 자체가 완전한 핵심 목표이다.'),
    ('prompt-intro-v2-0198', '직접적인 요청은 학습자가 끝내고 싶은 습관을 묻는 것이며, 그 행동을 밝히면 의도한 변화를 표현할 수 있다.'),
    ('prompt-intro-v2-0199', '완벽한 하루를 설명하는 것은 범위가 넓으므로, 하나의 일반적인 설명을 넘어 독립적인 활동, 장소, 시간 관련 세부 사항 또는 느낌을 하나 제시해야 한다.'),
    ('prompt-intro-v2-0200', '질문은 학습자의 미래의 자신에게 보낼 메시지 하나의 내용을 직접 묻고 있으며, 완전한 메시지 하나면 충분하다.'),
    ('prompt-intro-v2-0201', '학습자는 좋아하는 숫자를 하나 말하고 그 이유를 설명해야 하며, 선택과 이유가 모두 명시적으로 요구되므로 이미 충분한 깊이를 제공한다.'),
    ('prompt-intro-v2-0202', '두 절에서 좋아하는 동물과 그 선호 이유를 직접 요구하므로, 추가적인 뒷받침 내용은 필요하지 않다.'),
    ('prompt-intro-v2-0203', '질문은 학습자가 가장 좋아하는 꽃이 무엇인지 묻기만 하므로, 꽃을 고르는 것만으로 완전한 답변이 된다.'),
    ('prompt-intro-v2-0204', '학습자는 좋아하는 냄새를 하나 밝혀야 하며, 그것을 말하면 이 범위가 좁은 감각 선호 질문을 충족한다.'),
    ('prompt-intro-v2-0205', '직접적인 과업은 학습자가 가장 좋아하는 소리를 말하는 것이며, 입문 난이도에서는 그것만으로 충분하다.'),
    ('prompt-intro-v2-0206', '질문은 좋아하는 한국어 단어를 하나 말하라고 요구하므로, 그 단어를 밝히면 이 간단한 선호 질문이 완성된다.'),
    ('prompt-intro-v2-0207', '학습자는 좋아하는 영어 단어 하나만 말하면 된다. 의미나 이유를 덧붙이면 유용하지만 명시적으로 요구되지는 않는다.'),
    ('prompt-intro-v2-0208', '질문은 학습자에게 좋아하는 착용 물품을 고르게 하며, 그 물품만으로 질문에 직접 답할 수 있다.'),
    ('prompt-intro-v2-0209', '학습자는 좋아하는 가방이나 다른 물품을 밝혀야 하므로, 선택한 물건만으로도 이처럼 초점이 분명한 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0210', '문구는 선호하는 신발 종류를 요구하므로, 그 종류를 말하면 제한된 선택에 대한 답변이 완성된다.'),
    ('prompt-intro-v2-0211', '질문은 학습자의 옷에 평소 어떤 색이 자주 등장하는지 묻으며, 색을 고르는 것만으로도 간단한 일상 답변으로 충분하다.'),
    ('prompt-intro-v2-0212', '학습자는 꾸준히 좋아하는 음식 하나를 말하면 되며, 그 음식 선택이 질문의 요구를 직접 충족한다.'),
    ('prompt-intro-v2-0213', '질문은 학습자가 아무리 마셔도 질리지 않는 음료를 요구하므로, 선호하는 음료를 밝히는 것만으로 충분하다.'),
    ('prompt-intro-v2-0214', '직접적인 요구는 학습자가 집에서 가장 좋아하는 물건을 말하는 것이며, 물건을 선택하면 답변이 완성된다.'),
    ('prompt-intro-v2-0215', '질문은 책상 위에서 가장 좋아하는 물건을 간단히 묻고 있으므로, 그 물건을 말하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0216', '학습자는 가방에 넣어 다니는 가장 좋아하는 물건을 밝히기만 하면 되므로, 선택한 물건만으로 충분하다.'),
    ('prompt-intro-v2-0217', '질문은 좋아하는 자연의 소리 하나를 요구하며, 그 소리를 말하면 이처럼 구체적인 감각 선호에 완전히 답할 수 있다.'),
    ('prompt-intro-v2-0218', '학습자는 가장 좋아하는 앉을 장소를 고르는 것이므로, 그 장소를 밝히면 초급 수준의 완전한 답변이 된다.'),
    ('prompt-intro-v2-0219', '질문은 좋아하는 작은 것 하나를 요구하며, 선택한 것 자체로 초점이 분명한 선호 질문을 충족한다.'),
    ('prompt-intro-v2-0220', '문구는 학습자가 식당에서 평소 처음 고르는 것을 묻고 있으므로, 그 선택을 말하면 일상적인 질문에 직접 답할 수 있다.'),
    ('prompt-intro-v2-0221', '학습자는 어린 시절의 행복한 기억 하나를 밝혀야 하며, 그 기억을 구체적으로 말하는 것만으로 충분하다.'),
    ('prompt-intro-v2-0222', '질문은 학습자가 어린 시절에 좋아했던 게임을 요구하므로, 그 게임을 말하면 과거의 선호에 대한 답변이 완성된다.'),
    ('prompt-intro-v2-0223', '학습자는 어릴 때 좋아했던 음식 하나를 밝히기만 하면 되며, 추가 설명은 선택 사항이다.'),
    ('prompt-intro-v2-0224', '문구는 어린 시절 좋아했던 만화를 요구하며, 만화를 고르는 것만으로 적절한 답변이 된다.'),
    ('prompt-intro-v2-0225', '질문은 어린 시절 자주 갔던 장소를 간단히 묻는다. 장소만으로 이 단순한 사실적 일상에 직접 답할 수 있으므로, 다른 뒷받침 내용을 요구하는 것은 난이도 I에서는 타당하지 않을 수 있다.'),
    ('prompt-intro-v2-0226', '학습자는 좋아하는 선생님 한 명을 밝혀야 하며, 그 사람을 말하면 간단한 선호 질문을 충족한다.'),
    ('prompt-intro-v2-0227', '이 폭넓은 과거의 선호 질문은 학교의 특징 하나만 고립적으로 말하는 답변도 허용한다. 입문 수준의 답변을 의미 있게 만들려면 이유, 세부 내용 또는 예시 하나가 적절하다.'),
    ('prompt-intro-v2-0228', '이 열린 싫어하는 것 질문은 깊이 0에서는 특징을 나타내는 말 하나만으로 답할 수 있다. 이 폭넓은 선호에 대한 적절한 뒷받침으로 독립적인 이유, 예시, 감정 또는 해결책 중 하나가 필요하다.'),
    ('prompt-intro-v2-0229', '질문은 학습자가 가장 좋아했던 학교 급식을 묻고 있으며, 그 급식 선택이 질문에 직접 답한다.'),
    ('prompt-intro-v2-0230', '학습자는 어린 시절의 포부를 회상하는 것이므로, 무엇이 되고 싶었는지를 말하는 것이 요구된 목표를 완전히 제시한다.'),
    ('prompt-intro-v2-0231', '질문은 학습자가 어릴 때 좋아했던 장난감을 요구하며, 그 장난감을 말하면 과거의 선호에 대한 질문을 충족한다.'),
    ('prompt-intro-v2-0232', '질문은 학습자에게 어린 시절의 기억과 관련된 노래를 밝히도록 하므로, 노래 자체가 필요한 구체적 세부 내용이다.'),
    ('prompt-intro-v2-0233', '학습자는 어린 시절을 떠올리게 하는 냄새 하나를 밝혀야 하며, 그 감각 단서를 말하면 초점이 분명한 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0234', '가장 좋아하는 가족 여행을 고르는 것은 충분히 폭넓은 내용이므로, 여행을 선택한 뒤 장소, 시기, 사건의 세부 내용 또는 감정 중 하나를 덧붙여야 한다.'),
    ('prompt-intro-v2-0235', '질문은 과거에 방과 후 반복적으로 했던 활동을 묻는다. 활동만 말하는 것에서 더 나아가 장소, 이유 또는 두 번째 행동 중 하나가 필요하다.'),
    ('prompt-intro-v2-0236', '학습자는 방학 동안 즐겼던 활동 하나를 말해야 하며, 장소, 이유 또는 추가 행동 중 독립적인 내용 하나를 덧붙여야 폭넓은 과거 선호에 충분한 깊이가 생긴다.'),
    ('prompt-intro-v2-0237', '질문은 학습자가 학교에서 가장 좋아하는 장소를 직접 묻고 있으므로, 그 장소를 선택해 밝히는 것만으로 충분하다.'),
    ('prompt-intro-v2-0238', '학습자는 재미있었던 학교 기억 하나를 말해야 하며, 기억하는 사건을 구체적으로 진술하면 간단한 질문이 완성된다.'),
    ('prompt-intro-v2-0239', '직접적인 요청은 어린 시절에 놓친 한 가지를 밝히는 것이므로, 그 대상을 말하면 개인적인 답변으로 충분하다.'),
    ('prompt-intro-v2-0240', '학습자가 더 어린 자신에게 할 말의 내용을 묻는 질문이므로, 설명을 반드시 덧붙이지 않아도 완전한 메시지 하나로 질문을 충족한다.'),
    ('prompt-intro-v2-0241', '학습자의 일상적인 사용에 포함되는 앱이 무엇인지 묻는 질문이므로, 해당 앱을 말하면 이 간단한 개인 일상 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0242', '학습자가 유용하다고 생각하는 앱을 밝혀야 하며, 그 이점이나 이유를 덧붙이면 도움이 되지만 이 수준에서는 필수는 아니다.'),
    ('prompt-intro-v2-0243', '학습자가 재미있다고 느끼는 앱을 선택하는 질문이므로, 선택한 앱만으로도 짧은 초급 과제를 충족한다.'),
    ('prompt-intro-v2-0244', '휴대폰으로 무언가를 시청하는 행동은 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 습관적으로 선택하는 콘텐츠이므로, ACTION보다 CHOICE가 요청된 답을 더 정확히 포착한다.'),
    ('prompt-intro-v2-0245', '온라인에서 검색한다는 행동은 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 평소 찾아보기로 선택하는 주제나 정보이므로, 이 간단한 일상 질문에는 ACTION보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0246', '학습자는 셀카 찍기를 좋아하는지 밝히고 그 이유를 직접 설명해야 하며, 이 두 가지 필수 요소만으로도 충분한 깊이를 제공한다.'),
    ('prompt-intro-v2-0247', '질문은 소셜 미디어에 대한 호감 또는 비호감 판단과 그 판단의 이유를 명시적으로 요구한다.'),
    ('prompt-intro-v2-0248', '온라인에 게시한다는 행동은 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 평소 공유하기로 선택하는 콘텐츠 종류이므로, 이 일상 질문에는 ACTION보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0249', '‘어떤 종류인지’를 직접 묻는 표현이므로, 학습자가 평소 찍는 사진의 특징적인 범주를 제시해야 한다.'),
    ('prompt-intro-v2-0250', '학습자는 가장 좋아하는 휴대전화 사진을 밝혀야 하며, 독립적인 세부 정보 하나인 이유, 감정, 시기 또는 장소를 덧붙여야 단순히 모호한 사진 이름을 제시하는 데 그치지 않는다.'),
    ('prompt-intro-v2-0251', '배터리 부족이 문제로 제시되고, 질문은 이를 해결하기 위해 학습자가 어떻게 대응할지 직접 묻는다.'),
    ('prompt-intro-v2-0252', '매일 휴대전화를 사용하는 시간을 구체적으로 묻는 질문이므로, 구체적인 시간의 양을 제시하면 사실적인 일상 답변이 완성된다.'),
    ('prompt-intro-v2-0253', '학습자가 줄이고 싶은 휴대전화 사용을 말해야 하므로, 현재 습관을 보고하는 것이 아니라 바라는 미래의 변화를 표현해야 한다.'),
    ('prompt-intro-v2-0254', '학습자가 늘리고 싶은 유익하거나 원하는 휴대전화 사용을 묻는 질문이므로, 그 미래 상태가 필요한 목표가 된다.'),
    ('prompt-intro-v2-0255', '학습자는 문자 메시지와 전화 중 하나를 선택하고 명시적으로 요청된 이유를 제시해야 하므로, 추가적인 깊이 요소는 필요하지 않다.'),
    ('prompt-intro-v2-0256', '학습자의 의사소통에서 자주 등장하는 이모티콘이 무엇인지 묻는 질문이므로, 그 이모티콘을 말하면 간단한 일상 답변으로 충분하다.'),
    ('prompt-intro-v2-0257', '학습자에게 웃음과 관련된 특정한 최근 동영상을 밝히도록 하며, 그 동영상에 관한 세부 정보는 선택적인 보충 내용이다.'),
    ('prompt-intro-v2-0258', '학습자가 정기적으로 이용하는 온라인 상점이 무엇인지 묻는 질문이므로, 상점을 선택하는 것 자체로 초급 일상 질문에 답할 수 있다.'),
    ('prompt-intro-v2-0259', '균형 잡힌 비교가 아니라 인터넷의 긍정적인 측면 하나를 요구하는 질문이므로, 그 한 가지 장점만으로 충분하다.'),
    ('prompt-intro-v2-0260', '학습자는 휴대전화를 과도하게 사용할 때의 부정적인 결과나 단점 하나를 밝혀야 하며, 질문은 해결책까지 요구하지 않는다.'),
    ('prompt-intro-v2-0261', '구매 선호가 매우 광범위하므로, 좋아하는 구매 대상을 말한 뒤 이유, 예시, 장소 또는 구체적인 시기 정보 중 하나를 덧붙여야 한다.'),
    ('prompt-intro-v2-0262', '반복적으로 하는 광범위한 구매에 관한 질문이므로, 구매 품목을 넘어 유용한 내용을 제공하려면 빈도, 장소, 이유 또는 예시 중 독립적인 정보 하나를 제시해야 한다.'),
    ('prompt-intro-v2-0263', '요즘 무언가를 사고 싶다는 현재의 구매 의도는 질문에 제시되어 있다. 직접 묻는 내용은 학습자가 선택하는 물건이므로 GOAL보다 CHOICE가 더 정확하며, 이유와 구매 단계와 물건의 세부 사항은 선택 정보로 남는다.'),
    ('prompt-intro-v2-0264', '가장 최근에 구입했거나 주문한 품목이 무엇인지 묻는 사실 기억 질문이므로, 이를 밝히는 것만으로도 입문 수준에서는 충분하다.'),
    ('prompt-intro-v2-0265', '온라인 쇼핑과 오프라인 쇼핑 중 하나를 선택하고, 그 선호 이유를 함께 제시해야 한다.'),
    ('prompt-intro-v2-0266', '학습자가 정기적으로 방문하는 가게의 이름을 말하도록 하므로, 그 구체적인 가게만으로도 이 좁은 범위의 일상 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0267', '학습자가 슈퍼마켓에서 보통 무엇을 사는지 품목이나 범주로 묻는 질문이며, 추가적인 근거가 필요 없는 직접적인 일상 사실이다.'),
    ('prompt-intro-v2-0268', '학습자는 평소 편의점에서 사는 품목을 밝히기만 하면 되며, 언제 또는 왜 사는지에 관한 추가 세부 정보는 선택 사항이다.'),
    ('prompt-intro-v2-0269', '학습자는 유용하다고 판단하는 저렴한 품목을 선택해야 하며, 그 유용성을 뒷받침하려면 이점, 이유, 예시 또는 세부 정보 중 하나가 필요하다.'),
    ('prompt-intro-v2-0270', '가격이 비싸지만 그만한 가치가 있다고 판단하는 품목을 답변에 밝혀야 하며, 독립적인 정당화 하나를 덧붙여야 근거 없이 품목명만 제시하는 것을 피할 수 있다.'),
    ('prompt-intro-v2-0271', '질문은 학습자가 과도하다고 여기는 지출 범주를 묻고, 그 평가에 필요한 맥락을 더하려면 이유, 구체적인 시점, 결과 또는 감정 중 하나를 덧붙여야 한다.'),
    ('prompt-intro-v2-0272', '학습자는 돈을 저축하는 목적이나 원하는 결과를 밝혀야 하며, 이것이 요청된 목표를 직접 구성한다.'),
    ('prompt-intro-v2-0273', '10,000원이라는 빠듯한 한도 안에서 선물을 추천하는 과제이다. 제안한 선물이 좋은 이유를 뒷받침하려면 한 가지 이유나 실용적인 세부 사항을 덧붙여야 한다.'),
    ('prompt-intro-v2-0274', '학습자는 50,000원 미만의 선물을 추천해야 한다. 추천을 의미 있게 만들려면 이를 뒷받침하는 이유, 특징, 이점 또는 예시를 한 가지 덧붙여야 한다.'),
    ('prompt-intro-v2-0275', '학습자는 윈도 쇼핑을 즐기는지 말하고 그 이유 또는 그렇지 않은 이유를 설명해야 한다. 추가로 요구되는 깊이 없이 두 가지 명시적 조건을 모두 충족하면 된다.'),
    ('prompt-intro-v2-0276', '구매 전에 학습자가 평소에 하는 확인 행동을 직접 묻는 질문이다. 구체적인 확인 한 가지면 충분하다.'),
    ('prompt-intro-v2-0277', '학습자는 최근 구매 중 긍정적으로 평가하는 것을 밝혀야 한다. 무엇이 좋았는지 보여 주려면 이유, 이점, 세부 사항 또는 구체적인 시점 중 한 가지를 덧붙여야 한다.'),
    ('prompt-intro-v2-0278', '답변은 나쁘다고 평가한 최근 구매를 제시한다. 그 부정적 평가를 설명하려면 독립적인 이유, 결과, 세부 사항 또는 시점 중 한 가지가 필요하다.'),
    ('prompt-intro-v2-0279', '가상의 방 구매 상황에서는 선택한 물건이 필요하다. 폭넓은 선택을 유용하게 만들려면 이유, 이점, 세부 사항 또는 놓을 위치 중 한 가지를 덧붙여야 한다.'),
    ('prompt-intro-v2-0280', '학습자는 사랑하는 사람을 위해 무엇을 살지 선택해야 한다. 선물 선택에 내용을 더하려면 이유, 개인적인 세부 사항, 감정 또는 기대하는 이점 중 한 가지를 덧붙여야 한다.'),
    ('prompt-intro-v2-0281', '폭넓은 건강 습관 질문은 행동을 요구한다. 단순한 활동만 제시하는 답변이 되지 않도록 시점, 추가 행동, 이유, 결과 또는 장소 중 한 가지를 더해야 한다.'),
    ('prompt-intro-v2-0282', '좋아하는 건강식을 한 가지 말하는 좁은 개인 선호 질문이다. 음식 선택만으로 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0283', '학습자가 즐겨 먹는 건강에 좋지 않은 음식 한 가지를 묻는 질문이다. 해당 음식의 이름을 말하면 단순한 선호 과제를 충족한다.'),
    ('prompt-intro-v2-0284', '학습자는 걷기에 대한 긍정적 또는 부정적 선호를 밝히고 명시적으로 요청된 설명을 제공해야 한다.'),
    ('prompt-intro-v2-0285', '학습자가 달리기를 좋아하는지와 그 이유 또는 그렇지 않은 이유를 직접 묻는 질문이다. 의견과 이유만으로 완전한 답변이 된다.'),
    ('prompt-intro-v2-0286', '운동을 시도하고 싶다는 의도는 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 앞으로 시도할 운동의 선택이므로 GOAL보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0287', '학습자가 개인적으로 쉽다고 느끼는 운동을 밝히는 질문이다. 운동 이름을 말하면 요청된 사실을 충분히 제시할 수 있다.'),
    ('prompt-intro-v2-0288', '학습자는 자신에게 어려운 운동을 말해야 한다. 이 간단한 질문에서는 설명이나 예시가 선택적인 보충 내용이다.'),
    ('prompt-intro-v2-0289', '운동 후 학습자의 감정을 직접 묻는 질문이다. 분명하게 표현한 감정 한 가지면 초급 답변을 완성할 수 있다.'),
    ('prompt-intro-v2-0290', '감기에 걸린 것이 주어진 문제이며, 학습자는 이에 대응하기 위해 하는 행동을 말해야 한다.'),
    ('prompt-intro-v2-0291', '두통이 이미 어려움으로 제시되어 있으므로, 필요한 내용은 학습자가 그 상태를 다루는 방법이다.'),
    ('prompt-intro-v2-0292', '몸이 피곤하다는 문제가 제시되고 학습자가 이에 대응해 무엇을 하는지 묻는 질문이므로, 해결 행동이 필수 내용이다.'),
    ('prompt-intro-v2-0293', '질문은 학습자의 숙면에 도움이 되는 요인을 폭넓게 묻고 있으며, 유효한 답은 습관, 물건, 환경 조건 또는 다른 보조 수단일 수 있다. DETAIL은 행동이 아닌 답을 제외하지 않으면서 이 열린 요인을 포착하고, 관련 행동은 선택 사항으로 둘 수 있다.'),
    ('prompt-intro-v2-0294', '학습자는 숙면을 방해하는 요인만 제시한다. 질문에서 대처나 대응을 요구하지 않으므로, 이는 문제와 해결책을 함께 묻는 과제가 아니라 개인적인 사실 설명이다.'),
    ('prompt-intro-v2-0295', '더 넓은 목표나 계획이 아니라 원하는 취침 시간만 묻는 질문이다. 답변은 특정 시간에 대한 집중적인 설명이다.'),
    ('prompt-intro-v2-0296', '학습자는 원하는 기상 시간만 말한다. 더 넓은 목표, 준비 또는 앞으로의 단계는 필요하지 않으므로, 이는 특정 시간에 대한 집중적인 설명이다.'),
    ('prompt-intro-v2-0297', '학습자는 건강에 좋다고 판단하는 습관을 밝혀야 한다. 그 판단을 뒷받침하려면 이점, 이유, 예시 또는 구체적인 시점 중 한 가지를 덧붙여야 한다.'),
    ('prompt-intro-v2-0298', '건강에 해롭다고 판단하는 습관을 묻는 질문이다. 습관의 이름을 넘어 필요한 의미를 더하려면 결과, 이유, 예시 또는 가능한 해결책 중 한 가지를 덧붙여야 한다.'),
    ('prompt-intro-v2-0299', '학습자는 줄이려고 하는 음식이나 음식 범주를 말해야 하며, 이것만으로 간단한 식단 목표가 완성된다.'),
    ('prompt-intro-v2-0300', '식단에서 무엇을 늘리고 싶은지 묻는 질문이므로, 원하는 식습관 변화가 필수 목표이다.'),
    ('prompt-intro-v2-0301', '영화를 다시 보고 싶다는 미래 의도는 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 다시 볼 영화의 선택이므로 GOAL보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0302', '학습자가 웃었던 일과 관련된 특정 영화를 묻는 질문이다. 그 영화의 이름을 말하면 간단한 기억 과제가 완성된다.'),
    ('prompt-intro-v2-0303', '학습자는 자신을 울게 만든 영화를 밝혀야 한다. 장면의 세부 사항이나 감정은 답변을 풍부하게 할 수 있지만 필수는 아니다.'),
    ('prompt-intro-v2-0304', '표현은 학습자에게 좋아하는 드라마의 제목을 말하도록 요구한다. 깊이 수준 0에 적합한 직접적인 제목 기반 선호이다.'),
    ('prompt-intro-v2-0305', '학습자는 좋아하는 드라마 등장인물을 선택해야 하며, 초급자용으로 범위가 좁은 질문이므로 등장인물의 정체만 밝혀도 충분하다.'),
    ('prompt-intro-v2-0306', '질문은 선호하는 이야기의 종류를 폭넓게 묻기 때문에, 장르 선택에 이유, 예시, 느낌 또는 설명적 세부 사항 중 하나를 덧붙여야 한다.'),
    ('prompt-intro-v2-0307', '학습자는 해피엔딩을 좋아하는지 밝히고 그 이유 또는 좋아하지 않는 이유를 설명해야 하므로, 두 가지 명시적 요구 사항을 모두 충족해야 한다.'),
    ('prompt-intro-v2-0308', '질문은 무서운 영화에 대한 선호 판단과 그 판단을 뒷받침하는 이유를 직접 요구한다.'),
    ('prompt-intro-v2-0309', '완전한 답변은 학습자가 액션 영화를 좋아하는지 밝히고 요청된 설명을 제시해야 한다. 예시는 선택 사항이다.'),
    ('prompt-intro-v2-0310', '표현은 학습자에게 로맨스 영화에 대한 긍정적 또는 부정적 견해와 그 견해의 이유를 함께 말하도록 요구한다.'),
    ('prompt-intro-v2-0311', '질문은 학습자가 보통 기분이 좋을 때 어떤 음악을 선택하는지 묻는다. 그 음악을 밝히면 조건에 따른 일상적 선택에 답한 것이다.'),
    ('prompt-intro-v2-0312', '학습자는 슬플 때 듣는 음악을 말해야 하며, 그 음악이 정서에 미치는 영향이나 이유는 선택 사항이다.'),
    ('prompt-intro-v2-0313', '표현은 학습자에게 평소 공부할 때 선택하는 음악을 묻는다. 선택한 음악을 말하면 범위가 좁은 일상 사실에 충분히 답한 것이다.'),
    ('prompt-intro-v2-0314', '학습자는 좋아하는 가수 또는 밴드를 밝혀야 한다. 이름을 말한 음악가만으로도 이 직접적인 입문 선호 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0315', '특정 노래를 잘 부르고 싶은 것은 미래의 목표이므로, 그 노래를 밝히면 목표를 충분히 표현한 것이다.'),
    ('prompt-intro-v2-0316', '책을 읽고 싶다는 미래의 읽기 의도는 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 선택하는 책이나 읽기 대상이므로 GOAL보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0317', '이 질문은 학습자가 어린 시절 좋아했던 이야기를 묻는다. 과거에 좋아했던 이야기를 말하면 간단한 기억 기반 선호 과제를 충족한다.'),
    ('prompt-intro-v2-0318', '등장인물을 만나고 싶다는 가상의 의도는 질문에 이미 제시되어 있다. 직접 묻는 내용은 학습자가 선택하는 인물이므로 GOAL보다 CHOICE가 더 정확하다.'),
    ('prompt-intro-v2-0319', '질문은 학습자가 선호하는 영화 간식을 묻는다. 간식 선택만으로도 완전한 초급자 답변이 된다.'),
    ('prompt-intro-v2-0320', '학습자는 보통 휴식을 위해 선택하는 프로그램을 말해야 한다. 그 프로그램의 진정 효과나 시기는 덧붙일 수 있지만 필수는 아니다.'),
    ('prompt-intro-v2-0321', '질문은 학습자에게 아침과 밤 중 하나를 명시적으로 선택하고, 그 시간대를 선호하는 이유를 설명하도록 요구한다.'),
    ('prompt-intro-v2-0322', '학습자는 고양이와 개 중 하나를 선택하고 이유를 제시해야 하며, 이 두 가지가 함께 두 부분으로 이루어진 선호 질문에 완전히 답한다.'),
    ('prompt-intro-v2-0323', '완전한 답변은 여름과 겨울 중 하나를 선택하고 그 계절을 선호하는 이유를 말해야 한다. 계절과 관련된 예시는 선택 사항이다.'),
    ('prompt-intro-v2-0324', '표현은 봄과 가을 중 하나를 선택하고 그 계절을 더 좋아하는 이유를 말하도록 직접 요구한다.'),
    ('prompt-intro-v2-0325', '학습자는 커피와 주스 중 하나를 선택하고 음료 선호를 설명해야 하므로, 추가적인 뒷받침 요소는 필요하지 않다.'),
    ('prompt-intro-v2-0326', '질문은 밥과 면 중 하나를 선택하고 그 음식 선호의 이유를 말하도록 요구한다.'),
    ('prompt-intro-v2-0327', '학습자는 빵과 밥 중 하나를 선택하고 그 선택을 정당화해야 하며, 두 가지 명시적 요구 사항을 통해 충분한 깊이를 제공한다.'),
    ('prompt-intro-v2-0328', '과제는 버스와 지하철 중 선호하는 교통수단과 그 이유를 요구한다. 이동할 때의 효과나 예시는 선택적으로 선택을 더 분명하게 할 수 있다.'),
    ('prompt-intro-v2-0329', '학습자는 책과 동영상 중 하나를 선택하고 그 매체를 선호하는 이유를 설명해야 하며, 이는 명시된 두 가지 요구 사항을 모두 충족한다.'),
    ('prompt-intro-v2-0330', '질문은 문자 메시지와 대화 중 하나의 의사소통 방식을 선택하고 그 이유를 말하도록 직접 요구한다.'),
    ('prompt-intro-v2-0331', '학습자는 요리하기와 외식하기 중 하나를 선택하고 그 식사 관련 선호를 설명해야 한다. 예시는 선택 사항이다.'),
    ('prompt-intro-v2-0332', '표현은 집에 있는 것과 밖에 있는 것 중 선호하는 환경을 밝히고 그 선택을 뒷받침하는 이유를 말하도록 요구한다.'),
    ('prompt-intro-v2-0333', '학습자는 조용한 음악과 큰 음악 중 하나를 선택하고 그 음량을 선호하는 이유를 설명해야 한다.'),
    ('prompt-intro-v2-0334', '완전한 답변은 단순한 옷과 화려한 옷 중 하나를 선택하고, 그 스타일 선호에 대해 명시적으로 요청된 이유를 제시해야 한다.'),
    ('prompt-intro-v2-0335', '학습자는 계획적으로 행동할지 자유롭게 행동할지 선택한 다음, 그 방식이 자신에게 적합한 이유를 설명해야 한다.'),
    ('prompt-intro-v2-0336', '질문은 소규모 집단과 대규모 집단 중 하나를 명시적으로 선택하고, 학습자의 사회적 선호에 대한 이유를 말하도록 요구한다.'),
    ('prompt-intro-v2-0337', '학습자는 사진을 찍는 것과 사진에 나오는 것 중 하나를 선택하고, 그 역할을 선호하는 이유를 설명해야 한다.'),
    ('prompt-intro-v2-0338', '답변은 패스트푸드와 집밥 중 하나를 선택하고 그 이유를 밝혀야 하며, 선택과 그 근거를 모두 이미 요구하고 있다.'),
    ('prompt-intro-v2-0339', '학습자는 도시 생활과 시골 생활 중 하나를 선택하고, 그 생활 방식을 선호하는 이유를 제시해야 한다.'),
    ('prompt-intro-v2-0340', '문구는 혼자 일하는 것과 팀으로 일하는 것 중 하나를 선택하고, 그러한 업무 선호를 설명하도록 요구한다.'),
    ('prompt-intro-v2-0341', '학습자는 제시된 주간에 시작하려는 습관을 하나 말해야 하며, 그 습관 자체가 분명한 단기 목표를 이룬다.'),
    ('prompt-intro-v2-0342', '질문은 학습자가 이번 주에 그만두려는 습관이 무엇인지 묻는다. 대상 습관을 밝히는 것만으로도 변화 목표가 충분히 제시된다.'),
    ('prompt-intro-v2-0343', '학습자는 매일 아침의 일부로 만들고 싶은 행동을 하나 말해야 하며, 이는 의도한 일과를 직접 표현한다.'),
    ('prompt-intro-v2-0344', '문구는 매일 밤 하고 싶은 행동을 하나 요구하므로, 의도한 일과를 말하면 간단한 목표 질문에 답한 것이다.'),
    ('prompt-intro-v2-0345', '학습자는 매일 연습하고 싶은 기술이나 활동을 하나 밝혀야 하며, 이는 요청된 반복 목표를 직접 제시한다.'),
    ('prompt-intro-v2-0346', '매일 10분이라는 고정 조건은 이미 제시되어 있고, 학습자는 그 일과 안에서 무엇을 배우고 싶은지 말해야 한다.'),
    ('prompt-intro-v2-0347', '질문은 학습자가 빈도를 줄이려는 활동을 묻으며, 그 활동 자체가 완전한 희망 변화에 해당한다.'),
    ('prompt-intro-v2-0348', '학습자는 더 자주 하고 싶은 활동을 말해야 하며, 이는 앞으로 의도한 습관을 직접 정의한다.'),
    ('prompt-intro-v2-0349', '학습자는 오늘 달성할 수 있는 작은 목표를 밝혀야 하며, 목표 자체로 이 구체적인 계획 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0350', '질문은 일주일 안에 완료할 수 있는 실행 가능한 목표를 요구하며, 단계와 결과는 선택적으로 추가할 수 있다.'),
    ('prompt-intro-v2-0351', '질문은 학습자가 습관을 유지하는 데 도움이 되는 요인을 폭넓게 묻는다. 유효한 답은 알림, 사람, 체계, 환경 조건, 전략 또는 행동일 수 있으므로 GENERAL_DESCRIPTION과 DETAIL이 비행동 요인까지 포괄하고 ACTION은 선택 사항으로 남는다.'),
    ('prompt-intro-v2-0352', '질문은 습관을 유지하는 데 방해가 되는 요소만 묻는다. 학습자는 답변이나 해결책을 제시할 필요가 없으므로, 답변은 문제와 해결책을 함께 제시하는 구조가 아니라 일반적인 설명이다.'),
    ('prompt-intro-v2-0353', '학습자는 자신의 목표를 도와줄 수 있는 사람을 밝혀야 하며, 이는 사실을 묻는 질문을 완성하는 구체적인 개인 정보이다.'),
    ('prompt-intro-v2-0354', '문구는 영어 학습 목표 하나를 직접 요구하며, 원하는 학습 결과를 명확히 말하면 입문 수준의 답변으로 충분하다.'),
    ('prompt-intro-v2-0355', '학습자는 원하는 건강상의 결과를 하나 말해야 한다. 방법, 동기, 시점은 유용하지만 명시적으로 요구되지는 않는다.'),
    ('prompt-intro-v2-0356', '질문은 돈과 관련된 목표 하나를 요구하므로, 의도한 재정적 결과를 말하면 초급자의 직접적인 과제가 완성된다.'),
    ('prompt-intro-v2-0357', '학습자는 자신의 집에 대해 원하는 변화나 결과를 밝혀야 하며, 실행 세부 사항은 선택적으로 제시할 수 있다.'),
    ('prompt-intro-v2-0358', '질문은 여가 시간과 관련해 원하는 결과 하나를 직접 묻고 있으며, 그 목표를 말하는 것만으로도 이 수준에서는 충분하다.'),
    ('prompt-intro-v2-0359', '학습자는 목표를 달성한 뒤 취할 계획인 다음 행동을 밝혀야 하며, 다음 단계 하나를 말하면 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0360', '학습자는 개인적인 자부심과 관련된 목표를 밝혀야 하며, 그 목표를 달성하는 것이 왜 중요한지 분명히 하도록 이유, 느낌, 계획 또는 결과 중 하나를 제시해야 한다.'),
    ('prompt-intro-v2-0361', '질문은 누군가를 처음 만났을 때 사용하는 말이나 인사를 묻는다. 해당 의사소통 행동을 제시하면 이 간단한 입문 과제에 충분히 답한 것이다.'),
    ('prompt-intro-v2-0362', '학습자는 늦게 도착한 뒤 자신이 하는 말만 밝혀야 한다. 사과나 다른 발화를 제시하면 충분하며, 늦은 원인은 선택적으로 덧붙일 수 있다.'),
    ('prompt-intro-v2-0363', '직접적으로 요구되는 것은 도움을 요청할 때 사용하는 표현이며, 이 초급 질문에서는 근본적인 문제를 설명할 필요가 없다.'),
    ('prompt-intro-v2-0364', '질문은 학습자가 감사를 표현하기 위해 하는 말을 묻는다. 그 발화를 말하면 충분하며, 감사를 하게 된 계기는 추가 맥락으로 제시할 수 있다.'),
    ('prompt-intro-v2-0365', '요구되는 답변은 학습자가 실수한 뒤 하는 말이다. 실수의 내용이나 이를 바로잡는 방법을 설명하면 더 확장할 수 있지만, 기본 답변에는 필요하지 않다.'),
    ('prompt-intro-v2-0366', '이 질문은 학습자가 새 친구를 만날 때 보통 하는 행동을 묻는다. 범위가 명확한 사회적 상황이므로 분명한 행동 하나로 답할 수 있다.'),
    ('prompt-intro-v2-0367', '질문은 선물을 받을 때 학습자가 평소에 하는 반응을 묻고 있으므로, 준 사람에게 감사하는 것과 같은 단일 행동이면 초급자에게 완전한 답변이 된다.'),
    ('prompt-intro-v2-0368', '화난 사람 주변에서 학습자가 보통 무엇을 하는지 묻는 표현이다. 답변에는 행동이 필요하며, 그 이유나 효과는 선택 사항이다.'),
    ('prompt-intro-v2-0369', '누군가 친절하게 행동할 때의 평소 반응을 말하는 과제이다. 하나의 구체적인 반응이면 이 간단한 상황 질문에 답할 수 있다.'),
    ('prompt-intro-v2-0370', '학습자는 수줍음을 느낄 때 일반적으로 무엇을 하는지 말해야 한다. 조건이 이미 제시되어 있으므로 추가 세부 내용은 필수가 아니다.'),
    ('prompt-intro-v2-0371', '친구를 만나기 전에 평소에 하는 준비 행동을 묻는 질문이다. 이 수준에서는 한 가지 행동이면 충분하지만, 시점이나 다른 준비를 덧붙이면 상황을 더 잘 설명할 수 있다.'),
    ('prompt-intro-v2-0372', '친구를 만난 후 평소에 하는 행동을 직접 묻는 질문이다. 만남 후의 단일 행동 하나면 이 초점이 분명한 초급 과제를 완성할 수 있다.'),
    ('prompt-intro-v2-0373', '새로운 사람들과 보통 어떤 주제로 대화하는지 묻는 질문이다. 하나의 독립적인 이유나 예시가 있어야 넓은 일상 습관에 대한 답변이 단순한 주제명으로 끝나지 않는다.'),
    ('prompt-intro-v2-0374', '학습자가 이야기하기 쉽다고 느끼는 주제를 하나만 말하면 된다. 이는 간단한 개인적 사실이므로, 왜 쉬운지 설명하는 것은 선택 사항이다.'),
    ('prompt-intro-v2-0375', '학습자가 이야기하기 어려워하는 주제를 하나 말하는 것이 직접적인 요구이다. 그 원인이나 예시는 답변을 풍부하게 할 수 있지만 필수는 아니다.'),
    ('prompt-intro-v2-0376', '학습자는 대화를 즐기는 원인만 제시하며, 별도의 판단이나 입장을 말할 필요는 없다. 원인만 제시하는 답변은 GENERAL_DESCRIPTION에 해당한다.'),
    ('prompt-intro-v2-0377', '대화를 어렵게 만드는 원인만 묻는 질문이며, 그 원인에 더해 의견이나 입장을 요구하지 않는다. 답변 형태는 REASON을 포함한 GENERAL_DESCRIPTION이다.'),
    ('prompt-intro-v2-0378', '새 친구에게 할 만한 좋은 질문을 추천하라는 요청이다. 추천하는 질문을 말하면 충분하며, 억지로 근거를 덧붙일 필요는 없다.'),
    ('prompt-intro-v2-0379', '대화를 시작하는 방법에 대한 추천 질문이며, 적절한 시작 방법 하나로 이 간단한 질문에 충분히 답할 수 있다.'),
    ('prompt-intro-v2-0380', '대화를 마무리하는 좋은 방법을 묻는 질문이므로, 추천하는 마무리 방법이 필요하며 그것만으로도 적절한 초급 답변이 된다.'),
    ('prompt-intro-v2-0381', '날 수 있다는 것은 이미 주어진 가정이고, 학습자는 목적지만 말한다. 이는 표현된 선호가 아니며, 어디인지를 묻는 의무에는 CHOICE가 아니라 PLACE가 필요하다.'),
    ('prompt-intro-v2-0382', '학습자는 보이지 않는 상태에서 할 가상의 행동을 설명한다. 질문은 선호나 선택지 사이의 선택을 요구하지 않는다.'),
    ('prompt-intro-v2-0383', '어떤 동물을 만나고 싶은지 선택해야 한다. 이유나 상상한 상호작용이 있어야 답변이 동물 이름만으로 끝나지 않는다.'),
    ('prompt-intro-v2-0384', '살고 싶은 영화 속 세계를 하나 선택해야 한다. 이 가정적 상황은 제목만 말하는 것보다 더 많은 내용을 요구하므로, 뒷받침하는 이유나 세부 내용 하나가 적절하다.'),
    ('prompt-intro-v2-0385', '저녁 식사를 함께할 사람을 선택하는 것이 필수 답변이며, 이유나 제안하는 대화 하나를 덧붙이면 단순한 이름 제시를 넘어서는 독립적인 생각이 된다.'),
    ('prompt-intro-v2-0386', '학습자는 초능력 하나를 선택해야 한다. 그 초능력이 매력적인 이유나 사용 목적을 설명하면, 이처럼 범위가 넓은 선택에 기대되는 추가 깊이를 제공할 수 있다.'),
    ('prompt-intro-v2-0387', '새 이름을 선택하는 것이 직접적인 답변이며, 이유나 느낌 하나를 덧붙이면 개인적인 가정이 이름만 말하는 것보다 의미 있어진다.'),
    ('prompt-intro-v2-0388', '꿈의 방을 시각적으로 묘사해야 하며, 독립적인 용도나 느낌 또는 디자인 동기 하나가 있어야 넓은 묘사가 단일 형용사로 끝나지 않는다.'),
    ('prompt-intro-v2-0389', '필수 선택은 상상한 가게에서 팔거나 제공할 상품 또는 서비스이다. 독립적인 이유, 제공 항목의 세부 내용, 의도한 결과 또는 장소 하나를 덧붙이면 사업 아이디어에 유용한 깊이가 생긴다.'),
    ('prompt-intro-v2-0390', '새로 만든 휴일이 무엇인지 설명해야 하며, 이름만 제시하는 수준을 넘어 개념을 발전시키려면 활동, 날짜, 목적 또는 효과 중 하나가 필요하다.'),
    ('prompt-intro-v2-0391', '무료 표는 가정으로 주어진 조건이고, 학습자는 어디로 갈지에 답해 목적지, 장소, 명소 또는 유료 행사를 제시한다. PLACE가 이 목적지 관계를 담으며, 독립적인 보강 정보 하나가 가정적 답변에 적절한 깊이를 더한다.'),
    ('prompt-intro-v2-0392', '학습자는 즉시 습득하고 싶은 기술을 선택한다. 그 기술의 유용성이나 사용 목적을 덧붙이면 이 상상 속 선택에 적절한 추가 근거가 된다.'),
    ('prompt-intro-v2-0393', '추가로 배우고 싶은 언어를 선택하는 것이 필수 답변이며, 동기나 용도 또는 관련 장소 하나를 덧붙여야 언어 이름만 말하고 끝나지 않는다.'),
    ('prompt-intro-v2-0394', '오늘 선호하는 날씨를 좁은 범위에서 묻는 질문이다. 날씨 상태를 말하면 간단한 완전 답변이 되며, 이유는 선택 사항이다.'),
    ('prompt-intro-v2-0395', '가능한 반려동물을 하나 선택하고, 이유나 상상한 활동 하나를 덧붙이는 것이 유용하다. 그래야 넓은 선호가 동물 이름만 제시하는 데서 끝나지 않는다.'),
    ('prompt-intro-v2-0396', '발명한 앱의 기능을 묻는 질문이다. 해결하려는 문제, 기능의 세부 내용 또는 결과 중 하나가 있어야 제안한 기능이 구체적으로 드러난다.'),
    ('prompt-intro-v2-0397', '완벽한 아침 식사로 무엇을 먹을지 선택한다. 독립적인 세부 내용이나 이유 하나를 덧붙이면 답변이 음식 하나만 제시하는 수준을 넘어선다.'),
    ('prompt-intro-v2-0398', '바닷가에서 보내는 일상적인 반복 활동을 상상하는 질문이다. 추가 행동, 시점에 대한 세부 내용 또는 효과 하나가 있으면 반복 활동에 충분한 맥락이 생긴다.'),
    ('prompt-intro-v2-0399', '학습자는 산 근처에서 상상한 일상 활동을 말해야 하며, 별도의 시간, 동기, 감정 또는 두 번째 행동을 하나 덧붙여야 단순한 활동 나열에 그치지 않는다.'),
    ('prompt-intro-v2-0400', '이 제한 없는 가상의 선물 선호 질문은 선물 명사만 답하면 내용이 충분히 발전하지 않은 것으로 본다. 입문 단계에서도 독립적인 이유, 이점, 감정 또는 세부 사항을 하나 제시하는 것이 적절하다.'),
    ('prompt-opinion-01', '질문은 성공한 기업의 사회적 책임을 제안하게 하지만 여러 근거를 명시적으로 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 의견을 충분히 뒷받침한다.'),
    ('prompt-opinion-02', '학습자는 성공한 기업이 사회에 더 많이 기여해야 하는지 판단하고, 그 이유를 명시적으로 설명해야 한다. 이 두 가지 필수 요소만으로도 충분한 깊이가 확보된다.'),
    ('prompt-opinion-03', '문항은 중요한 기업의 역할 하나와 그 역할이 중요한 이유를 요구하므로, 필수 입장과 그 정당화만으로도 답변이 충분히 발전한다.'),
    ('prompt-opinion-04', '이 질문은 성공한 기업이 어떤 책임을 지며 그 책임이 무엇 때문에 중요한지를 직접 묻는다. 판단과 설명을 함께 제시하면 이미 독립적인 깊이가 형성된다.'),
    ('prompt-opinion-05', '기업의 사회적 책임에 대한 권장 방안과 그 이유가 모두 명시적인 필수 요소이므로, 선택적인 추가 근거는 유익하지만 필수는 아니다.'),
    ('prompt-opinion-06', '질문은 대도시 대중교통의 책임을 묻지만 여러 뒷받침 항목을 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 의견을 충분히 발전시킨다.'),
    ('prompt-opinion-07', '학습자는 대도시의 대중교통이 사회를 위해 더 많은 일을 해야 하는지 판단하고 그 이유를 제시해야 한다. 명시적인 입장과 정당화만으로 충분하다.'),
    ('prompt-opinion-08', '도시 대중교통의 중요한 역할 하나와 그 역할을 선택한 이유가 모두 요구되므로, 추가적인 깊이 요소를 억지로 요구할 필요는 없다.'),
    ('prompt-opinion-09', '이 과제는 제안한 대중교통의 책임과 그 중요성에 대한 설명을 명시적으로 결합한다. 이 필수 의미 단위들만으로도 답변이 충분히 발전한다.'),
    ('prompt-opinion-10', '학습자는 대도시 대중교통의 사회적 책임을 밝히고 그것이 왜 중요한지 설명해야 하므로, 예시나 결과는 선택적인 보충 내용으로 남는다.'),
    ('prompt-opinion-11', '질문은 금융 역량 교육 기관의 책임을 묻지만 여러 형태의 근거를 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 제안한 책임을 충분히 설명한다.'),
    ('prompt-opinion-1101', '학습자는 현대 사회에서 동네 공원이 맡아야 할 역할을 제안한다. 그 역할을 뒷받침하려면 이유, 지역사회에 미치는 영향 또는 구체적인 예시를 하나 제시해야 한다.'),
    ('prompt-opinion-1102', '질문은 공공 박물관의 지역사회 책임에 대한 판단을 요구하지만 별도의 뒷받침 항목들을 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 세부 내용 중 하나면 답변을 충분히 발전시킨다.'),
    ('prompt-opinion-1103', '이 문항은 지역 서점이 사람들을 위해 무엇을 해야 하는지 묻는다. 따라서 제안이 필수이며, 이를 뒷받침하는 이유 또는 구체적인 지역사회 이익을 하나 제시해야 한다.'),
    ('prompt-opinion-1104', '질문은 대학의 역할을 묻지만 교육, 연구, 공적 생활을 각각 논의하라고 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 의견을 충분히 뒷받침한다.'),
    ('prompt-opinion-1105', '학습자는 지역 뉴스 매체의 지역사회 책임을 제시해야 하지만 문항은 여러 근거를 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 그 책임을 충분히 뒷받침한다.'),
    ('prompt-opinion-1106', '이 질문은 편의점이 사람들을 어떻게 지원해야 하는지에 대한 제안을 요구한다. 정당화, 예시 또는 공공의 이익을 하나 제시하면 그 제안에 충분한 깊이가 더해진다.'),
    ('prompt-opinion-1107', '청소년 스포츠 동아리의 사회적 역할이 필수 판단이며, 초점이 분명한 제안을 뒷받침하기에는 이유 또는 청소년에게 미치는 결과 하나면 충분하다.'),
    ('prompt-opinion-1108', '질문은 공공 보건 캠페인의 책임을 묻지만 여러 뒷받침 항목을 명시적으로 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 제안을 충분히 설명한다.'),
    ('prompt-opinion-1109', '질문은 인공지능을 사용하는 기업이 무엇을 해야 하는지 묻지만 문제와 해결책을 모두 요구하지 않는다. 구체적인 이유, 문제, 해결책, 결과 또는 예시 중 하나면 입장을 충분히 발전시킨다.'),
    ('prompt-opinion-1110', '이 질문은 동물 보호소의 현대적 역할을 요구한다. 학습자가 제안한 역할을 뒷받침하려면 이유, 결과 또는 구체적인 예시를 하나 제시해야 한다.'),
    ('prompt-opinion-1111', '질문은 공영 방송사의 지역사회 책임을 묻지만 여러 뒷받침 항목을 명시적으로 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 그 책임을 충분히 설명한다.'),
    ('prompt-opinion-1112', '학습자는 지역 커뮤니티 센터가 사람들을 위해 무엇을 해야 하는지 제안해야 한다. 이유 또는 구체적인 영향 하나를 제시하면 그 제안이 충분히 발전한다.'),
    ('prompt-opinion-1113', '이 과제는 지역 농산물 직거래 장터의 사회적 역할을 묻는다. 제안한 역할과 함께 이를 뒷받침하는 이유, 지역사회 이익 또는 예시를 하나 제시해야 한다.'),
    ('prompt-opinion-1114', '문항은 방과 후 프로그램의 지역사회 책임을 묻지만 여러 독립적인 근거를 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 그 책임을 아동의 필요와 충분히 연결한다.'),
    ('prompt-opinion-1115', '질문은 기차역이 사람과 지역사회를 어떻게 지원해야 하는지 묻지만 두 대상이 별도의 두 답변을 요구하는 것은 아니다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 제안을 충분히 뒷받침한다.'),
    ('prompt-opinion-1116', '도시 자전거 시스템의 현대적 역할을 하나 제안해야 한다. 초점이 분명한 입장을 뒷받침하기에는 이유, 이동성의 결과 또는 구체적인 예시 하나면 충분하다.'),
    ('prompt-opinion-1117', '질문은 인턴십 제공자의 책임을 묻지만 기준과 영향을 각각 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 제안한 책임을 충분히 뒷받침한다.'),
    ('prompt-opinion-1118', '학습자는 음식물 쓰레기를 줄이는 식당이 사람들을 위해 무엇을 해야 하는지 제안한다. 정당화, 공공의 이익 또는 구체적인 예시 하나를 제시하면 그 제안이 발전한다.'),
    ('prompt-opinion-1119', '이 과제는 온라인 안전을 가르치는 학교의 사회적 역할을 묻는다. 제안한 교육적 역할을 뒷받침하려면 이유 또는 안전상의 결과를 하나 제시해야 한다.'),
    ('prompt-opinion-1120', '질문은 지방 정부가 폭염 대피소를 운영할 때의 책임을 묻지만 여러 뒷받침 범주를 요구하지 않는다. 구체적인 이유, 문제, 해결책, 결과 또는 예시 중 하나면 의견을 충분히 발전시킨다.'),
    ('prompt-opinion-1121', '질문은 문화 축제가 사람들을 위해 무엇을 해야 하는지 묻고 있으므로, 권장하는 기여가 발전된 의견이 되려면 한 가지 이유, 효과 또는 예시가 필요하다.'),
    ('prompt-opinion-1122', '학습자는 자원봉사 연결 플랫폼의 사회적 역할을 제안하므로, 그 역할을 뒷받침할 한 가지 이유, 결과 또는 구체적인 활용 사례면 충분하다.'),
    ('prompt-opinion-1123', '질문은 아파트 재활용 시설의 지역사회 역할을 묻고 있으므로, 한 가지 근거, 환경적 결과 또는 예시가 권고에 충분한 깊이를 더한다.'),
    ('prompt-opinion-1124', '요구되는 판단은 지역사회 텃밭이 사람들에게 무엇을 제공해야 하는지에 관한 것이며, 한 가지 이유나 지역사회 결과가 제안을 뒷받침해야 한다.'),
    ('prompt-opinion-1125', '학습자는 노인 센터의 현대적 역할을 제시해야 하므로, 한 가지 이유, 이점 또는 구체적인 예시가 이 구체적인 사회적 권고를 뒷받침한다.'),
    ('prompt-opinion-1126', '질문은 공공 수영장의 지역사회 책임을 묻지만 이용 기회, 안전, 서비스를 각각 요구하지 않는다. 구체적인 이유, 예시, 결과 또는 문제 중 하나면 판단을 충분히 뒷받침한다.'),
    ('prompt-opinion-1127', '질문은 지역 보건소가 사람들을 위해 무엇을 해야 하는지에 관한 권고를 요구하므로, 한 가지 이유나 건강 관련 결과가 제안을 충분히 발전시킨다.'),
    ('prompt-opinion-12', '학습자는 금융 역량 교육 기관이 사회를 위해 더 많은 일을 해야 하는지 판단하고 그 이유를 설명해야 하므로, 요구된 입장과 이유만으로 충분한 깊이가 형성된다.'),
    ('prompt-opinion-13', '금융 역량을 가르치는 학교의 중요한 역할 한 가지와 그 역할이 중요한 이유를 명시적으로 요구하므로, 추가 근거는 선택 사항이다.'),
    ('prompt-opinion-14', '질문은 금융 역량 교육 기관이 맡아야 할 의무와 그 의무가 중요한 이유에 대한 설명을 요구하므로, 서로 독립적인 이 두 의무만으로도 충분한 답변이 구성된다.'),
    ('prompt-opinion-15', '금융 역량을 가르치는 학교의 사회적 책임과 그 이유가 모두 직접 요구되므로, 예시와 효과는 선택 사항으로 남는다.'),
    ('prompt-opinion-16', '학습자는 지역 자원봉사의 현대적 사회 역할을 제안해야 하므로, 한 가지 이유, 지역사회 결과 또는 예시가 입장을 뒷받침하는 데 필요하다.'),
    ('prompt-opinion-17', '문구는 지역 자원봉사가 더 많은 일을 해야 하는지에 대한 판단과 그 판단의 이유를 요구하므로, 추가적인 깊이는 필수가 아니다.'),
    ('prompt-opinion-18', '답변은 지역 자원봉사의 중요한 역할 한 가지를 밝히고 그것이 중요한 이유를 설명해야 하므로, 이 두 가지 필수 요소만으로 과제에 충분히 답할 수 있다.'),
    ('prompt-opinion-19', '학습자는 지역 자원봉사의 의무와 그 의무가 중요한 이유를 직접 답해야 하므로, 의견과 설명만으로 충분하다.'),
    ('prompt-opinion-20', '질문은 지역 자원봉사의 사회적 책임 형태와 그 이유를 명시적으로 요구하므로, 예시나 결과는 선택 사항으로 둘 수 있다.'),
    ('prompt-opinion-21', '질문은 소셜 미디어 플랫폼의 책임에 대한 의견을 묻지만 여러 뒷받침 범주를 요구하지 않는다. 구체적인 이유, 문제, 해결책, 결과 또는 예시 중 하나면 제안한 책임을 충분히 발전시킨다.'),
    ('prompt-opinion-22', '학습자는 소셜 미디어 플랫폼이 사회를 위해 더 많은 일을 해야 하는지에 대한 입장을 취하고 그 이유를 설명해야 하므로, 이미 서로 독립적인 두 가지 요소가 제공된다.'),
    ('prompt-opinion-23', '질문은 소셜 미디어의 중요한 역할 한 가지와 그것이 중요한 이유를 요구하므로, 요구된 권고와 정당화만으로 충분한 깊이가 제공된다.'),
    ('prompt-opinion-24', '소셜 미디어 플랫폼의 의무와 그 의무가 중요한 이유에 대한 설명이 모두 명시적인 요구 사항이므로, 추가 예시나 효과는 선택 사항이다.'),
    ('prompt-opinion-25', '학습자는 소셜 미디어 플랫폼의 사회적 책임을 제안하고 그 이유를 설명해야 하므로, 이 필수 요소들만으로도 발전된 고급 수준의 답변이 구성된다.'),
    ('prompt-opinion-26', '질문은 공공 도서관의 현대적 역할을 묻고 있으므로, 권장하는 역할을 뒷받침할 한 가지 이유, 지역사회 이점 또는 예시가 필요하다.'),
    ('prompt-opinion-27', '공공 도서관이 더 많은 지원을 받아야 하는지는 요구된 판단이며, 명시적인 이유 제시 조항이 그 판단의 정당화를 요구하므로 추가적인 깊이는 필요하지 않다.'),
    ('prompt-opinion-28', '질문은 공공 도서관의 중요성을 판단하게 하지만 근거와 영향을 각각 요구하지 않는다. 구체적인 이유, 결과, 예시 또는 세부 내용 중 하나면 판단을 충분히 뒷받침한다.'),
    ('prompt-opinion-29', '과제는 사람들이나 기관이 공공 도서관에 대해 어떤 의무를 지는지 묻고 있으므로, 한 가지 구체적인 지원 행동, 이유 또는 효과가 제시된 책임을 발전시켜야 한다.'),
    ('prompt-opinion-30', '학습자는 공공 도서관을 확대하는 것에 대한 입장을 밝히고 이유를 제시해야 하므로, 이 직접적인 요구 사항만으로도 충분히 발전된 답변이 된다.'),
    ('prompt-opinion-31', '질문은 오늘날 공립학교에서 교복의 역할에 대한 판단을 요구하므로, 그 입장을 뒷받침할 한 가지 이유, 효과 또는 예시가 필요하다.'),
    ('prompt-opinion-32', '학습자는 공립학교 교복이 더 많은 지원을 받을 만한지 판단하고 그 이유를 설명해야 하므로, 입장과 요구된 이유만으로 충분한 깊이가 제공된다.'),
    ('prompt-opinion-33', '질문은 학교 교복의 중요성에 대한 판단을 요구하지만 여러 관점을 명시적으로 요구하지 않는다. 구체적인 이유, 결과, 예시, 장점 또는 단점 중 하나면 의견을 충분히 발전시킨다.'),
    ('prompt-opinion-34', '질문은 사람들이나 기관이 학교 교복을 지원하기 위해 어떤 책임을 지는지 묻고 있으므로, 제시된 의무에 한 가지 구체적인 행동이나 근거가 함께 제시되어야 한다.'),
    ('prompt-opinion-35', '학교 교복을 확대하는 것에 대한 입장과 그 이유가 모두 명시적으로 요구되므로, 선택적인 이점, 단점 또는 예시는 필수 사항일 필요가 없다.'),
    ('prompt-opinion-36', '학습자는 현대 사회에서 재활용 프로그램이 맡아야 할 역할을 제안해야 한다. 환경적 이유, 결과 또는 사례 하나만 제시해도 그 제안을 충분히 뒷받침할 수 있다.'),
    ('prompt-opinion-37', '문구상 재활용 프로그램에 대한 지원 확대 여부를 판단하고 설명해야 하므로, 입장과 이유만으로도 충분한 깊이가 형성된다.'),
    ('prompt-opinion-38', '질문은 재활용 프로그램의 중요성을 묻지만 근거와 영향을 각각 요구하지 않는다. 구체적인 이유, 결과, 예시 또는 문제 중 하나면 평가를 충분히 뒷받침한다.'),
    ('prompt-opinion-39', '학습자는 재활용 프로그램을 지원하기 위해 사람이나 기관이 져야 할 책임을 밝혀야 한다. 그 의무를 구체화하려면 실행 방안이나 이유 하나를 제시해야 한다.'),
    ('prompt-opinion-40', '질문은 재활용 프로그램 확대에 대한 의견과 그 근거를 직접 요구한다. 따라서 이 두 가지 필수 요소만으로 충분하며 억지로 내용을 추가할 필요는 없다.'),
    ('prompt-opinion-41', '질문은 사회에서 청소년 아르바이트가 어떤 역할을 해야 하는지 묻는다. 제안한 역할을 뒷받침하려면 이유, 청소년에게 미치는 결과 또는 사례 하나가 필요하다.'),
    ('prompt-opinion-42', '학습자는 청소년 아르바이트에 더 많은 지원을 해야 하는지 판단하고 그 이유 또는 반대 이유를 설명해야 한다. 필수적인 입장과 이유만으로 충분하다.'),
    ('prompt-opinion-43', '질문은 청소년 아르바이트의 중요성에 대한 판단을 요구하지만 여러 관점을 요구하지 않는다. 구체적인 이유, 결과, 예시, 장점 또는 단점 중 하나면 의견을 충분히 발전시킨다.'),
    ('prompt-opinion-44', '과제는 청소년 아르바이트를 지원하기 위해 사람이나 기관이 어떤 의무를 지는지 묻는다. 밝힌 책임에 구체적인 행동이나 정당화 근거 하나를 덧붙여야 한다.'),
    ('prompt-opinion-45', '청소년 아르바이트 확대에 대한 의견과 이유가 모두 명시적으로 요구되므로, 추가적인 이점이나 단점 또는 사례는 선택 사항이다.'),
    ('prompt-opinion-46', '학습자는 현대 사회에서 지역사회 예술 프로그램이 맡을 역할을 제안한다. 그 역할을 뒷받침하려면 이유, 지역사회에 미치는 영향 또는 사례 하나가 필요하다.'),
    ('prompt-opinion-47', '질문은 지역사회 예술 프로그램에 대한 지원 확대에 관한 입장과 그 이유 또는 반대 이유에 대한 설명을 직접 요구하므로, 충분한 깊이가 확보된다.'),
    ('prompt-opinion-48', '질문은 지역사회 예술 프로그램의 중요성을 판단하게 하지만 근거와 영향을 각각 요구하지 않는다. 구체적인 이유, 결과, 예시 또는 세부 내용 중 하나면 판단을 충분히 뒷받침한다.'),
    ('prompt-opinion-49', '학습자는 지역사회 예술 프로그램을 지원하기 위해 사람이나 기관이 져야 할 책임을 밝혀야 한다. 그 의무를 구체화하려면 구체적인 행동이나 이유 하나를 제시해야 한다.'),
    ('prompt-opinion-50', '질문은 지역사회 예술 프로그램 확대에 대한 입장과 설명을 요구하므로, 필수적인 의견과 이유만으로도 충분한 답변이 된다.'),
    ('prompt-preference-01', '학습자는 좋아하는 음식의 종류를 말하고 좋아하는 이유를 설명해야 한다. 필수적인 선택과 이유만으로도 이 중급 질문에 충분한 깊이를 제공한다.'),
    ('prompt-preference-02', '문구는 좋아하는 음식의 범주와 그것이 매력적인 이유에 대한 설명을 직접 요구한다. 따라서 이 두 가지 필수 의미 단위만으로 과제를 충분히 완성할 수 있다.'),
    ('prompt-preference-03', '학습자는 좋아하는 음식을 밝히고 설명하며, 요구된 두 가지 이유를 제시해야 한다. 구조의 필수 이유 항목이 명시적인 이유 제시 의무를 나타내므로 추가적인 깊이는 필요하지 않다.'),
    ('prompt-preference-04', '질문은 학습자가 좋아하는 음식에서 가장 마음에 드는 측면을 선택하고 그 이유를 설명하도록 한다. 따라서 필수적인 선택과 이유만으로 충분하다.'),
    ('prompt-preference-05', '학습자는 좋아하는 음식의 종류를 말하고 그것을 특별하게 만드는 개인적인 특성을 설명해야 한다. 이 두 가지 의무만으로도 충분한 깊이가 제공된다.'),
    ('prompt-preference-06', '‘보통’이라는 말은 반복적인 영화 선택 행동임을 나타내며, 학습자는 그러한 습관적인 선택이 자신의 기분에 어떻게 맞는지도 설명해야 한다.'),
    ('prompt-preference-07', '좋아하는 영화 장르와 그 장르가 매력적인 이유가 모두 직접 요구되므로, 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-preference-08', '답변은 좋아하는 영화 장르를 밝히고 그것을 좋아하는 서로 다른 두 가지 이유를 제시해야 한다. 명시된 이유들이 있으므로 답변은 충분히 전개된다.'),
    ('prompt-preference-09', '학습자는 좋아하는 장르에서 가장 마음에 드는 측면을 선택하고 그 측면이 돋보이는 이유를 설명한다.'),
    ('prompt-preference-10', '좋아하는 장르를 소개하려면 선택한 장르를 말해야 하고, 그것을 특별하게 만드는 요소를 설명하려면 개인적인 이유가 필요하다.'),
    ('prompt-preference-11', '이 집중형 장소 질문은 휴식을 위해 이용하는 장소와 그곳에서 편안함을 느끼게 하는 원인을 요구한다. 두 절이 각각 독립적으로 필수이다.'),
    ('prompt-preference-1101', '학습자가 바쁜 아침에 습관적으로 무엇을 먹는지와 그 아침 식사를 선택하는 이유를 묻는다. 따라서 일상적인 행동과 그 이유가 함께 요구된다.'),
    ('prompt-preference-1102', '더운 날의 과일은 선택한 선호 사항이며, 마지막 절에서 그것을 고르는 이유를 직접 요구한다.'),
    ('prompt-preference-1103', '답변은 비 오는 날 선호하는 음료를 말하고 그것이 그 상황에 어울리는 이유를 설명해야 한다.'),
    ('prompt-preference-1104', '무엇이 가장 중요한지 묻는 질문은 휴대전화 케이스의 핵심 기준에 대한 판단을 요구하며, 이어서 그 판단에 대한 필수적인 정당화가 필요하다.'),
    ('prompt-preference-1105', '학습자는 공책에 습관적으로 쓰는 내용을 설명하고, 그 내용을 쓰는 목적이나 동기를 설명한다.'),
    ('prompt-preference-1106', '학습자는 특정한 독서 장소를 제시하고 그곳이 편안하게 느껴지는 이유를 설명해야 한다.'),
    ('prompt-preference-1107', '답변에는 따뜻한 음식이 먹고 싶을 때 선택한 수프와 그 선호를 설명하는 이유가 필요하다.'),
    ('prompt-preference-1108', '일상 가방에 관한 표현은 반복적으로 가지고 다니는 습관과 언급된 물건을 가지고 다니는 이유를 묻는다.'),
    ('prompt-preference-1109', '보드게임 활동은 이미 제시되어 있으므로, 학습자는 구체적인 시기와 그때가 적절한 이유만 작성한다.'),
    ('prompt-preference-1110', '질문은 어휘를 공부하는 시기와 기억을 돕기 위해 사용하는 학습 방법을 별도로 요구한다.'),
    ('prompt-preference-1111', '학습자는 방에 편안함을 주는 향을 설명하고 그 향이 그런 효과를 내는 이유를 설명한다. 선호를 밝힐 필요는 없다.'),
    ('prompt-preference-1112', '이 구체적인 장소 과제는 학습자가 버스에서 어디에 앉는지와 그 장소가 자신에게 적합한 이유를 묻는다.'),
    ('prompt-preference-1113', '답변에는 구체적인 산책 시간과 경험을 더 좋게 만드는 날씨 상태에 대한 설명이 필요하다.'),
    ('prompt-preference-1114', '간단한 식사로 먹을 샌드위치의 선택과 그것을 좋아하는 이유를 모두 직접 요구한다.'),
    ('prompt-preference-1115', '자주 사용한다는 점에서 이 과제는 일상적인 습관을 묻는 과제이다. 학습자는 어떤 도구를 사용하는지 밝히고 자주 사용하는 이유를 설명한다.'),
    ('prompt-preference-1116', '학습자는 운동 수업에 참여하는 구체적인 시기와 꾸준히 참여하는 데 도움이 되는 수업 유형을 설명해야 한다.'),
    ('prompt-preference-1117', '질문은 학습자가 일상적으로 시청하는 온라인 창작자의 유형과 그 콘텐츠를 시청하는 이유를 묻는다.'),
    ('prompt-preference-1118', '학습자는 쉬는 시간에 먹을 간식을 선택하고 공부나 업무 중에 그것을 선호하는 이유를 설명한다.'),
    ('prompt-preference-1119', '답변에는 글을 쓸 때 편안하게 느껴지는 펜의 유형과 무엇이 그 펜을 편안하게 만드는지에 대한 설명이 필요하다. 선호를 밝힐 필요는 없다.'),
    ('prompt-preference-1120', '빵집에서 살 음식은 개인적인 선택이며, 학습자는 그것을 사는 이유도 설명해야 한다.'),
    ('prompt-preference-1121', '질문은 영화 관람 중 선호하는 간식과 그 간식이 영화 관람에 잘 맞는 이유를 직접 묻는다.'),
    ('prompt-preference-1122', '선호하는 여행 기념품과 그것을 집으로 가져오는 동기가 답변에 필요한 요소이다.'),
    ('prompt-preference-1123', '촛불을 사용하는 것은 이미 제시되어 있으므로, 학습자는 촛불을 사용하는 시기와 그 이유를 밝혀야 한다.'),
    ('prompt-preference-1124', '답변에는 사진을 정리하는 방법과 그 방법이 유용한 이유가 되는 실질적인 이점을 설명해야 한다.'),
    ('prompt-preference-1125', '학습자는 보통 차를 마시는 시기와 그러한 습관의 이유를 답해야 한다.'),
    ('prompt-preference-1126', '질문은 얇은 재킷을 가져가는 상황이나 시기와 그것을 가져가는 이유를 요구한다.'),
    ('prompt-preference-12', '학습자는 휴식에 이용하는 가장 좋아하는 장소를 밝히고 그 장소가 개인적으로 매력적인 이유를 설명해야 한다.'),
    ('prompt-preference-13', '좋아하는 휴식 장소와 그곳을 즐기는 두 가지 서로 다른 이유가 필요하므로, 이미 충분히 발전된 답변이 된다.'),
    ('prompt-preference-14', '이 표현은 장소만 묻는 것이 아니라 그곳에서 가장 좋아하는 것을 선택하고 그 선택을 정당화하도록 요구한다.'),
    ('prompt-preference-15', '답변은 좋아하는 휴식 장소를 소개하고 그곳을 특별하게 만드는 개인적인 특징이나 의미를 설명한다.'),
    ('prompt-preference-16', '학습자는 가장 좋아하는 계절에 하는 활동을 설명하고 그 계절이 좋은 이유를 설명해야 한다.'),
    ('prompt-preference-17', '질문은 좋아하는 계절과 그 계절이 학습자에게 매력적인 이유를 직접 요구한다.'),
    ('prompt-preference-18', '답변은 좋아하는 계절을 밝히고 그 계절을 즐기는 두 가지 이유를 제시해야 하며, 그 이유들이 필요한 답변의 깊이를 충족한다.'),
    ('prompt-preference-19', '학습자는 좋아하는 계절에서 가장 마음에 드는 요소를 선택하고 그 요소가 중요한 이유를 설명한다.'),
    ('prompt-preference-20', '좋아하는 계절을 밝히면 선택이 제시되고, 그 계절을 특별하게 만드는 점을 설명하면 필요한 개인적인 이유가 제시된다.'),
    ('prompt-preference-21', '답변에는 구체적으로 음악을 듣는 시기와 그 순간에 어울리는 음악의 유형을 설명해야 하며, 더 넓은 선호를 밝힐 필요는 없다.'),
    ('prompt-preference-22', '좋아하는 음악의 유형과 그 음악의 매력에 대한 설명을 모두 명시적으로 요구하므로, 추가적인 필수 근거는 필요하지 않다.'),
    ('prompt-preference-2201', '질문은 바쁜 아침에 아침 식사를 쉽게 먹게 하는 요인을 묻는다. 이 수준에서는 명확한 인과적 설명 하나면 충분하다.'),
    ('prompt-preference-2202', '학습자는 아침 식사에 단백질이나 에너지를 더하는 선호 방식을 설명하기만 하면 되며, 초급 수준의 좁은 행동을 묻는 질문이다.'),
    ('prompt-preference-2203', '답변에는 아침에 먹고 싶은 과일을 말하고 그 과일을 좋아하는 이유를 설명해야 한다.'),
    ('prompt-preference-2204', '이 좁은 과제는 아침 식사를 더 좋게 만들기 위해 무엇을 추가하는지 묻는다. 추가하는 것을 행동의 일부로 말하면 질문에 답한 것이다.'),
    ('prompt-preference-2205', '학습자는 하루의 시작을 돕는 빠른 아침 식사의 종류를 설명한다. 선호를 말하거나 별도로 설명할 필요는 없다.'),
    ('prompt-preference-2206', '질문은 간단한 아침 식사를 더 맛있게 하는 맛만 묻으므로, 구체적인 묘사 하나로 이 좁은 과제를 완성할 수 있다.'),
    ('prompt-preference-2207', '필수 내용은 토스트나 다른 간단한 아침 식사를 더 완전하게 만드는 학습자의 방법이다.'),
    ('prompt-preference-2208', '학습자는 주어진 시간이 제한된 상황에 적합한 간단한 식사를 말한다. 선호나 별도의 설명은 요구되지 않는다.'),
    ('prompt-preference-2209', '선호하는 도시락 반찬과 그 반찬을 챙기는 이유를 모두 말해야 한다.'),
    ('prompt-preference-2210', '답변에는 학습자가 만들기 좋아하는 간단한 식사와 그것을 만드는 경우를 밝혀야 한다.'),
    ('prompt-preference-2211', '학습자는 우유와 함께 먹는 간식을 고르고, 그 조합을 좋아하는 이유를 설명한다.'),
    ('prompt-preference-2212', '질문은 서두를 때 하는 음식 섭취 행동과 그 상황에서 그 음식을 고르는 이유를 묻는다.'),
    ('prompt-preference-2213', '학습자는 밥이나 다른 간단한 식사를 더 든든하게 만들기 위해 무엇을 올리는지 설명한다. 이러한 구체적인 행동이 질문을 충족한다.'),
    ('prompt-preference-2214', '이 가정 상황은 주어진 조용한 아침에 학습자가 무엇을 먹을지 묻는다. 따라서 필요한 구조는 선호를 주장하는 것이 아니라 하나의 행동이다.'),
    ('prompt-preference-2215', '답변에는 주어진 늦은 하루 시작 후에 도움이 되는 빠른 식사를 말해야 한다. 이 좁은 초급 질문에는 구체적인 식사 내용 하나면 충분하다.'),
    ('prompt-preference-2216', '과제는 주어진 짧은 휴식 시간에 적절하다고 느껴지는 작은 간식을 말하는 것이며, 뒷받침하는 내용을 요구하는 두 번째 절은 없다.'),
    ('prompt-preference-2217', '‘손이 가다’라는 표현은 짧은 휴식 중 평소에 간식을 집어 먹는 학습자의 행동을 묻는다. 휴식 상황 자체를 다시 말할 필요는 없다.'),
    ('prompt-preference-2218', '가정 상황의 표현은 주어진 조건에서 어떤 차가운 간식을 고를지 묻는 것이며, 더 넓은 선호나 목표를 묻는 것이 아니다.'),
    ('prompt-preference-2219', '답변에는 공부 후 먹고 싶은 간식과 그 간식을 좋아하는 이유가 모두 필요하다.'),
    ('prompt-preference-2220', '가정 상황은 학습자가 어떤 작은 단것을 고를지 묻는다. 원하는 에너지 효과는 상황에 이미 제시되어 있으므로 다시 말할 필요가 없다.'),
    ('prompt-preference-2221', '이 가정 상황은 학습자가 편의점에서 무엇을 고를지 묻는다. 바쁜 날이라는 상황은 이미 주어졌으므로 구체적인 선택 하나만 제시하면 된다.'),
    ('prompt-preference-2222', '학습자는 함께 나누거나 편하게 쉬면서 먹기 쉬운 간단한 간식을 말한다. 선호를 주장하거나 명시적인 이유 절을 제시할 필요는 없다.'),
    ('prompt-preference-2223', '가정 상황은 영화를 보거나 프로그램을 시청하면서 어떤 간식을 고를지 묻는다. 상황에 맞는 선택 하나로 과제를 완성할 수 있다.'),
    ('prompt-preference-2224', '학습자는 이동하면서 먹기 좋아하는 달콤한 빵을 말하고, 그 선호의 이유를 설명한다.'),
    ('prompt-preference-2225', '‘음료 간식’이라는 짧은 표현이지만, 과제는 낮 동안 상쾌하게 느껴지는 항목을 묻고 선호나 설명을 요구하지 않는다.'),
    ('prompt-preference-2226', '학습자는 기분 좋은 휴식과 관련된 달콤한 과일 맛을 제시한다. 그 맛을 말하면 간단한 묘사적 연상이 완성된다.'),
    ('prompt-preference-2227', '이 가정 상황은 학습자가 밤늦게 무엇을 먹을지 묻는다. 작은 것을 원한다는 내용은 이미 주어졌으므로 다시 말할 필요가 없다.'),
    ('prompt-preference-2228', '학습자는 편안한 휴식에 어울리는 짭짤한 간식을 말하고, 왜 어울리는지 설명해야 한다. 구조는 선호를 말하기보다 묘사하는 방식이다.'),
    ('prompt-preference-2229', '답변에는 주어진 긴 하루를 보낸 후 위로가 될 것 같은 부드러운 간식을 말해야 한다. 선호를 주장하거나 별도로 설명할 필요는 없다.'),
    ('prompt-preference-2230', '가정 상황은 하루를 긍정적으로 마무리하는 데 도움이 될 작은 간식을 묻는다. 초급 수준에서는 구체적인 내용 하나면 충분하다.'),
    ('prompt-preference-2231', '학습자는 공부할 때 좋아하는 필기 도구를 고르고, 그 도구를 선호하는 이유를 설명해야 한다.'),
    ('prompt-preference-2232', '지우개의 용도는 이미 주어져 있으므로, 학습자는 공부 중 언제 사용하는지와 어떤 이점을 주는지를 말해야 한다.'),
    ('prompt-preference-2233', '이 좁은 초급 질문은 공부할 때 형광펜을 사용하는 방법만 묻는다.'),
    ('prompt-preference-2234', '학습이나 일을 위해 메모지에 습관적으로 적는 내용을 설명하는 질문이므로, 구체적인 행동 하나면 충분하다.'),
    ('prompt-preference-2235', '직접적인 의무는 학습이나 일에 수첩을 사용하는 방법을 설명하는 것이며, 집중된 일과를 설명하면 된다.'),
    ('prompt-preference-2236', '책갈피를 사용하는 것이 이미 제시되어 있으므로, 학습자가 책갈피를 사용하는 독서나 학습 상황만 제시하면 된다.'),
    ('prompt-preference-2237', '학습이나 일을 시작하기 전에 책상을 정리하는 행동을 설명하는 답변이다. 선택적인 단계를 덧붙일 수 있지만 필수는 아니다.'),
    ('prompt-preference-2238', '질문에서 자를 사용하는 활동을 제시하고, 학습자가 이를 사용하는 학교나 직장의 상황을 묻고 있다.'),
    ('prompt-preference-2239', '학교나 직장의 서류를 정리하는 방법을 말해야 하며, 질문에서 별도로 이유를 요구하지는 않는다.'),
    ('prompt-preference-2240', '학교나 직장용 주머니에 무엇을 늘 넣어 두는지 묻는 질문이므로, 구체적으로 가지고 다니는 행동 하나로 답할 수 있다.'),
    ('prompt-preference-2241', '편안한 타자 입력을 돕는 자판 배열을 설명하는 답변이다. 편안함이라는 조건 때문에 별도의 선호나 이유를 설명할 필요는 없다.'),
    ('prompt-preference-2242', '학습이나 일을 할 때 편안하게 느껴지는 마우스를 묻는 질문이므로, 초급 답변에는 구체적인 설명 하나면 충분하다.'),
    ('prompt-preference-2243', '학습이나 일을 할 때 타이머를 사용하는 방법을 말해야 한다.'),
    ('prompt-preference-2244', '학교나 직장의 서류를 정리해 두는 방법을 설명하는 질문이며, 명확한 정리 행동 하나면 충분하다.'),
    ('prompt-preference-2245', '공책 가까이에 학습 도구를 두는 어떤 행동을 습관적으로 하는지 말하고, 그 도구의 실용적인 이점을 설명해야 한다.'),
    ('prompt-preference-2246', '평소에 입는 티셔츠를 설명하고, 평범한 날에 그 티셔츠를 선택하는 이유를 설명해야 한다.'),
    ('prompt-preference-2247', '후드티 자체는 이미 제시되어 있으므로, 이 집중된 시간 관련 질문에서는 후드티를 입는 상황과 그 상황에 후드티가 적합한 이유만 말하면 된다.'),
    ('prompt-preference-2248', '긴 하루 동안 편안한 양말을 설명하고, 무엇 때문에 적합한지 설명해야 한다. 선호를 밝히는 답변은 요구되지 않는다.'),
    ('prompt-preference-2249', '매일 걸을 때 습관적으로 신는 운동화를 고르고, 그 운동화를 신는 이유를 말해야 한다.'),
    ('prompt-preference-2250', '맑은 날 모자를 사용하는 것은 제시되어 있으므로, 모자를 쓰는 상황만 구체적으로 말하면 된다.'),
    ('prompt-preference-2251', '겨울에 목도리를 언제 하는지 말하고, 목도리를 하면 어떤 도움이 되는지 설명해야 한다.'),
    ('prompt-preference-2252', '자주 착용하는 액세서리를 습관적인 행동으로 설명하고, 그것을 착용하는 이유를 말해야 한다.'),
    ('prompt-preference-2253', '집에서 슬리퍼를 신는 상황과 그때 슬리퍼를 신는 이유를 직접적으로 묻는 질문이다.'),
    ('prompt-preference-2254', '가정적인 표현으로 우비를 입을 상황과 우비가 제공하는 이점을 묻는 질문이며, 미래의 목표를 묻는 것이 아니다.'),
    ('prompt-preference-2255', '잠자리에 들 때 무엇을 입는지 설명하고, 그 옷이 편안한 수면을 돕는 이유를 설명해야 한다.'),
    ('prompt-preference-2256', '언제 머리를 묶는지 말하고, 머리를 편안하게 유지해 주는 도움이나 조건을 설명해야 한다.'),
    ('prompt-preference-2257', '비 오는 날 평소에 사용하는 우산을 설명하고, 그 우산을 사용하는 이유를 제시해야 하므로 습관적인 행동을 묻는 질문이다.'),
    ('prompt-preference-2258', '밖에 나갈 때 평소에 입는 재킷을 설명하고, 그 재킷을 입는 이유를 말해야 한다.'),
    ('prompt-preference-2259', '좋아하는 반지나 팔찌를 하나 고르고, 그 액세서리를 언제 착용하는지 말해야 한다.'),
    ('prompt-preference-2260', '제시된 휴식 상황에서 무엇을 입는지 설명하고, 그 옷이 편안함을 주는 이유를 설명해야 한다.'),
    ('prompt-preference-2261', '편안함을 주는 담요를 설명하고, 학습자가 그 담요를 사용하는 상황을 말해야 한다.'),
    ('prompt-preference-2262', '휴식을 향상하는 베개를 설명하고, 그 베개가 도움이 되는 이유를 말해야 한다. 좋아하는 물건이나 선택을 묻는 표현은 아니다.'),
    ('prompt-preference-2263', '집에서 사용하기 좋아하는 컵을 고르고, 그 컵을 사용하는 상황을 말해야 한다.'),
    ('prompt-preference-2264', '선호하는 그릇을 하나 고른 뒤, 그 안에 무엇을 담는지 별도로 설명해야 한다.'),
    ('prompt-preference-2265', '방을 편안하게 만들어 주는 램프나 조명을 설명하고, 그것이 그런 효과를 내는 이유를 설명해야 한다.'),
    ('prompt-preference-2266', '답변은 물병을 집에서 어디에 보관하는지 밝히고, 그곳에 보관하는 이점을 설명해야 한다.'),
    ('prompt-preference-2267', '질문은 책상 매트가 집에서 공부하거나 일할 때 어떤 이점을 주는지 구체적으로 묻고 있으므로, 분명하고 유용한 효과 하나면 충분하다.'),
    ('prompt-preference-2268', '학습자는 오래 앉아 있을 때 의자를 더 편안하게 느끼게 하는 요인을 밝혀야 한다.'),
    ('prompt-preference-2269', '답변은 벽 달력을 어떻게 사용하는지 설명하고, 그것이 유용한 이유가 되는 이점을 밝혀야 한다.'),
    ('prompt-preference-2270', '학습자는 작은 선풍기를 사용하는 상황을 제시하고, 그 상황에서 선풍기가 어떻게 도움이 되는지 설명해야 한다.'),
    ('prompt-preference-2271', '외출 준비를 하면서 거울을 사용한다는 내용은 이미 제시되어 있으므로, 구체적인 사용 시점이나 상황만 직접적으로 요구된다.'),
    ('prompt-preference-2272', '학습자는 집의 수납 바구니에 무엇을 보관하는지 설명하고, 그 물건들을 그곳에 보관하는 이유를 설명해야 한다.'),
    ('prompt-preference-2273', '답변은 간단한 식사 때 습관적으로 사용하는 접시를 밝히고, 그것을 사용하는 이유를 제시해야 한다.'),
    ('prompt-preference-2274', '학습자는 휴식과 관련된 작은 방 안 물건을 설명하고, 그 물건이 그런 효과를 내는 이유를 설명한다. 선호를 주장할 필요는 없다.'),
    ('prompt-preference-2275', '답변은 학습자가 침대 가까이에 무엇을 두는지 밝히고, 그것을 그곳에 두는 실용적인 이점을 설명해야 한다.'),
    ('prompt-preference-2276', '질문은 하루 동안 학습자의 손을 잘 관리된 느낌이 들게 하는 제품, 습관 또는 그 밖의 원인을 묻는다.'),
    ('prompt-preference-2277', '질문은 씻은 뒤 학습자가 선호하는 깨끗한 느낌의 종류를 묻고 있으므로, 그 느낌을 말하는 것만으로 이 간단한 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-preference-2278', '학습자는 머리를 감을 때 상쾌하거나 편안하게 느끼게 하는 구체적인 요인을 밝혀야 한다. 그러한 요인 하나면 이 초점이 분명한 질문에 충분히 답할 수 있다.'),
    ('prompt-preference-2279', '문장은 입술이 건조할 때 어떤 물건을 사용하는지와 그 이유를 직접 묻고 있으므로, 선택한 물건과 그 이유가 모두 필요하다.'),
    ('prompt-preference-2280', '질문은 샤워 후 학습자가 상쾌하게 느끼는 데 도움이 되는 요인을 폭넓게 묻는다. 유효한 답은 행동, 제품, 물건 또는 환경 조건일 수 있으므로, DETAIL은 행동이 아닌 답을 배제하지 않으면서 열린 도움 요인을 포착한다.'),
    ('prompt-preference-2281', '질문은 어떤 질감이 편안하게 느껴지는지를 묻는 것이지, 학습자가 어떤 질감을 좋아하거나 선호하는지를 묻는 것이 아니다. 학습자가 묘사하는 질감을 제시하므로, GENERAL_DESCRIPTION과 DETAIL은 선호를 답변 의무로 임의로 추가하지 않는다.'),
    ('prompt-preference-2282', '학습자는 작은 수건을 기분 좋게 사용하게 하는 특성을 말해야 한다. 부드러움이나 향기 같은 특성 하나면 충분하며, 추가적인 뒷받침은 요구되지 않는다.'),
    ('prompt-preference-2283', '질문은 목욕 시간을 더 편안하게 만드는 요인을 폭넓게 묻는다. 따뜻한 물, 음악, 조명, 제품 또는 행동이 모두 답이 될 수 있으므로 ACTION을 필수로 두면 유효한 비행동 요인을 잘못 제외한다.'),
    ('prompt-preference-2284', '학습자는 외출 전에 평소에 하는 보호 행동을 밝혀야 한다. 자외선 차단제를 바르는 것과 같은 구체적인 방법이 질문에 직접 답한다.'),
    ('prompt-preference-2285', '질문은 긴 하루 뒤 학습자의 얼굴이 상쾌하게 느껴지도록 돕는 것이 무엇인지 묻는다. 도움 요인은 행동, 제품, 물건, 온도 또는 다른 조건일 수 있으므로 DETAIL을 포괄적인 필수 슬롯으로 두고 ACTION은 선택 사항으로 둔다.'),
    ('prompt-preference-2286', '질문은 양치질을 상쾌하게 느끼게 하는 특정 특성이나 도움을 묻고 있으며, 아침이나 밤은 단지 상황을 제시할 뿐이다.'),
    ('prompt-preference-2287', '질문은 학습자의 방에서 깨끗하거나 편안한 향이 나도록 돕는 것이 무엇인지 폭넓게 묻는다. 향의 원천, 제품, 물건, 환경 조건 또는 행동이 답이 될 수 있으므로 행동을 필수로 두지 않고 DETAIL이 열린 요인을 포괄해야 한다.'),
    ('prompt-preference-2288', '질문은 감은 머리가 단정하거나 부드럽게 느껴지도록 돕는 것을 묻는다. 관리 행동도 유효하지만 제품, 도구, 물의 조건 또는 모발 특성도 답이 될 수 있으므로 DETAIL을 포괄적인 필수 슬롯으로 두고 ACTION은 선택 사항으로 둔다.'),
    ('prompt-preference-2289', '학습자는 깨끗한 옷을 기분 좋게 입게 하는 특성을 밝혀야 하며, 이 간단한 질문에는 구체적인 특성 하나면 충분하다.'),
    ('prompt-preference-2290', '질문은 선호하는 취침 전 관리 제품과 그것이 어떻게 편안함을 주는지에 대한 설명을 명시적으로 요구하며, 그 결과로 이를 포착한다.'),
    ('prompt-preference-2291', '학습자는 선호하는 휴대전화 배경 화면을 밝히고 그 선호 이유를 설명해야 하므로, 선택과 이유가 모두 필수이다.'),
    ('prompt-preference-2292', '문장은 잠에서 깨는 데 도움이 되는 알람 소리를 밝히고 그것이 효과적인 이유를 설명하도록 요구한다. 이 두 가지 요구 사항만으로도 충분한 깊이가 확보된다.'),
    ('prompt-preference-2293', '질문은 학습자가 휴대전화 일정을 확인하는 방법을 묻고 있으며, 분명한 행동 하나가 이 초급 일상 질문에 직접 답한다.'),
    ('prompt-preference-2294', '휴대전화에 메모를 쓴다는 내용은 이미 제시되어 있으므로, 직접적으로 필요한 누락 정보는 학습자가 메모를 쓰는 구체적인 시간이나 조건이다.'),
    ('prompt-preference-2295', '학습자는 메시지에서 스티커를 사용하는 시점과 그 이유를 밝혀야 한다. 두 절의 내용이 명시적으로 요구되므로 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-preference-2296', '질문은 학습자가 하루 동안 휴대전화 음악을 평소에 어떻게 선택하는지 묻고 있다. 단순히 선택한다고 말하는 것에서 더 나아가, 독립적인 선택 세부 사항 하나가 필요하다.'),
    ('prompt-preference-2297', '질문은 사용하는 사진 필터와 그것을 사용하는 상황을 직접 요구하므로, 선택과 시점을 함께 제시하면 충분히 답할 수 있다.'),
    ('prompt-preference-2298', '학습자는 어딘가로 이동할 때 휴대전화로 경로를 선택하는 방법을 말해야 하므로, 구체적인 선택 행동만으로 충분하다.'),
    ('prompt-preference-2299', '질문에서 학습자가 언제 휴대전화로 날씨를 확인하는지와 그 이유를 명시적으로 묻고 있으며, 이 두 의미 단위만으로 완전한 답변이 된다.'),
    ('prompt-preference-23', '학습자는 좋아하는 음악 유형을 설명하고 서로 다른 이유 두 가지를 제시해야 한다. REASON 의무가 요청된 두 이유를 모두 포함하므로 추가적인 세부 내용은 필요하지 않다.'),
    ('prompt-preference-2300', '과제는 학습자가 입력하기 가장 쉽다고 느끼는 자판 설정을 식별하는 것이며, 그 유용한 효과는 질문에 이미 제시되어 있다.'),
    ('prompt-preference-2301', '학습자는 자주 사용하는 휴대전화 단축 기능을 말하고 그 기능을 사용하는 이유를 설명해야 하므로, 명시된 두 조건을 모두 충족해야 한다.'),
    ('prompt-preference-2302', '질문은 어떤 재생 목록을 반복해서 여는지와 언제 여는지를 묻고 있으므로, 재생 목록의 선택과 그 시점이 필수 내용이다.'),
    ('prompt-preference-2303', '학습자는 설정하는 알림의 종류와 설정하는 이유를 구체적으로 말해야 하며, 초급 수준에서는 이 두 부분으로 충분하다.'),
    ('prompt-preference-2304', '질문에서 자주 확인하는 위젯과 확인하는 이유를 직접 요구하므로, 추가적인 뒷받침 내용은 필요하지 않다.'),
    ('prompt-preference-2305', '답변은 아침에 사용하는 앱 기능을 식별하고 그 기능이 어떻게 도움이 되는지 말해야 하므로, 선택한 기능과 그 결과가 필수 내용이다.'),
    ('prompt-preference-2306', '학습자는 근처 공원에서 앉는 장소를 말하고 그 장소를 좋아하는 이유를 설명해야 하므로, 두 의무가 모두 명시되어 있다.'),
    ('prompt-preference-2307', '질문은 학습자가 근처에서 보통 무엇을 사는지와 그 구매가 어떻게 유용한지를 묻고 있으므로, 물건과 그 실용적인 결과가 필수 내용이다.'),
    ('prompt-preference-2308', '과제는 학습자가 걷기를 좋아하는 근처의 거리를 말하고 그 이유를 설명하도록 직접 요구하므로, 장소와 이유가 필수 요소가 된다.'),
    ('prompt-preference-2309', '가정 상황에서 학습자가 언제 꽃 가게를 방문할지와 무엇을 고를지를 모두 묻고 있으므로, 시점과 선택이 더 넓은 계획을 세우지 않고도 필수 내용이 된다.'),
    ('prompt-preference-2310', '학습자는 근처 버스 정류장이 일상에 어떻게 활용되는지 설명해야 한다. 단순한 이동 행동에 그치지 않으려면 시점, 목적 또는 결과에 관한 세부 내용 하나가 필요하다.'),
    ('prompt-preference-2311', '질문은 대중교통에서 학습자가 앉는 위치와 그 위치를 좋아하는 이유를 묻고 있으며, 이 두 내용이 함께 완전한 개인적 설명을 이룬다.'),
    ('prompt-preference-2312', '가정 상황에서는 학습자가 살 과일과 그 과일을 먹을 시점을 요구하므로, 요청된 두 조건이 모두 필요하며 더 넓은 목표를 뜻하지는 않는다.'),
    ('prompt-preference-2313', '질문은 학습자가 식료품점에 갈 때 습관적으로 이용하는 경로와 그 경로를 좋아하는 이유를 요구한다.'),
    ('prompt-preference-2314', '학습자는 시장에서 처음 방문하는 구역을 식별하고 그곳이 먼저인 이유를 설명해야 하므로, 추가적인 세부 내용 없이 순서에 관한 질문을 충족한다.'),
    ('prompt-preference-2315', '과제는 급하게 필요한 일을 처리하는 데 유용한 근처 장소를 간단히 식별하는 것이므로, 적절한 장소의 이름을 말하면 초급 답변으로 충분하다.'),
    ('prompt-preference-2316', '질문에서 학습자가 야외에서 쉬는 동안 앉기를 좋아하는 장소와 그 이유를 명시적으로 묻고 있으므로, 장소와 이유가 모두 필요하다.'),
    ('prompt-preference-2317', '학습자는 근처에서 노을을 보는 장소를 식별하고 그 장소를 좋아하는 이유를 설명해야 한다.'),
    ('prompt-preference-2318', '직접적인 의무 내용은 창문 근처에서 학습자가 앉는 장소와 그 장소를 좋아하는 이유이다.'),
    ('prompt-preference-2319', '질문은 학습자가 집에 가는 길에 들르기를 좋아하는 장소와 그 이유를 요구하므로, 위치와 이유가 필수이다.'),
    ('prompt-preference-2320', '질문은 학습자가 신선한 공기를 원할 때 이용하는 근처의 목적지를 묻고 있으므로, 구체적인 장소를 말하면 직접적이고 충분한 답변이 된다.'),
    ('prompt-preference-2321', '학습자는 즐겁게 할 수 있는 간단한 퍼즐이나 게임을 말하고 그것이 즐거운 이유를 설명해야 하므로, 두 조건을 모두 다룬다.'),
    ('prompt-preference-2322', '질문은 부담 없이 즐기는 카드 게임과 그 게임을 하는 시간이나 상황을 요구하므로, 두 내용이 모두 필요하다.'),
    ('prompt-preference-2323', '학습자는 재미로 보는 유튜브 동영상의 유형을 식별하고 그것을 즐기는 이유를 제시해야 한다.'),
    ('prompt-preference-2324', '질문은 즐겨 듣는 팟캐스트의 주제와 그것을 즐기는 이유를 직접 묻고 있으므로, 선택과 이유만으로 충분하다.'),
    ('prompt-preference-2325', '학습자는 긴장을 풀어 주는 창의적인 활동을 말하고 그 활동에 무엇을 사용하는지 밝혀야 하므로, 명시된 두 부분만으로 적절한 깊이가 확보된다.'),
    ('prompt-preference-2326', '가정 상황에서는 학습자가 시도할 공예 활동과 그 활동에 사용할 재료를 요구하며, 더 넓은 목표나 준비 계획은 필요하지 않다.'),
    ('prompt-preference-2327', '질문은 학습자가 사진을 저장하거나 공유하기 전에 선호하는 편집 방법을 묻고 있으므로, 구체적인 편집 행동으로 답할 수 있다.'),
    ('prompt-preference-2328', '학습자는 10분의 짧은 휴식 시간에 하는 활동을 말하고 그 활동을 하는 이유를 설명해야 하므로, 요청된 두 요소가 모두 필요하다.'),
    ('prompt-preference-2329', '질문은 비 오는 날 어떤 실내 취미가 적합하다고 느끼는지와 그 이유를 묻고 있으므로, 해당 취미와 이유를 제시하면 설명이 완성된다.'),
    ('prompt-preference-2330', '학습자는 여가 시간에 긴장을 푸는 데 도움이 되는 소리나 음악의 종류만 밝히면 되므로, 그에 초점을 맞춘 선택만으로 충분하다.'),
    ('prompt-preference-2331', '질문은 더운 날 실내에서 즐길 수 있는 활동과 학습자가 그 활동을 즐기는 이유를 직접 묻는다.'),
    ('prompt-preference-2332', '학습자는 줄을 기다릴 때 보통 하는 행동을 설명하고 그것이 어떻게 도움이 되는지 밝혀야 하므로, 요청된 실용적 결과까지 제시해야 한다.'),
    ('prompt-preference-2333', '과제는 학습자가 짧은 교육 영상을 밝히고 그 영상을 보는 이유를 설명하도록 하므로, 이 두 절만으로 충분하다.'),
    ('prompt-preference-2334', '질문은 친구와 집에서 하는 활동을 묻는 간단한 개인 선호 질문이므로, 구체적인 활동 하나만 제시해도 충분하다.'),
    ('prompt-preference-2335', '원문은 학습자가 어떤 취미를 시작하고 싶어 하는지 묻고 있으므로, 선호하는 취미를 직접 요구한다. 현재 설명은 가정법 표현으로 다시 쓰고 있지만, 원문은 가정적인 선택을 묻지 않는다.'),
    ('prompt-preference-24', '학습자가 가장 좋아하는 것을 묻는 질문은 가장 선호하는 측면을 선택하도록 요구하므로, 그 문자 그대로의 의무는 CHOICE이다. DETAIL은 부연 설명으로 유용하지만, 요청된 선택을 대신해서는 안 된다.'),
    ('prompt-preference-25', '질문은 가장 좋아하는 음악의 종류를 소개하고 무엇이 그것을 개인적으로 특별하게 만드는지 설명하도록 요구한다.'),
    ('prompt-preference-2501', '학습자는 하루 동안 가지고 다니는 병을 밝히고 그것이 어떻게 도움이 되는지 설명해야 하므로, 물건과 그 결과를 모두 제시해야 한다.'),
    ('prompt-preference-2502', '물병을 다시 채우는 행동은 이미 제시되어 있으므로, 직접적인 답변으로 필요한 것은 물을 다시 채우는 구체적인 시간이나 조건뿐이다.'),
    ('prompt-preference-2503', '질문은 선호하는 탄산수의 맛과 그것을 마시는 때를 묻으므로, 선택과 시기를 모두 반드시 제시해야 한다.'),
    ('prompt-preference-2504', '학습자는 산책할 때 선호하는 음료를 말하고 그것이 적합한 이유를 설명해야 하므로, 명시된 두 절을 모두 충족해야 한다.'),
    ('prompt-preference-2505', '질문은 점심과 함께 마시기를 선호하는 주스와 그 선호 이유를 직접 요구한다.'),
    ('prompt-preference-2506', '학습자는 물에 넣을 과일을 선택하고 그 첨가물을 좋아하는 이유를 설명해야 하므로, 선택 사항 외에 추가적인 깊이는 필요하지 않다.'),
    ('prompt-preference-2507', '질문은 가지고 다니기 좋아하는 병과 그 이유를 묻으므로, 선택과 이유가 완전한 필수 답변을 이룬다.'),
    ('prompt-preference-2508', '학습자는 더운 날 선호하는 차가운 음료를 밝히고 그 선호 이유를 설명해야 한다.'),
    ('prompt-preference-2509', '질문은 여름에 차갑게 보관해 두기를 좋아하는 음료와 그 이유를 묻으므로, 요청된 두 부분을 모두 제시해야 한다.'),
    ('prompt-preference-2510', '학습자는 공부할 때 보통 조금씩 마시는 음료를 말하고 그 상황에서 그것을 선택하는 이유를 설명해야 한다.'),
    ('prompt-preference-2511', '행동 자체는 제시되어 있으므로, 학습자는 재사용 컵을 사용하는 때와 그 이유를 명시적으로 답해야 한다.'),
    ('prompt-preference-2512', '질문은 운동 후 마시는 음료와 그것이 어떻게 도움이 되는지에 대한 설명을 요구하며, 이는 음료의 선택과 그 결과로 나타난다.'),
    ('prompt-preference-2513', '학습자는 더운 날 마실 차가운 음료를 선택하고 그것을 고른 이유를 설명해야 하므로, 이 두 절만으로 충분한 깊이를 제공한다.'),
    ('prompt-preference-2514', '질문은 학습자가 들기 편하다고 느끼는 병과 그것을 사용하는 때를 묻으므로, 해당 병과 시기를 반드시 제시해야 한다.'),
    ('prompt-preference-2515', '학습자는 따뜻한 날 집에 도착한 뒤 보통 선택하는 음료를 밝히고 그 선택을 설명해야 한다.'),
    ('prompt-preference-2516', '바쁜 날을 위해 배낭을 준비하는 것은 폭넓은 일상 행동이므로, 단순히 준비한다고만 답하지 말고 구체적인 포장이나 정리 방법 하나를 추가해야 한다.'),
    ('prompt-preference-2517', '짧은 여행에 토트백을 사용하는 것은 이미 제시되어 있으므로, 질문은 학습자가 그렇게 하는 시간이나 상황을 직접 묻는다.'),
    ('prompt-preference-2518', '질문은 작은 가방 속 주머니의 내용물을 묻는 단순한 요청이므로, 구체적인 물건 정보만으로 충분하다.'),
    ('prompt-preference-2519', '학습자는 일상적으로 사용하기 위해 지갑에 무엇을 넣어 두는지만 설명하면 되며, 목적은 질문에서 이미 정해져 있다.'),
    ('prompt-preference-2520', '질문은 매일 사용하는 열쇠고리와 그 이유를 직접 묻으므로, 선택한 물건과 이유를 모두 제시해야 한다.'),
    ('prompt-preference-2521', '질문은 학습자의 가방 안에서 병이 어디에 있는지를 묻고 있으며, 정확한 위치 하나만으로도 이 간단한 과제에 충분히 답할 수 있다.'),
    ('prompt-preference-2522', '학습자는 가방을 쉽게 열고 닫는 데 도움이 되는 정리 방법을 설명해야 하므로, 독립적인 배치 방법 하나를 제시해 그 방법을 구체화해야 한다.'),
    ('prompt-preference-2523', '학습자는 카드지갑을 사용하는 때와 그 이유를 명시적으로 답해야 하므로, 시기와 이유가 완전한 답변을 이룬다.'),
    ('prompt-preference-2524', '과제는 오랜 시간 동안 편안함을 돕는 구체적인 가방 기능을 묻고 있으므로, 해당 기능을 이름으로 말하면 초급 수준에서는 충분하다.'),
    ('prompt-preference-2525', '질문은 어떤 일상용 가방을 가장 많이 사용하는지와 그 이유를 묻으므로, 선택한 가방과 자주 사용하는 이유를 모두 말해야 한다.'),
    ('prompt-preference-2526', '행동이 이미 제시되어 있으므로, 학습자가 직접 답해야 할 유일한 내용은 접이식 장바구니를 사용하는 상황이다.'),
    ('prompt-preference-2527', '질문은 휴대용 충전기를 가지고 다니는 상황과 그 이유를 명시적으로 요구한다.'),
    ('prompt-preference-2528', '학습자는 파우치에 보관하는 펜이나 케이블 물품을 설명해야 하며, 구체적인 내용물로 답하면 충분하다.'),
    ('prompt-preference-2529', '학습자는 비 오는 날 사용하는 가방을 밝히고, 그 가방이 그러한 날씨에 적합한 이유를 설명해야 한다.'),
    ('prompt-preference-2530', '초점이 맞춰진 질문은 잠깐 외출할 때 사용하는 작은 가방이 무엇인지 묻고 있으므로, 그 가방의 이름을 말하면 충분히 답할 수 있다.'),
    ('prompt-preference-2531', '질문은 집의 수납 상자에 들어 있는 물건을 묻고 있으므로, 구체적인 물건을 말하면 초급 과제를 충족한다.'),
    ('prompt-preference-2532', '학습자는 집에서 매일 입는 옷을 걸어 두는 방법을 말해야 하며, 명확한 행동 하나면 충분하다.'),
    ('prompt-preference-2533', '서랍을 사용하기 쉽게 정리하는 것은 범위가 넓은 방법 질문이므로, 그 일상을 구체적으로 설명하려면 독립적인 배치 세부 사항 하나가 필요하다.'),
    ('prompt-preference-2534', '질문은 벽걸이를 어디에 사용하는지와 그곳에 어떤 물건을 거는지를 명시적으로 묻으므로, 이 두 필수 내용이면 충분하다.'),
    ('prompt-preference-2535', '학습자는 집의 상자에 보관하는 작은 물건의 이름을 말해야 하므로, 구체적인 내용물이 유일한 직접 요구 사항이다.'),
    ('prompt-preference-2536', '과제는 학습하기 전에 책상을 닦을 때 사용하는 청소용품이 무엇인지 묻고 있으므로, 그 물품을 밝히면 충분하다.'),
    ('prompt-preference-2537', '어떤 청소가 가장 쉬운지 말하는 것은 평가적 판단이며, 질문은 그 이유도 별도로 요구한다. 이 판단을 선호로 처리하는 것은 타당하지만 더 정확한 분류는 아니다.'),
    ('prompt-preference-2538', '질문은 주방 청소에 사용하는 스펀지나 도구가 무엇인지 직접 묻고 있으므로, 구체적인 도구를 말하면 충분하다.'),
    ('prompt-preference-2539', '학습자는 방을 더 사용하기 편하게 해 주는 수납 공간을 밝혀야 하며, 도움이 되는 효과는 이미 질문의 조건에 포함되어 있다.'),
    ('prompt-preference-2540', '질문은 집에서 무엇에 라벨을 붙이는지와 라벨이 어떻게 유용한지를 묻으므로, 라벨을 붙인 물건과 실용적인 결과를 모두 말해야 한다.'),
    ('prompt-preference-2541', '학습자는 사용하기 편한 욕실 서랍 정리 방법을 설명해야 하므로, 일반적인 정리 행동을 넘어서는 구체적인 배치 세부 사항 하나가 필요하다.'),
    ('prompt-preference-2542', '초점이 맞춰진 질문은 집에서 신발 상자를 어떤 방식으로 재사용하는지 묻고 있으므로, 구체적인 재사용 행동 하나로 충분히 답할 수 있다.'),
    ('prompt-preference-2543', '학습자는 집에서 케이블을 보관하는 장소를 밝히고 그 장소를 사용하는 이유를 설명해야 하므로, 두 가지 명시적 요구를 모두 충족해야 한다.'),
    ('prompt-preference-2544', '질문은 수건 바구니의 내용물과 바구니의 위치를 모두 요구하므로, 추가적인 선택 정보는 필요하지 않다.'),
    ('prompt-preference-2545', '질문은 문 근처에서 가방이나 열쇠를 보관하는 장소를 묻고 있으므로, 정확한 위치를 말하면 간단한 답변으로 충분하다.'),
    ('prompt-preference-2546', '학습자는 휴대전화를 사용하기 편하게 해 주는 집에서의 충전 방법을 설명해야 하며, 구체적인 설치 행동 하나가 질문에 직접 답한다.'),
    ('prompt-preference-2547', '과제는 일상적인 기기 사용을 개선하는 케이블 정리 방법을 묻고 있으므로, 그 정리 상태를 설명하면 좁은 범위의 초급 질문에는 충분하다.'),
    ('prompt-preference-2548', '학습자는 배경 음악을 언제 재생하는지와 어떤 기기, 앱 또는 출처를 사용하는지를 말해야 하므로, 두 절을 모두 충족해야 한다.'),
    ('prompt-preference-2549', '따뜻한 날 책상 선풍기를 사용하는 사실은 이미 제시되어 있으므로, 직접 답해야 할 내용은 사용하는 구체적인 시간이나 조건이다.'),
    ('prompt-preference-2550', '질문은 알람이나 알림이 하루 전체의 일과를 어떻게 돕는지 넓게 묻고 있으므로, 단순히 사용한다고 말하는 것 이상으로 시간, 설정 또는 결과에 관한 세부 사항 하나가 필요하다.'),
    ('prompt-preference-2551', '학습자는 책상 위 휴대전화 거치대를 실용적으로 사용하는 방법을 말해야 하며, 구체적인 사용 행동 하나면 충분하다.'),
    ('prompt-preference-2552', '질문은 밤에 책을 읽을 때 평소 사용하는 조명의 종류와 그 조명을 사용하는 이유를 요구하므로, 두 항목 모두 필수이다.'),
    ('prompt-preference-2553', '과제는 타이머를 사용하게 되는 상황이나 짧은 작업의 종류를 묻고 있으므로, 그 구체적인 조건이면 초급 수준에서 충분하다.'),
    ('prompt-preference-2554', '학습자는 집에서 가습기를 언제 사용하는지와 가습기가 어떻게 도움이 되는지를 말해야 하므로, 사용 시점과 결과가 명시적으로 필요하다.'),
    ('prompt-preference-2555', '질문은 집에서 멀티탭을 어디에 사용하는지와 그곳에 두는 이유를 묻고 있으므로, 위치와 이유를 모두 말해야 한다.'),
    ('prompt-preference-2556', '학습자는 집에서 독서할 때 사용하는 조명을 식별하고 언제 사용하는지 말해야 하며, 이 두 가지 직접적인 의무만으로도 충분한 깊이가 확보된다.'),
    ('prompt-preference-2557', '침대 옆에 충전기를 둔다는 내용은 이미 제시되어 있으므로, 초점을 맞춘 질문에서는 그렇게 하는 이유만 요구된다.'),
    ('prompt-preference-2558', '학습자는 휴대용 선풍기를 언제 사용하는지와 그 상황에서 왜 유용한지를 모두 설명해야 한다.'),
    ('prompt-preference-2559', '질문은 학습자가 집에서 태블릿 거치대를 사용하는 방법을 묻고 있으며, 구체적인 사용 행동 하나로 간단한 일상 과제가 완성된다.'),
    ('prompt-preference-2560', '램프의 용도는 질문에 제시되어 있고 학습자는 구체적인 시간 또는 시점 조건만 작성하므로, 이는 일상 행동 답변이 아니라 초점을 맞춘 I 수준의 설명이다.'),
    ('prompt-preference-2561', '표현은 학습자가 남은 음식을 평소에 보관하는 방법을 묻고 있으므로, 보관 행동만이 이 간단한 개인적 질문에서 요구되는 유일한 내용이다.'),
    ('prompt-preference-2562', '학습자는 음식 용기를 식별하고 그 안에 어떤 음식이 들어가는지 말해야 하며, 요청된 이 두 가지 내용만으로도 I 수준의 답변에 충분한 내용이 갖춰진다.'),
    ('prompt-preference-2563', '학습자는 집 밖에서 사용하는 도시락 용기를 선택하고 그것이 편안한 이유를 설명해야 하므로, 선택과 이유가 모두 필수이다.'),
    ('prompt-preference-2564', '답변하려면 수프에 사용하는 숟가락이 무엇인지와 그것을 사용하는 이유를 말해야 하며, 이 두 가지 명시적인 의무만으로 난이도 I에 충분하다.'),
    ('prompt-preference-2565', '답변에는 집에서 사용할 젓가락을 선택하고 그 선택의 이유를 설명해야 하며, 명시된 두 절 외에 추가 항목은 필요하지 않다.'),
    ('prompt-preference-2566', '열린 표현상 습관, 도구, 배치, 환경이나 조건이 지저분함을 줄이는 요인이 될 수 있으므로 CHOICE나 ACTION 대신 포괄적인 DETAIL이 필수이다. 명시적인 이유 절에는 REASON이 필요하며, 이 두 부분이면 난이도 I에서 충분하다.'),
    ('prompt-preference-2567', '학습자는 요리할 때 사용하는 도마를 말하고 그 도마를 사용하는 이유를 설명해야 하며, 이 두 부분으로 완전한 I 수준의 답변이 구성된다.'),
    ('prompt-preference-2568', '주방 수건을 사용한다는 내용은 이미 제시되어 있으므로, 학습자는 시점 조건과 그에 따른 이점만 제시하면 된다. 이는 일상 행동의 순서가 아니라 사실에 대한 설명이다.'),
    ('prompt-preference-2569', '학습자는 주전자를 언제 사용하는지와 그것으로 만드는 음료나 음식을 밝혀야 한다. 요청된 산출물은 행동이 아니라 포괄적인 DETAIL이며, 실제 준비 단계는 선택 ACTION으로 남는다.'),
    ('prompt-preference-2570', '보온병과 따뜻한 음료라는 맥락은 이미 제시되어 있고 학습자는 그것을 언제 사용하는지만 작성하므로, 시점을 포함한 초점을 맞춘 일반 설명이면 I 수준에서 충분하다.'),
    ('prompt-preference-2571', '학습자는 과일을 담기 위해 선택한 용기를 식별하고 그 선택을 설명해야 하므로, 명시적인 두 가지 답변 요소로 충분하다.'),
    ('prompt-preference-2572', '열린 질문상 용기, 포장 습관, 정리 도구, 보관 배치나 조건이 도움 요인이 될 수 있으므로 CHOICE나 ACTION 대신 포괄적인 DETAIL이 필수이다. 이 좁은 난이도 I 과제에는 구체적인 요인 하나면 충분하다.'),
    ('prompt-preference-2573', '바쁜 날이라는 조건이 선택의 맥락을 제시하고 있으며, 학습자는 명시적으로 도시락과 그것을 사용하는 이유를 말해야 한다.'),
    ('prompt-preference-2574', '보온병을 가져간다는 내용은 표현에 제시되어 있으므로, 학습자는 그때와 내용물을 설명하면 된다. 따라서 필요한 시점과 구체적인 세부 내용이 일반 설명을 구성한다.'),
    ('prompt-preference-2575', '학습자는 소스나 간식에 사용하는 작은 용기만 식별하면 되므로, 이 간단한 질문에는 구체적인 선택 하나로 충분하다.'),
    ('prompt-preference-26', '질문은 선호하는 주문 시점과 그 시점에 어울리는 카페 음료를 묻고 있으므로, 시점과 음료 선택이 모두 나타나야 한다.'),
    ('prompt-preference-27', '학습자는 좋아하는 카페 음료를 말하고 그 매력을 설명해야 하며, 이 두 가지 직접적인 A 수준의 의무만으로도 적절한 답변이 된다.'),
    ('prompt-preference-28', '질문은 좋아하는 카페 음료를 식별하고 그것을 좋아하는 이유 두 가지를 요구하며, 요청된 두 이유는 필수 REASON 항목 안에 포함된다.'),
    ('prompt-preference-29', '학습자는 좋아하는 카페 음료에서 가장 마음에 드는 측면을 선택하고 그 측면이 왜 두드러지는지 설명해야 한다.'),
    ('prompt-preference-30', '좋아하는 카페 음료를 소개하려면 그 음료를 식별해야 하며, 무엇이 개인적으로 특별하게 만드는지를 설명하면 필요한 이유가 제시된다.'),
    ('prompt-preference-31', '즐거움을 위한 독서라는 조건은 제시되어 있고, 학습자는 평소 읽는 책의 종류를 선택하고 그 선택을 설명해야 한다.'),
    ('prompt-preference-32', '질문은 좋아하는 책 장르와 그 매력에 대한 설명을 직접 요구하므로, 선택과 이유만으로 A 수준에서 충분하다.'),
    ('prompt-preference-33', '완전한 답변은 좋아하는 책 장르를 식별하고 그것을 즐기는 이유 두 가지를 명시적으로 제시해야 하며, 이유 항목이 두 이유를 모두 포함한다.'),
    ('prompt-preference-34', '학습자는 좋아하는 책 장르에서 가장 마음에 드는 점을 선택하고 그 이유를 설명해야 하므로, 선호하는 측면과 이유가 모두 필요하다.'),
    ('prompt-preference-35', '질문은 학습자에게 좋아하는 책 장르를 식별하고 그것이 개인적으로 특별한 이유를 설명하도록 요구하며, 선택과 이유로 충분히 다룰 수 있다.'),
    ('prompt-preference-36', '학습자는 원하는 디저트 시간을 구체적으로 말하고 그 순간이 특별한 이유를 설명하면 된다. 시간과 이유는 명시되어 있지만, 더 넓은 선호 선택은 요구되지 않는다.'),
    ('prompt-preference-37', '질문은 좋아하는 디저트와 그것이 학습자에게 매력적인 이유를 요구하므로, A 수준의 답변에 필요한 내용이 충분히 제공된다.'),
    ('prompt-preference-38', '학습자는 선택한 가장 좋아하는 디저트를 설명하고 그것을 좋아하는 두 가지 이유를 제시해야 하며, 두 이유 모두 필수 이유 구성 요소에 해당한다.'),
    ('prompt-preference-39', '질문은 학습자가 가장 좋아하는 디저트에서 가장 마음에 드는 부분과 그에 대한 설명을 요구하므로, 선택한 부분과 그 이유가 필요하다.'),
    ('prompt-preference-40', '가장 좋아하는 디저트를 소개하려면 선택한 대상을 말해야 하고, 무엇이 그것을 특별하게 만드는지는 질문에서 직접 요구한 개인적인 이유이다.'),
    ('prompt-preference-41', '학습자는 선호하는 운동 시간과 기분을 좋게 해 주는 운동의 종류를 선택해야 하므로, 요청된 두 가지 선호 세부 사항이 모두 필요하다.'),
    ('prompt-preference-42', '질문은 가장 좋아하는 운동 방법과 그것이 마음에 드는 이유를 명시적으로 요구하므로, 운동 활동의 선택과 이유가 완전한 A급 핵심 요소를 이룬다.'),
    ('prompt-preference-43', '답변은 학습자가 가장 좋아하는 운동 방법을 밝히고 그것을 좋아하는 두 가지 이유를 제시해야 한다. 이러한 의무를 충족하는 것 외에 추가 항목은 필요하지 않다.'),
    ('prompt-preference-44', '질문은 가장 좋아하는 운동 방법에서 가장 마음에 드는 부분을 선택하고, 그 부분을 중요하게 여기는 이유를 설명하도록 요구한다.'),
    ('prompt-preference-45', '학습자는 가장 좋아하는 운동 방법을 밝히고 무엇이 그것을 개인적으로 특별하게 만드는지 설명해야 하므로, 선택과 이유가 직접적으로 요구된다.'),
    ('prompt-preference-46', '첫머리의 ‘언제 집중해야 하는가’는 시간 조건을 직접 요구하며, 질문에 의해 제공되는 맥락이 아니다. 또한 학습자는 좋아하는 공부 장소를 말하므로 답변 구조는 선호에 해당하고, 명시된 세 항목만으로 충분하므로 추가 깊이는 필요하지 않다.'),
    ('prompt-preference-47', '질문은 학습자가 가장 좋아하는 공부 장소와 그 장소가 마음에 드는 이유를 요구하므로, 두 가지 A급 의무만으로 충분하다.'),
    ('prompt-preference-48', '학습자는 가장 좋아하는 공부 장소를 밝히고 그 장소를 좋아하는 이유로 명시적으로 요청된 두 가지 이유를 제시해야 한다.'),
    ('prompt-preference-49', '질문은 새로운 장소를 직접 요구하는 것이 아니라, 가장 좋아하는 공부 장소에서 무엇이 가장 마음에 드는지 선택하고 그 이유를 설명하도록 요구한다.'),
    ('prompt-preference-50', '가장 좋아하는 공부 장소를 소개하려면 그 장소를 밝혀야 하고, 무엇이 그것을 특별하게 만드는지 설명하는 것이 두 번째 필수 이유 구성 요소가 된다.'),
    ('prompt-problem-01', '질문은 반복적으로 발생하는 시간 관리 문제와 학습자가 그것을 어떻게 처리하는지를 요구하므로, 문제와 대응 방식이 두 가지 중요한 B급 요구 사항이다.'),
    ('prompt-problem-02', '개인적인 시간 관리 문제와 학습자가 그것을 처리하는 방식이 모두 명시적으로 요청되므로, 이 두 항목만으로도 충분한 답변이 된다.'),
    ('prompt-problem-03', '학습자는 시간 관리와 관련된 어려움을 설명하고 그에 대해 무엇을 하는지 말해야 하므로, 문제와 해결책이 직접적으로 요구된다.'),
    ('prompt-problem-04', '질문은 시간 관리를 어렵게 만드는 요인과 학습자가 이에 어떻게 대응하는지를 각각 묻고 있으므로, 두 필수 의미 단위만으로 충분한 깊이를 제공한다.'),
    ('prompt-problem-05', '흔한 시간 관리 문제와 학습자가 시도한 해결책이 모두 명시적인 의무이므로, 완전한 B급 문제-해결 답변을 구성한다.'),
    ('prompt-problem-06', '학습자는 자주 겪는 동기 부여 문제를 밝히고 그것을 어떻게 처리하는지 설명해야 하므로, 문제와 해결책이 모두 필요하면서도 충분하다.'),
    ('prompt-problem-07', '질문은 동기를 유지하는 데 따르는 문제와 학습자가 그것을 처리하는 방식을 직접 요구하므로, 서로 독립적인 두 필수 부분을 제공한다.'),
    ('prompt-problem-08', '동기 부여와 관련된 어려움과 학습자가 그에 대해 무엇을 하는지가 별도로 요청되므로, 이 두 항목 외에 추가 깊이 항목은 필요하지 않다.'),
    ('prompt-problem-09', '질문은 동기를 유지하는 데 무엇이 어려운지와 학습자가 어떻게 대응하는지를 묻으므로, 어려움과 대응 방식이 모두 필요하다.'),
    ('prompt-problem-10', '학습자는 흔한 동기 부여 문제와 그것을 해결하기 위해 시도한 방법을 설명해야 하며, 이러한 명시적인 B급 절들만으로도 충분한 깊이가 확보된다.'),
    ('prompt-problem-11', '질문은 반복적으로 발생하는 대중 연설의 어려움 하나와 학습자가 그것을 처리하는 방식을 요구하므로, 문제와 해결책이 모두 필수이다.'),
    ('prompt-problem-1101', '학습자는 시끄러운 장소에서 겪는 어려움을 말하고 그것을 어떻게 처리하는지 설명해야 하므로, 충분한 두 가지 필수 구성 요소가 산출된다.'),
    ('prompt-problem-1102', '문구는 받은 편지함을 관리하는 문제와 학습자가 그에 대해 무엇을 하는지를 명시적으로 요구하므로, 필수적인 문제-해결 쌍만으로도 B급에서 이미 충분하다.'),
    ('prompt-problem-1103', '혼란스러울 때 질문하기가 어렵다는 내용은 질문에 제시되어 있고, 학습자는 평소의 대처 행동 하나만 제시하므로, 독립적인 보조 내용 하나가 있어야 이 B급 일상적 답변이 단순한 답변에 그치지 않는다.'),
    ('prompt-problem-1104', '학습자는 힘든 하루를 보낸 후 회복하는 데 반복적으로 방해가 되는 장애물을 밝히고 그것을 어떻게 처리하는지 설명해야 하므로, 과제의 양쪽 필수 요소를 모두 제공한다.'),
    ('prompt-problem-1105', '질문은 우선순위를 정하는 문제와 그에 대한 학습자의 대응을 요구하므로, 문제와 해결책이 각각 필요하며 함께 충분한 깊이를 제공한다.'),
    ('prompt-problem-1106', '질문은 작은 일을 제때 시작하는 데 어려움이 있다는 점을 이미 제시하고 학습자의 평소 대처 행동만 요구하므로, 이러한 B급 일상적 답변에는 보조 세부 내용 하나가 필요하다.'),
    ('prompt-problem-1107', '학습자는 긴장감을 유발하는 상황에서 말하기와 관련된 어려움을 말하고 그것을 어떻게 처리하는지 설명해야 하므로, 두 가지 필수 단위로 B급 과제를 충족한다.'),
    ('prompt-problem-1108', '통근 지연으로 발생하는 문제와 이에 대응해 취하는 행동이 모두 직접적으로 요청되므로, 추가 깊이 항목은 필수가 아니다.'),
    ('prompt-problem-1109', '열려 있는 탭이 너무 많은 것이 주어진 어려움인 반면, 학습자는 일반적인 관리 행동만 제시하므로, 난이도 B에서는 설명, 예시, 결과 또는 세부 내용 중 하나가 적절하다.'),
    ('prompt-problem-1110', '질문은 사람의 이름을 기억할 때 반복적으로 겪는 어려움과 학습자가 이를 어떻게 대처하는지를 요구하므로, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-1111', '학습자는 갈등 중에 침착함을 유지하는 데 관한 문제를 설명하고 이에 대해 무엇을 하는지 밝혀야 하므로, 이미 상당한 수준의 B급 구성 요소 두 가지가 제시되어 있다.'),
    ('prompt-problem-1112', '사소한 기술적 문제가 어려움으로 제시되고 학습자는 일반적인 대처 행동만 작성하므로, 하나의 독립적인 뒷받침 내용이 해당 단일 필수 B급 답변을 발전시킨다.'),
    ('prompt-problem-1113', '질문은 미완성 작업을 일찍 공유할 때 겪는 어려움과 학습자의 대처 전략을 요구하므로, 두 의미 구성 요소가 모두 필수이다.'),
    ('prompt-problem-1114', '졸린 아침에 겪는 문제와 그에 대한 대응이 별도로 요구되므로, 답변은 충분한 필수 깊이를 갖춘다.'),
    ('prompt-problem-1115', '주말을 지나치게 계획하는 것이 이미 문제로 제시되어 있으므로, 학습자는 계획을 관리 가능한 상태로 유지하는 일반적인 행동만 제시한다. B급에서는 추가적인 뒷받침 내용 하나가 필요하다.'),
    ('prompt-problem-1116', '학습자는 진전이 느리게 느껴질 때 발생하는 어려움을 파악하고 어떻게 대처하는지 설명해야 하므로, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-1117', '질문은 자기 비교로 인해 생기는 문제와 학습자가 이에 대해 무엇을 하는지를 명시적으로 요구하므로, 필수 항목 두 가지가 과제를 완성한다.'),
    ('prompt-problem-1118', '취미와 집안일의 균형을 맞추기 어려운 점이 제시되어 있어 학습자는 일반적인 대처 행동만 작성하면 된다. 이 B급 일상적 대응을 발전시키려면 추가적인 뒷받침 내용 하나가 필요하다.'),
    ('prompt-problem-1119', '학습자는 정중하게 거절할 때 겪는 어려움을 말하고 어떻게 대처하는지 설명해야 하므로, 명시적이고 충분한 B급 의무 사항 두 가지가 도출된다.'),
    ('prompt-problem-1120', '질문은 놓친 일과를 다시 시작할 때의 문제와 학습자의 대응을 요구하므로, 장애 요소와 해결책이 모두 필요하다.'),
    ('prompt-problem-1121', '긴 글을 읽는 동안 집중력을 잃는 것이 제시된 어려움이고 학습자는 일반적인 대처 행동만 작성하므로, 하나의 뒷받침 단위가 충분히 발전되지 않은 B급 일상적 답변을 방지한다.'),
    ('prompt-problem-1122', '반복적으로 겪는 책상 정리의 어려움과 이를 처리하는 방법이 모두 직접 요구되므로, B급에 필요한 깊이가 충분하다.'),
    ('prompt-problem-1123', '학습자는 붐비는 공간에서 겪는 문제를 설명하고 이에 대해 무엇을 하는지 밝혀야 하므로, 문제와 해결책의 조합만으로 충분하다.'),
    ('prompt-problem-1124', '주의를 산만하게 하는 메시지가 이미 문제로 제시된 반면 학습자는 일반적인 대처 행동만 제시하므로, 이 B급 일상적 상황에는 독립적인 뒷받침 내용 하나가 적절하다.'),
    ('prompt-problem-1125', '질문은 생각을 명확하게 요약할 때의 어려움과 학습자의 대처 전략을 요구하므로, 의사소통 문제와 해결책이 모두 필수이다.'),
    ('prompt-problem-1126', '학습자는 첫 번째 시도에서 지시를 따르는 데 관한 문제를 설명하고 이에 대한 대응을 밝혀야 하므로, 과제에서 요구하는 양쪽 측면을 모두 충족한다.'),
    ('prompt-problem-1127', '긴 줄에서 참을성을 잃는 것이 제시된 어려움이므로 학습자는 일반적인 대처 행동만 제시한다. 감정, 이유, 예시, 결과 또는 세부 내용이 적절한 B급 깊이를 더한다.'),
    ('prompt-problem-12', '질문은 대중 앞에서 말할 때의 문제와 학습자가 이를 어떻게 다루는지에 대한 설명을 요구하므로, 문제와 해결책이 모두 직접 필요하다.'),
    ('prompt-problem-13', '사람들 앞에서 말하는 것과 관련된 어려움과 이에 대해 취하는 행동이 별도로 요구되므로, 답변은 필요한 B급 내용을 충분히 갖춘다.'),
    ('prompt-problem-14', '질문은 대중 앞에서 말할 때 개인적으로 어려운 점과 학습자의 대응을 요구하므로, 두 의미 단위가 모두 필수이다.'),
    ('prompt-problem-15', '학습자는 흔히 겪는 대중 연설 문제와 시도한 해결책을 설명해야 하므로, 이미 완전한 두 부분의 B급 답변을 구성한다.'),
    ('prompt-problem-16', '질문은 일과 휴식의 균형을 맞출 때 반복적으로 겪는 어려움과 그 대처 방법을 요구하므로, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-17', '개인적인 일과 휴식의 균형 문제와 학습자가 이를 처리하는 방식이 모두 명시적으로 요구되므로, 필수 항목 두 가지로 충분하다.'),
    ('prompt-problem-18', '학습자는 일과 휴식의 균형과 관련된 어려움을 파악하고 이에 대해 무엇을 하는지 밝혀야 하므로, 문제와 해결책이 필요하다.'),
    ('prompt-problem-19', '질문은 일과 휴식의 균형에서 어려운 점과 학습자의 대응을 별도로 요구하므로, 적절한 두 부분의 핵심 답변이 형성된다.'),
    ('prompt-problem-20', '일과 휴식의 균형에서 흔히 겪는 문제와 학습자가 시도한 해결책이 모두 문자 그대로의 필수 사항이므로, 추가적인 필수 깊이는 필요하지 않다.'),
    ('prompt-problem-21', '학습자는 반복적으로 겪는 팀워크의 어려움을 말하고 어떻게 대처하는지 설명해야 하므로, 문제와 해결책이 모두 직접 요구된다.'),
    ('prompt-problem-22', '문구는 학습자가 팀으로 일할 때 겪는 문제와 이를 해결하는 방식을 요구하므로, 충분한 B급 요구 사항 두 가지가 제시된다.'),
    ('prompt-problem-23', '팀워크와 관련된 어려움과 학습자가 이에 대해 하는 행동이 별도로 요구되므로, 문제와 해결책의 조합이 핵심 답변을 완성한다.'),
    ('prompt-problem-24', '질문은 팀 활동 참여에서 어려운 점과 학습자의 대응을 요구하므로, 개인적인 문제와 대처 방법이 모두 필요하다.'),
    ('prompt-problem-25', '학습자는 팀워크에서 겪는 일반적인 문제와 이를 해결하려고 하는 방법을 설명해야 하므로, 서로 독립적이고 충분한 두 개의 답변 단위를 제시하게 된다.'),
    ('prompt-problem-26', '질문은 신속한 의사 결정을 할 때 반복해서 겪는 어려움과 학습자가 이를 처리하는 방법을 묻기 때문에, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-27', '신속한 의사 결정 중에 겪은 문제와 학습자가 이를 해결하는 방법을 명시적으로 요구하므로, 이 두 요소만으로 충분하다.'),
    ('prompt-problem-28', '학습자는 신속한 의사 결정과 관련된 어려움과 이에 대해 무엇을 하는지를 밝혀야 하므로, 문제와 해결책이 모두 직접적으로 요구된다.'),
    ('prompt-problem-29', '질문은 신속한 의사 결정에서 무엇이 어려운지와 학습자가 어떻게 대응하는지를 별도로 묻기 때문에, 이 두 가지 필수 요소만으로도 충분한 깊이를 제공한다.'),
    ('prompt-problem-30', '신속한 의사 결정에서 발생하는 일반적인 문제와 학습자가 시도하는 해결책을 문제의 표현이 모두 요구하므로, 완전한 B급 답변이 된다.'),
    ('prompt-problem-31', '질문은 집단 과제에서 반복해서 겪는 어려움과 학습자가 이를 처리하는 방법을 묻기 때문에, 문제와 처리 전략이 모두 필요하다.'),
    ('prompt-problem-32', '학습자는 집단 과제 수행에서 겪은 문제를 설명하고 이를 어떻게 해결하는지 밝혀야 하므로, 충분한 두 부분으로 이루어진 답변이 된다.'),
    ('prompt-problem-33', '집단 과제의 어려움과 이에 대해 학습자가 무엇을 하는지가 별도로 요구되므로, 문제와 해결책이 모두 필수이다.'),
    ('prompt-problem-34', '질문은 집단 과제 수행에서 학습자가 겪는 어려움과 그에 대한 대응을 요구하므로, 명시된 두 가지 의무만으로도 충분한 B급 깊이를 제공한다.'),
    ('prompt-problem-35', '학습자는 집단 과제에서 흔히 발생하는 문제와 이를 해결하려고 하는 방법을 설명해야 하므로, 문제와 해결책의 짝이 직접적으로 요구된다.'),
    ('prompt-problem-36', '질문은 집중력을 유지할 때 반복해서 겪는 어려움과 학습자가 이를 처리하는 방법을 요구하므로, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-37', '집중하려고 할 때 겪는 문제와 학습자가 이를 처리하는 방법이 모두 명시적으로 요구되므로, 핵심 과제가 완성된다.'),
    ('prompt-problem-38', '학습자는 집중력과 관련된 어려움을 밝히고 이에 대해 무엇을 하는지 말해야 하므로, 서로 독립적인 두 개의 필수 항목만으로도 충분한 깊이를 제공한다.'),
    ('prompt-problem-39', '질문은 집중력을 유지할 때 무엇이 어려운지와 학습자가 어떻게 대응하는지를 묻기 때문에, 문제와 해결책이 직접적으로 요구된다.'),
    ('prompt-problem-40', '집중력과 관련된 일반적인 문제와 학습자가 이를 해결하려고 하는 방법이 별도로 요구되므로, 두 부분으로 이루어진 B급 답변만으로 충분하다.'),
    ('prompt-problem-41', '학습자는 예상치 못한 변화로 인해 반복해서 겪는 어려움을 밝히고 이를 어떻게 처리하는지 설명해야 하므로, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-42', '질문은 예상치 못한 변화와 관련된 문제와 학습자가 이를 처리하는 방법을 명시적으로 요구하므로, 이 두 부분만으로 충분한 깊이를 제공한다.'),
    ('prompt-problem-43', '예상치 못한 변화와 관련된 어려움과 이에 대해 학습자가 무엇을 하는지가 모두 명시된 의무이므로, 문제와 해결책이 필요하다.'),
    ('prompt-problem-44', '질문은 예상치 못한 변화에서 개인적으로 무엇이 어려운지와 학습자가 어떻게 대응하는지를 묻기 때문에, 두 개의 필수 단위만으로 과제가 완성된다.'),
    ('prompt-problem-45', '학습자는 예상치 못한 변화로 인해 흔히 발생하는 문제와 시도한 해결책을 설명해야 하므로, 충분한 B급 문제와 해결책의 핵심을 형성한다.'),
    ('prompt-problem-46', '질문은 사소한 실수를 지나치게 곱씹을 때 반복해서 겪는 어려움과 학습자가 이를 처리하는 방법을 묻기 때문에, 문제와 해결책이 모두 필요하다.'),
    ('prompt-problem-47', '사소한 실수를 계속 곱씹을 때 학습자가 겪는 문제와 이를 해결하는 방법이 명시적으로 요구되므로, 두 항목이 모두 필수이다.'),
    ('prompt-problem-48', '학습자는 사소한 실수를 지나치게 생각하는 것과 관련된 어려움을 설명하고 이에 대해 무엇을 하는지 밝혀야 하므로, 충분한 두 개의 필수 요소를 제시하게 된다.'),
    ('prompt-problem-49', '질문은 사소한 실수를 지나치게 생각할 때 무엇이 어려운지와 학습자가 어떻게 대응하는지를 별도로 요구하므로, 문제와 해결책의 짝이 필요하다.'),
    ('prompt-problem-50', '지나치게 곱씹은 실수와 관련된 일반적인 문제와 학습자가 이를 해결하려고 하는 방법이 모두 직접적으로 요구되므로, 충분한 B급 깊이를 형성한다.'),
    ('prompt-reflection-01', '성공에 대한 생각이 시간이 지나면서 어떻게 바뀌었는지 설명하려면 이전의 관점, 현재의 관점, 변화의 이유가 필요하므로, 이 세 가지 단위가 충분한 C급 깊이를 제공한다.'),
    ('prompt-reflection-02', '질문은 성공에 대한 학습자의 과거 믿음과 생각을 바꾼 요인을 직접적으로 묻기 때문에, 현재의 믿음과 같은 독립적인 추가 요소 하나를 포함하는 것이 이 C급 성찰에 적절하다.'),
    ('prompt-reflection-03', '질문은 성공에 대한 과거와 현재의 생각 및 변화의 원인을 명시적으로 묻기 때문에, 이 세 가지 필수 단위만으로도 충분한 깊이를 제공한다.'),
    ('prompt-reflection-04', '학습자는 성공에 대한 과거의 믿음을 밝히고 무엇이 그 믿음을 바꾸게 했는지 설명해야 하므로, 새로운 믿음은 직접적으로 요구되지 않기 때문에 현재의 믿음이나 다른 독립적인 뒷받침 요소 하나가 필요하다.'),
    ('prompt-reflection-05', '문제의 표현은 성공에 대한 생각이 시간에 따라 어떻게 다른지를 묻기 때문에, 과거와 현재의 관점이 모두 필요하다. 여기에 변화의 원인, 사례 또는 영향 중 하나를 더하면 이 고급 성찰에 충분한 뒷받침을 제공한다.'),
    ('prompt-reflection-06', '학습자는 과거와 현재의 공부 습관을 대조하고 왜 바뀌었는지 설명해야 하므로, 이미 충분히 발전된 세 가지 독립적인 필수 요소를 제시하게 된다.'),
    ('prompt-reflection-07', '질문은 학습 습관에 대한 예전의 믿음과 무엇이 학습자의 생각을 바꾸었는지를 직접 요구한다. 성찰을 완성하려면 현재의 믿음 하나 또는 별도의 독립적인 뒷받침이 필요하다.'),
    ('prompt-reflection-08', '질문은 학습 습관이 어떻게 변했는지와 무엇이 변화를 일으켰는지를 직접 묻는다. 따라서 추가적인 깊이 요구 없이 이전 습관, 현재 습관, 원인이 필요하다.'),
    ('prompt-reflection-09', '질문은 학습 습관에 대한 예전의 믿음을 밝히고 그것을 바꾼 원인을 설명하도록 한다. 현재 상태 하나 또는 비교 가능한 뒷받침이 있으면 고급 답변에 충분한 깊이가 생긴다.'),
    ('prompt-reflection-10', '시간이 지나면서 학습 습관이 어떻게 변했는지 설명하려면 과거와 현재의 대조가 필요하다. 또한 원인, 예시, 결과 중 하나가 있어야 고급 답변이 그 대조에만 머물지 않는다.'),
    ('prompt-reflection-11', '질문은 소셜 미디어에 대한 과거와 현재의 견해를 묻고 변화가 일어난 이유를 명시적으로 요구한다. 따라서 변화의 세 요소가 모두 필요하며 그것만으로 충분하다.'),
    ('prompt-reflection-1101', '학습자는 경쟁에 대한 이전 견해와 현재 견해를 비교하고 왜 바뀌었는지 설명해야 한다. 명시된 세 가지 요구가 이미 완전한 고급 답변을 구성한다.'),
    ('prompt-reflection-1102', '질문은 휴식을 취하는 것에 대한 예전의 이해, 성장하면서 형성된 이해, 그리고 그 형성에 영향을 준 요인을 요구한다. 추가 항목 없이도 충분한 깊이가 확보된다.'),
    ('prompt-reflection-1103', '혼자 사는 것에 대한 의견의 변화를 설명하려면 이전 의견과 현재 의견이 필요하고, 왜 바뀌었는지에 대한 명시적인 요구가 원인을 추가한다. 이 세 단위가 기대되는 깊이를 충족한다.'),
    ('prompt-reflection-1104', '질문은 인맥 형성에 대한 과거와 현재의 견해 및 변화의 이유를 요구한다. 따라서 명시된 세 가지 의미 단위가 필요하며, 의무적인 추가 뒷받침은 필요하지 않다.'),
    ('prompt-reflection-1105', '학습자는 잡담에 대한 이전과 이후의 이해를 설명하고 무엇이 그 이해에 영향을 주었는지 밝혀야 한다. 두 상태와 원인이 필요하며 내용도 충분히 충실하다.'),
    ('prompt-reflection-1106', '질문은 도움을 요청하는 것에 대한 의견이 과거의 입장에서 현재의 입장으로 어떻게 바뀌었는지와 그 이유를 직접 요구한다. 따라서 필요한 세 항목만으로 충분하다.'),
    ('prompt-reflection-1107', '완전한 답변은 생산성에 대한 예전과 현재의 견해를 밝히고 왜 변화가 일어났는지 설명해야 한다. 명시된 내용만으로도 분석에 충분한 깊이가 제공된다.'),
    ('prompt-reflection-1108', '질문은 지루함에 대한 이전의 이해와 성숙한 이해를 비교하고 변화를 만든 영향을 함께 요구한다. 따라서 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-reflection-1109', '학습자는 패션에 대한 과거와 현재의 의견 및 의견이 바뀐 이유를 모두 설명해야 한다. 직접 요구된 세 단위를 통해 충분한 깊이가 충족된다.'),
    ('prompt-reflection-1110', '질문은 혼자 보내는 시간에 대한 견해가 과거와 어떻게 다른지와 그 이유를 묻는다. 따라서 이전 상태, 현재 상태, 원인이 필요하며 추가적인 최소 뒷받침은 필요하지 않다.'),
    ('prompt-reflection-1111', '질문은 운동에 대한 이전의 이해, 성장한 후의 이해, 그리고 변화의 배경이 된 영향을 요구한다. 이 세 가지 필수 내용만으로 충분하다.'),
    ('prompt-reflection-1112', '온라인 수업에 대한 의견의 변화를 설명하려면 과거와 현재의 입장이 필요하고, 왜 바뀌었는지를 설명하려면 원인이 직접 요구된다. 이 조합만으로도 고급 깊이의 기대를 충족한다.'),
    ('prompt-reflection-1113', '학습자는 일기를 쓰는 것에 대한 과거와 현재의 견해를 대조하고 변화의 이유를 제시해야 한다. 명시된 변화의 모든 요소가 필요하며 그것만으로 충분하다.'),
    ('prompt-reflection-1114', '질문은 지역 공동체 생활에 대한 학습자의 이전과 이후의 이해 및 그 이해의 형성에 영향을 준 요인을 요구한다. 이 세 가지 필수 단위가 충분한 깊이를 제공한다.'),
    ('prompt-reflection-1115', '질문은 일과가 과거의 견해에서 현재의 견해로 어떻게 바뀌었는지와 그 이유를 묻는다. 따라서 두 상태와 원인이 직접 요구되며 내용도 충분히 구체적이다.'),
    ('prompt-reflection-1116', '질문은 실수에 대한 예전과 현재의 견해 및 전환이 일어난 이유를 명시적으로 요구한다. 따라서 세 가지 필수 단위만으로 답변에 충분하다.'),
    ('prompt-reflection-1117', '답변은 피드백을 받는 것에 대한 이전의 이해와 발전된 이해를 비교하고 그 변화에 영향을 준 요인을 밝혀야 한다. 따라서 선택 항목을 반드시 추가할 필요는 없다.'),
    ('prompt-reflection-1118', '질문은 주말을 보내는 것에 대한 과거와 현재의 의견 및 변화에 대한 설명을 요구한다. 이 세 가지 독립적인 요구만으로도 충분한 깊이가 형성된다.'),
    ('prompt-reflection-1119', '학습자는 물건을 적게 소유하는 것에 대한 견해가 어떻게 바뀌었고 왜 바뀌었는지 보여 주어야 한다. 이전 상태, 현재 상태, 원인이 함께 있으면 충분하다.'),
    ('prompt-reflection-1120', '질문은 시간 엄수에 대한 이전과 이후의 이해 및 변화를 이끈 요인을 요구한다. 따라서 명시된 세 요소만 필요하며 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-reflection-1121', '팀워크에 대한 의견의 변화를 설명하려면 이전 의견과 현재 의견을 밝혀야 하고, 왜 바뀌었는지 설명하려면 원인이 필요하다. 이 항목들만으로 이미 충분하다.'),
    ('prompt-reflection-1122', '질문은 사생활에 대한 견해가 과거에서 현재로 어떻게 바뀌었고 왜 그런 변화가 일어났는지를 직접 묻는다. 따라서 두 상태와 원인이 필요하며 그것으로 충분하다.'),
    ('prompt-reflection-1123', '학습자는 직장이나 학교 가까이 사는 것에 대한 이전과 성장한 후의 이해를 비교하고 변화에 영향을 준 요인을 밝혀야 한다. 필요한 깊이는 이 내용만으로 충분하다.'),
    ('prompt-reflection-1124', '질문은 집에서 요리하는 것에 대한 의견이 시간이 지나며 어떻게 바뀌었고 왜 바뀌었는지를 묻는다. 따라서 예전 의견, 현재 의견, 원인이 필요하며 추가적인 필수 뒷받침은 없다.'),
    ('prompt-reflection-1125', '완전한 답변은 대중 앞에서 말하는 것에 대한 과거와 현재의 견해를 대조하고 변화의 이유를 설명해야 한다. 이 명시적인 내용만으로 깊이가 충족된다.'),
    ('prompt-reflection-1126', '질문은 아르바이트에 대한 이전과 발전된 이해 및 그 이해의 형성에 영향을 준 요인을 요구한다. 따라서 세 가지 필수 단위만으로 충분하다.'),
    ('prompt-reflection-1127', '학습자는 미리 계획하는 것에 대한 의견이 이전과 어떻게 다른지 밝히고 그 이유를 설명해야 한다. 따라서 두 상태와 변화의 원인이 필요하며 그것으로 충분하다.'),
    ('prompt-reflection-12', '문구는 소셜 미디어에 대한 과거의 믿음과 학습자의 생각을 바꾼 것을 직접 요구한다. 고급 성찰을 완성하려면 현재의 견해 하나 또는 이에 준하는 근거가 필요하다.'),
    ('prompt-reflection-13', '질문은 소셜 미디어에 대한 견해가 어떻게 바뀌었고 무엇이 그 변화를 일으켰는지를 묻는다. 따라서 이전 견해, 현재 견해, 원인이 모두 명시되어 있으며 충분한 깊이를 제공한다.'),
    ('prompt-reflection-14', '학습자는 소셜 미디어에 대한 과거의 믿음과 그 믿음이 바뀐 이유를 직접 답해야 한다. 충분한 깊이를 위해 현재의 견해 하나 또는 그 밖의 독립적인 근거가 필요하다.'),
    ('prompt-reflection-15', '소셜 미디어에 대한 견해의 변화를 답하려면 이전 견해와 현재 견해를 모두 밝혀야 한다. 원인, 예시 또는 결과 중 하나를 더하면 비교에 적절한 깊이가 생긴다.'),
    ('prompt-reflection-16', '과제는 돈에 대한 과거와 현재의 의견 및 두 의견이 다른 이유에 대한 설명을 명시적으로 요구한다. 따라서 필수 요소 세 가지만으로도 충분히 발전된 답변이 구성된다.'),
    ('prompt-reflection-17', '학습자는 돈에 대한 과거의 믿음과 그 믿음을 바꾼 계기를 직접 답해야 한다. 이 고급 수준에서는 현재의 입장 하나 또는 그 밖의 독립적인 근거를 더하는 것이 적절하다.'),
    ('prompt-reflection-18', '질문은 돈에 대한 의견이 과거의 상태에서 현재의 상태로 어떻게 바뀌었고 무엇이 그 변화를 일으켰는지를 요구한다. 따라서 추가적인 깊이 요소는 필요하지 않다.'),
    ('prompt-reflection-19', '질문은 돈에 대한 과거의 믿음과 학습자가 그 믿음을 바꾼 이유를 요구한다. 새로운 입장은 명시적으로 요구되지 않으므로, 충분한 깊이를 위해 현재의 믿음 하나 또는 다른 독립적인 세부 내용이 적절하다.'),
    ('prompt-reflection-20', '질문은 시간이 지나며 돈에 대한 의견이 어떻게 바뀌었는지를 묻으므로 과거와 현재의 상태가 모두 필수이다. 대조가 피상적이지 않도록 독립적인 설명이나 예시 하나가 필요하다.'),
    ('prompt-reflection-21', '학습자는 리더십에 대한 과거와 현재의 이해를 설명하고 그 이해가 바뀐 이유를 밝혀야 한다. 명시된 세 부분이 모두 필요하며 충분하다.'),
    ('prompt-reflection-22', '질문은 학습자가 리더십에 대해 과거에 무엇을 믿었고 무엇이 그 믿음을 바꾸었는지를 직접 묻는다. 완전한 성찰을 위해 현재의 이해 하나 또는 유사한 근거가 필요하다.'),
    ('prompt-reflection-23', '리더십에 대한 이해가 어떻게 바뀌었는지를 답하려면 이전의 이해와 현재의 이해가 필요하며, 두 번째 절에서 원인도 직접 요구한다. 따라서 추가적인 선택 요소 없이도 충분한 깊이가 있다.'),
    ('prompt-reflection-24', '질문은 학습자에게 과거의 리더십에 대한 믿음을 밝히고 그것이 바뀐 이유를 설명하도록 한다. 현재의 이해는 선택 사항으로 남아 있으며, 깊이를 위해 독립적인 근거 하나가 필요하다.'),
    ('prompt-reflection-25', '질문은 리더십에 대한 이해가 시간에 따라 어떻게 달라졌는지를 묻으므로 과거와 현재의 상태가 모두 필요하다. 고급 수준의 비교를 심화하려면 원인, 예시 또는 결과 중 하나를 제시해야 한다.'),
    ('prompt-reflection-26', '우정에 대한 견해가 어떻게 바뀌었는지를 설명하려면 과거와 현재의 형태가 모두 필요하다. 설명이 명시적으로 요구되지는 않으므로 원인이나 예시 하나가 고급 수준에 적절한 깊이를 제공한다.'),
    ('prompt-reflection-27', '우정에 대한 사고의 변화에는 이전 입장과 현재 입장이 포함되며, 질문은 별도로 그 원인도 묻는다. 따라서 이 세 요소만으로 충분하다.'),
    ('prompt-reflection-28', '학습자는 우정에 대한 과거의 의견과 그것이 어떻게 달라졌는지를 밝혀야 하므로 과거와 현재의 상태가 필요하다. 근거나 예시를 하나 더하면 설명이 충분히 발전된다.'),
    ('prompt-reflection-29', '문구는 우정에 대한 현재의 견해를 중심에 두고 과거와 명시적으로 비교한다. 따라서 두 상태가 모두 필요하며, 필요한 깊이를 위해 설명이나 예시 하나를 더해야 한다.'),
    ('prompt-reflection-30', '직접적인 요구 사항은 우정에 대한 사고의 변화를 일으킨 경험이다. 그 경험으로 무엇이 바뀌었는지를 보여 주려면 그 결과로 생긴 견해나 과거의 견해에 대한 설명 하나가 필요하다.'),
    ('prompt-reflection-31', '건강한 식습관에 대한 견해의 변화는 과거와 현재의 상태를 통해 표현해야 한다. 원인, 예시 또는 결과 중 하나를 더하면 고급 답변에 충분한 전개가 이루어진다.'),
    ('prompt-reflection-32', '건강한 식습관에 대한 사고의 변화에는 이전의 입장과 현재의 입장이 필요하며, 원인도 별도로 요구된다. 따라서 필수 요소만으로 충분한 깊이가 형성된다.'),
    ('prompt-reflection-33', '건강한 식습관에 대해 과거에 가졌던 의견과 그 의견이 어떻게 바뀌었는지를 답하려면 과거와 현재의 의견이 모두 필요하다. 이 수준의 성찰을 완성하려면 독립적인 원인이나 예시 하나가 필요하다.'),
    ('prompt-reflection-34', '질문은 건강한 식습관에 대한 현재의 견해가 과거와 어떻게 다른지를 명시적으로 묻으므로 대조의 양쪽이 모두 필요하다. 적절한 깊이를 위해 뒷받침하는 세부 내용 하나를 더해야 한다.'),
    ('prompt-reflection-35', '질문은 건강한 식습관에 대한 사고의 변화를 일으킨 경험을 직접 묻는다. 그 경험과 함께 결과로 생긴 견해나 과거의 견해 중 하나를 제시해야 변화를 명확히 할 수 있다.'),
    ('prompt-reflection-36', '뉴스 소비에 대한 변화하는 견해를 설명하려면 과거와 현재의 형태가 필요하다. 고급 답변이 단순한 대조에 그치지 않도록 원인, 예시 또는 결과 중 하나를 더해야 한다.'),
    ('prompt-reflection-37', '뉴스 소비에 대한 사고의 변화에는 이전 견해와 현재 견해가 필요하며, 두 번째 절에서 원인을 요구한다. 이 세 요소만으로도 충분히 풍부하다.'),
    ('prompt-reflection-38', '학습자는 뉴스 소비에 대한 과거의 의견을 밝히고 그것이 어떻게 새로운 형태가 되었는지를 설명해야 하므로 두 상태가 모두 필요하다. 적절한 뒷받침을 위해 원인이나 예시 하나를 더해야 한다.'),
    ('prompt-reflection-39', '질문은 뉴스 소비에 대한 현재의 견해와 과거의 견해를 직접 대조한다. 이 비교를 발전시키려면 이유, 예시 또는 결과 중 하나가 필요하다.'),
    ('prompt-reflection-40', '명시적인 목표는 뉴스 소비에 대한 학습자의 사고를 바꾼 경험이다. 그 경험의 의미를 보여 주려면 과거의 견해나 그 결과로 생긴 견해에 대한 설명 하나가 필요하다.'),
    ('prompt-reflection-41', '변화하는 여행에 대한 견해를 설명하려면 과거와 현재의 관점이 필요하다. 이 고급 성찰을 심화하려면 원인, 예시 또는 결과 중 하나를 더하는 것이 적절하다.'),
    ('prompt-reflection-42', '질문은 여행에 대한 사고의 변화 하나와 그 원인을 별도로 묻는다. 따라서 이전 견해, 현재 견해, 계기가 필요하며 추가적인 최소 뒷받침은 요구되지 않는다.'),
    ('prompt-reflection-43', '학습자는 여행에 대한 과거의 의견과 그것이 어떻게 달라졌는지를 답해야 하므로 과거와 현재의 상태가 필수이다. 충분한 깊이를 위해 독립적인 근거 하나를 더해야 한다.'),
    ('prompt-reflection-44', '질문은 학습자의 현재 여행관이 과거와 어떻게 다른지 묻고 있으므로 두 관점을 모두 직접 요구한다. 대조를 충분히 드러내려면 설명이나 예시 하나가 필요하다.'),
    ('prompt-reflection-45', '직접적인 답변은 학습자의 여행에 대한 생각을 바꾼 경험이다. 변화가 분명해지도록 그 결과로 생긴 관점이나 이전 관점에 대한 설명 하나가 필요하다.'),
    ('prompt-reflection-46', '시간이 지나면서 실패에 대한 관점이 어떻게 달라졌는지 설명하려면 이전 상태와 현재 상태가 필요하다. 질문에서 기대하는 추가 깊이를 위해 원인, 예시 또는 영향 하나를 제시해야 한다.'),
    ('prompt-reflection-47', '실패에 대한 생각의 변화는 기존 입장과 새로운 입장으로 이루어지며, 질문은 그 원인도 묻고 있다. 따라서 이 세 가지 필수 부분으로 충분하다.'),
    ('prompt-reflection-48', '한때 가졌던 실패에 대한 의견과 그 변화는 과거 관점과 현재 관점을 모두 요구한다. 대조를 뒷받침할 이유나 구체적인 예시 하나를 제시해야 한다.'),
    ('prompt-reflection-49', '질문은 실패에 대한 현재의 이해와 과거의 이해를 명시적으로 비교하므로 두 상태가 모두 필요하다. 적절한 분석적 깊이를 위해 원인, 예시 또는 결과 하나를 덧붙여야 한다.'),
    ('prompt-reflection-50', '질문은 학습자의 실패에 대한 생각을 바꾼 경험을 직접 묻고 있다. 실제 변화가 드러나도록 그 결과로 생긴 관점이나 이전 관점에 대한 설명 하나가 필요하다.'),
    ('prompt-routine-01', '질문은 평일 아침에 보통 하는 활동을 묻는다. 입문 수준에서는 답변이 단순한 활동명에 그치지 않도록 추가 행동 하나, 구체적인 시간 정보 또는 다른 뒷받침 내용이 필요하다.'),
    ('prompt-routine-02', '학습자는 평일 아침에 보통 무엇을 하는지 말해야 하며, 발전된 중급 답변을 위해 독립적인 단계 하나, 시간 또는 설명 하나를 제시하는 것이 적절하다.'),
    ('prompt-routine-03', '평일 아침 일과를 설명하려면 적어도 습관적인 행동 하나가 필요하다. 일과가 단순한 한 가지 명칭에 그치지 않도록 두 번째 단계나 구체적인 시간 정보도 제시해야 한다.'),
    ('prompt-routine-04', '문구는 평일 아침에 자주 반복하는 행동을 직접 요구한다. 답변에 적절한 중급 수준의 깊이를 더하려면 추가 행동 하나, 시간 정보 또는 이유를 제시해야 한다.'),
    ('prompt-routine-05', '평일 아침을 보통 어떻게 보내는지는 습관적인 행동을 요구한다. 답변이 짧은 한 절에만 머물지 않도록 별도의 단계, 시간 정보 또는 결과 하나를 덧붙여야 한다.'),
    ('prompt-routine-06', '질문은 퇴근이나 수업 후 저녁에 보통 하는 활동을 묻는다. 충분히 발전된 답변을 위해 추가 행동 하나, 시간, 장소 또는 설명 하나가 필요하다.'),
    ('prompt-routine-07', '직접적인 필수 내용은 퇴근이나 수업 후 저녁에 보통 하는 행동이다. 답변이 최소한에 그치지 않도록 독립적인 단계 하나나 맥락 정보 하나를 덧붙여야 한다.'),
    ('prompt-routine-08', '퇴근이나 수업 후 저녁 일과에는 습관적인 행동이 포함되어야 한다. 설명하는 일과를 충분히 유용한 내용으로 만들려면 두 번째 행동이나 구체적인 맥락이 필요하다.'),
    ('prompt-routine-09', '질문은 저녁에 퇴근이나 수업 후 무엇을 자주 하는지 묻는다. 따라서 행동이 필요하며, 적절한 깊이를 위해 별도의 맥락 정보나 설명 하나를 덧붙여야 한다.'),
    ('prompt-routine-10', '그러한 저녁을 보통 어떻게 보내는지 설명하려면 습관적인 행동이 필요하다. 답변이 지나치게 빈약해지지 않도록 추가 행동, 시간, 장소 또는 이점 하나를 제시해야 한다.'),
    ('prompt-routine-11', '질문은 일요일 오후를 보통 어떻게 보내는지 직접 묻는다. 입문 수준에서도 단순한 행동만 제시하지 않도록 독립적인 활동 하나나 맥락 정보 하나가 필요하다.'),
    ('prompt-routine-1101', '학습자는 빨래하는 날 무엇을 하는지 설명하고, 그 일과 중 가장 도움이 되는 부분을 선택해야 한다. 이 두 가지 명시적 답변으로 충분하며, 이점에 대한 자세한 설명은 선택적으로 덧붙일 수 있다.'),
    ('prompt-routine-1102', '질문은 이른 약속 전에 하는 일과 그것이 잘 작동하는 이유를 묻는다. 따라서 습관적인 행동과 그 도움이 되는 효과가 모두 필요하며, 이 두 내용만으로도 충분한 깊이가 확보된다.'),
    ('prompt-routine-1103', '학습자는 장을 본 후 보통 무엇을 하는지 말하고 그 이유를 직접 설명해야 한다. 따라서 행동과 이유만으로 충분하며, 다른 필수 세부 내용은 없다.'),
    ('prompt-routine-1104', '질문은 수업을 기다리는 동안 하는 활동과 그 일과 중 가장 도움이 되는 부분을 선택하도록 요구한다. 이 두 가지 요청 단위로 충분한 답변을 구성할 수 있다.'),
    ('prompt-routine-1105', '질문은 업무 첫 시간에 무엇을 하는지와 그 일과가 잘 작동하는 이유를 묻는다. 따라서 습관적인 행동과 그 유익한 결과가 필요하며, 추가 깊이를 위한 별도 항목은 없다.'),
    ('prompt-routine-1106', '학습자는 조용한 일요일 저녁에 보통 하는 행동과 그 이유를 명시적으로 답해야 한다. 이 두 필수 절만으로도 중급 수준의 깊이를 충족한다.'),
    ('prompt-routine-1107', '답변은 친구들과 저녁 식사를 만나기 전에 하는 준비를 설명하고, 그중 가장 도움이 되는 부분을 밝혀야 한다. 이 두 가지 별도 요구만으로 충분하며, 이점은 선택적으로 자세히 설명할 수 있다.'),
    ('prompt-routine-1108', '질문은 운동 후 보통 하는 행동과 그 일과가 잘 작동하는 이유를 묻는다. 따라서 행동과 그 도움이 되는 효과가 모두 필요하며, 이 내용만으로 충분하다.'),
    ('prompt-routine-1109', '학습자는 긴 기차 여행 중 보통 무엇을 하는지와 그 이유를 말해야 한다. 이 두 가지 명시적 절만으로 충분하며, 선택적인 추가 뒷받침 내용은 필수가 아니다.'),
    ('prompt-routine-1110', '질문은 집에 있는 날의 일과와 그중 가장 도움이 되는 부분을 선택하도록 요구한다. 행동과 선택한 단계를 제시하면 두 의무를 모두 충족하며, 이미 충분한 깊이도 형성된다.'),
    ('prompt-routine-1111', '학습자는 시험 준비를 위해 보통 하는 행동을 설명하고 그 일과가 어떻게 잘 작동하는지 설명해야 한다. 따라서 행동과 유익한 결과가 필수이며, 이 내용만으로 충분하다.'),
    ('prompt-routine-1112', '문구는 늦은 점심 식사 후 보통 무엇을 하는지와 그 이유를 직접 묻는다. 따라서 행동과 이유가 모두 필요하며, 이 중급 과제에는 이 두 내용만으로 충분하다.'),
    ('prompt-routine-1113', '질문은 방을 청소하는 일과와 그중 가장 도움이 되는 부분을 묻는다. 따라서 습관적인 행동과 도움이 되는 단계의 선택이 직접적으로 필요하며, 추가 항목은 필수가 아니다.'),
    ('prompt-routine-1114', '학습자는 금요일 밤 집에서 보통 무엇을 하는지와 그 일과가 잘 작동하는 이유를 말해야 한다. 따라서 행동과 그 긍정적인 효과가 필요하며, 이 정도로 충분한 깊이가 확보된다.'),
    ('prompt-routine-1115', '질문은 가족 나들이 전에 보통 하는 준비와 그 행동의 이유를 묻고 있으므로, 명시된 두 가지 의무만으로도 충분하다.'),
    ('prompt-routine-1116', '답변은 주말 저녁 활동을 설명하고 그 일과에서 가장 도움이 되는 부분을 선택해야 하므로, 이 두 가지 필수 요소만으로도 최소한의 답변을 피할 수 있다.'),
    ('prompt-routine-1117', '학습자는 너무 일찍 도착했을 때 무엇을 하는지와 그 일과가 왜 잘 작동하는지를 답해야 하므로, 습관적인 행동과 그 유익한 결과가 직접적으로 필요하며 그것만으로 충분하다.'),
    ('prompt-routine-1118', '질문은 쇼핑 후에 보통 하는 행동과 그 이유를 직접 요구하므로, 행동과 이유를 답하면 두 절을 모두 충족하며 필수로 추가할 내용은 없다.'),
    ('prompt-routine-1119', '질문은 학교에 가기 전에 무엇을 하는지와 그중 어떤 부분이 가장 도움이 되는지를 묻고 있으므로, 습관적인 행동과 도움이 되는 단계의 선택이 모두 필요하며 그 내용만으로도 충분히 구체적이다.'),
    ('prompt-routine-1120', '학습자는 혼자 지하철을 탈 때 보통 하는 활동을 설명하고 그 일과가 왜 잘 작동하는지 밝혀야 하므로, 행동과 도움이 되는 효과가 필수이며 그것만으로 충분하다.'),
    ('prompt-routine-1121', '질문은 집안일 후에 보통 무엇을 하는지와 그 이유를 묻고 있으므로, 습관적인 행동과 그 이유가 과제를 직접 충족하며 추가적인 깊이는 필요하지 않다.'),
    ('prompt-routine-1122', '질문은 비 오는 아침에 하는 실내 활동과 그 일과에서 가장 도움이 되는 부분을 요구하므로, 이 두 가지 명시적 요소만으로도 중급 수준에 충분한 깊이를 제공한다.'),
    ('prompt-routine-1123', '질문은 부업을 시작하기 전에 하는 일과 그 일이 왜 잘 작동하는지를 묻고 있으므로, 준비 행동과 그 유익한 결과가 필수이며 이미 충분하다.'),
    ('prompt-routine-1124', '학습자는 공항에서 기다리는 동안 보통 무엇을 하는지 말하고 그 이유를 설명해야 하므로, 활동과 이유가 두 절에 대한 충분한 답변이 된다.'),
    ('prompt-routine-1125', '답변은 짧게 낮잠을 잔 후 보통 일어나는 일을 설명하고 가장 도움이 되는 부분을 선택해야 하므로, 행동과 선택이라는 요구 사항만으로도 충분한 깊이를 제공한다.'),
    ('prompt-routine-1126', '질문은 캠퍼스에서 쉬는 시간에 보통 하는 활동과 그 일과가 왜 잘 작동하는지를 묻고 있으므로, 행동과 그 도움이 되는 결과가 필요하며 추가적인 필수 뒷받침은 없다.'),
    ('prompt-routine-1127', '질문은 동영상을 녹화하기 전에 보통 하는 준비와 그 이유를 직접 요구하므로, 이 두 절만으로 완전한 중급 수준의 답변이 된다.'),
    ('prompt-routine-12', '학습자는 일요일 오후에 보통 하는 활동을 밝혀야 하며, 중급 답변이 단순한 행동 하나에 그치지 않도록 추가 행동이나 맥락 정보 하나가 필요하다.'),
    ('prompt-routine-13', '일요일 오후의 일과를 설명하려면 습관적인 행동이 필요하고, 두 번째 단계나 구체적인 시간 또는 그 밖의 독립적인 맥락이 있어야 발전된 일과 설명이 된다.'),
    ('prompt-routine-14', '질문은 일요일 오후에 자주 하는 활동을 묻고 있으므로, 한 절짜리 답변을 피하려면 추가 활동, 장소, 시간 또는 설명 중 하나가 적절하다.'),
    ('prompt-routine-15', '일요일 오후를 보통 어떻게 보내는지는 습관적인 행동을 직접 요구하며, 유용한 최소 깊이를 제공하려면 추가 단계나 맥락 정보 하나가 필요하다.'),
    ('prompt-routine-16', '질문은 집에서 여가 시간을 보통 어떻게 보내는지를 묻고 있으므로 활동이 필요하며, 입문 수준의 답변이 단순한 명칭에 그치지 않도록 추가 행동이나 구체적인 뒷받침 하나가 필요하다.'),
    ('prompt-routine-17', '학습자는 집에서 여가 시간에 보통 무엇을 하는지 말해야 하며, 중급 답변에 충분한 깊이를 주려면 추가 활동, 시간 정보 또는 설명 중 하나가 필요하다.'),
    ('prompt-routine-18', '집에서 보내는 여가 일과에는 적어도 하나의 습관적인 행동이 있어야 하며, 요청된 설명이 최소한의 답변을 넘어서려면 두 번째 행동이나 독립적인 정보가 필요하다.'),
    ('prompt-routine-19', '질문은 집에서 여가 시간에 자주 하는 활동을 묻고 있으므로, 충분히 발전된 답변을 만들려면 별도의 행동, 시간 정보 또는 이유 중 하나가 필요하다.'),
    ('prompt-routine-20', '질문은 집에서 여가 시간을 보통 어떻게 보내는지를 묻고 있으므로 습관적인 행동이 필요하다. 범위가 넓고 난이도가 A이므로, 단순한 활동 하나를 넘어서는 독립적인 정보 하나가 필요하다.'),
    ('prompt-routine-2001', '질문은 아침 식사 전에 학습자가 보통 하는 행동을 묻고 있으며, 시간이 한정된 이 초급 질문에는 그 한 가지 행동만으로도 충분히 답할 수 있다.'),
    ('prompt-routine-2002', '학습자는 전날 밤에 무엇을 준비하는지 말해야 하며, 아침이 더 수월해진다는 것은 이미 제시된 목적이므로 준비 행동만으로도 간단한 질문을 충족한다.'),
    ('prompt-routine-2003', '질문은 아침에 하는 작은 준비 습관 하나를 직접 요구하므로, 난이도 I에서는 습관적인 행동만으로 충분하며 그 이점은 선택적으로 추가할 수 있다.'),
    ('prompt-routine-2004', '질문은 더 빨리 준비하기 위해 사용하는 행동을 묻고 있으며, 원하는 속도 향상 결과는 별도로 요구된 것이 아니라 질문에 이미 제시되어 있다.'),
    ('prompt-routine-2005', '아침에 서두르는 상황은 이미 제시된 어려움이며, 학습자는 침착함을 유지하기 위해 사용하는 대응을 말해야 하므로, 명확한 해결책 하나면 이 초급 질문에 충분하다.'),
    ('prompt-routine-2006', '명시된 두 가지 의무는 아침을 위해 미리 무엇을 준비하는지와 왜 준비하는지이므로, 행동과 이유만으로도 충분한 깊이를 제공한다.'),
    ('prompt-routine-2007', '질문은 아침 준비 중 보통 어떤 감정을 느끼는지와 그 이유를 명시적으로 묻고 있으므로, 이 두 필수 요소만으로 과제를 완성할 수 있다.'),
    ('prompt-routine-2008', '질문은 아침 일과에서 개선하고 싶은 한 가지를 묻고 있으므로, 방법을 요구하지 않고도 구체적인 목표만으로 충분하다.'),
    ('prompt-routine-2009', '질문은 아침 일과 중 어떤 부분이 학습자가 준비되었다고 느끼는 데 도움이 되는지를 묻고 있으므로, 관련 일과 행동이 필요하며 그 효과나 설명은 선택 사항이다.'),
    ('prompt-routine-2010', '학습자는 최근에 성공적으로 보낸 아침 일과의 사례를 제시해야 하며, 단순히 기억을 언급하는 데 그치지 않고 그 기억을 설명하려면 사건의 세부 정보, 행동 또는 결과 중 하나도 필요하다.'),
    ('prompt-routine-2011', '질문은 아침에 하는 행동 한 가지와 그 행동이 학습자가 준비되었다고 느끼는 데 도움이 되는 이유를 각각 요청하므로, 행동과 이유만으로도 초급자에게 완전한 답변이 된다.'),
    ('prompt-routine-2012', '학습자는 평소 아침 준비에서 가장 먼저 하는 행동을 밝히고 그것이 먼저인 이유를 설명해야 하므로, 명시된 두 절이 모두 필요하며 충분하다.'),
    ('prompt-routine-2013', '문항은 학습자가 준비되었다고 느끼기 위해 아침 일과의 마지막에 무엇을 하는지 묻고 있으므로, 마지막 행동만으로도 좁은 과제를 직접 충족한다.'),
    ('prompt-routine-2014', '학습자는 아침 준비 중 피하는 행동과 그 이유를 말해야 하므로, 행동과 이유가 필요한 두 단위이다.'),
    ('prompt-routine-2015', '아침 일과가 계획대로 진행되지 않는 상황이 문제로 제시되므로, 학습자는 평소의 기준을 다시 말하지 않고 달라진 대응만 설명하면 된다.'),
    ('prompt-routine-2016', '질문은 장소를 옮기기 전에 무엇을 확인하는지 직접 묻고 있으므로, 구체적인 확인 행동 하나면 충분히 답할 수 있다.'),
    ('prompt-routine-2017', '요청된 내용은 장소 사이를 이동할 때 사용하는 작은 습관 하나이므로, 행동은 필수이고 그 이점이나 설명은 선택 사항이다.'),
    ('prompt-routine-2018', '버스에 앉을 자리가 없는 조건이 주어졌으므로, 학습자는 그 특정 상황에서 평소 취하는 행동만 말하면 된다.'),
    ('prompt-routine-2019', '문항은 장소 사이의 이동을 더 쉽게 만드는 행동을 묻고 있으며, 의도된 편안함이 이미 제시되어 있으므로 추가로 반드시 필요한 내용은 없다.'),
    ('prompt-routine-2020', '이동 중 서두르게 되는 상황이 문제로 주어지고 질문은 마음을 진정시키는 대응을 묻고 있으므로, 해결 방법 하나면 초급 과제가 완성된다.'),
    ('prompt-routine-2021', '통근 전에 무엇을 준비하는지와 그 이유를 직접 묻고 있으므로, 준비 행동과 그 이유가 모두 필요하다.'),
    ('prompt-routine-2022', '학습자는 장소 사이를 이동할 때 평소 어떤 기분인지 설명하고 그 원인을 말해야 하므로, 명시된 두 항목만으로 충분하다.'),
    ('prompt-routine-2023', '버스가 늦는 상황이 문제로 제시되고 학습자에게 평소의 대응 방식을 묻고 있으므로, 구체적인 해결 방법 하나면 충분한 답변이 된다.'),
    ('prompt-routine-2024', '질문은 통근에서 개선하고 싶은 점 하나를 요청하므로, 개선 목표는 필수이고 실행 계획은 선택 사항이다.'),
    ('prompt-routine-2025', '학습자는 통근을 더 쉽거나 편안하게 만드는 구체적인 요소를 밝혀야 하므로, 그 특징을 말하는 것만으로도 간단한 질문에 답할 수 있다.'),
    ('prompt-routine-2026', '문항은 최근에 순조로웠던 통근 경험을 묻고 있으며, 제시한 사례를 의미 있는 설명으로 만들려면 이를 뒷받침하는 행동, 결과 또는 구체적인 세부 내용 하나가 필요하다.'),
    ('prompt-routine-2027', '과제는 짧은 이동 중 학습자가 평소 하는 활동으로 범위가 좁혀져 있으므로, 난이도 I에서는 행동 하나면 충분하다.'),
    ('prompt-routine-2028', '학습자는 어딘가에 갈 때 무엇을 가져가는지 밝히고 그것이 도움이 되는 이점을 말해야 하므로, 이 두 명시적 단위가 충분한 깊이를 제공한다.'),
    ('prompt-routine-2029', '질문은 장소를 바꿀 때 평소 가장 먼저 하는 행동과 그 행동을 먼저 하는 이유를 묻고 있으므로, 두 절이 모두 필요하다.'),
    ('prompt-routine-2030', '통근이 거의 끝날 무렵이라는 조건이 구체적으로 제시되므로, 학습자는 그때 평소 취하는 행동만 말하면 된다.'),
    ('prompt-routine-2031', '5분이라는 시간이 일과의 범위를 명확히 제한하므로, 평소 짧은 휴식에서 하는 행동을 말하면 완전한 초급자 답변이 된다.'),
    ('prompt-routine-2032', '학습자는 짧은 휴식을 편안하게 만들기 위해 시작할 때 무엇을 하는지 질문받고 있으므로, 시작 행동이 질문에 직접 답한다.'),
    ('prompt-routine-2033', '문항은 짧은 휴식 중 도움이 되는 작은 습관 하나를 요구하므로, 습관으로 하는 행동은 필수이고 그 이점은 선택적으로 덧붙일 수 있다.'),
    ('prompt-routine-2034', '과제는 짧은 휴식 중 빠르게 쉬기 위해 하는 행동을 묻고 있으며, 원하는 결과는 질문에 이미 제시되어 있다.'),
    ('prompt-routine-2035', '신선한 공기를 마시러 밖에 나가는 구체적인 상황이 주어졌으므로, 그곳에서 평소 하는 행동만 필수 내용이다.'),
    ('prompt-routine-2036', '휴식 중에도 서두르는 느낌이 드는 상황이 문제로 제시되고, 학습자는 속도를 늦추기 위해 사용하는 대응을 말해야 하므로, 해결 방법 하나면 충분하다.'),
    ('prompt-routine-2037', '질문은 짧은 휴식을 위해 미리 무엇을 준비하는지와 그 이유를 명시적으로 요청하므로, 행동과 이유가 모두 필요하다.'),
    ('prompt-routine-2038', '학습자는 빠르게 재정비해야 할 때 평소 취하는 행동을 묻고 있으므로, 그 한 가지 행동만으로도 초점이 분명한 초급 질문에 답할 수 있다.'),
    ('prompt-routine-2039', '문항은 짧은 휴식 중 학습자가 어떻게 느끼는지와 그 이유를 각각 묻고 있으므로, 기분과 이유가 필수이며 충분하다.'),
    ('prompt-routine-2040', '질문은 밖에서 짧게 걸은 직후 평소 무엇을 하는지에 초점을 맞추므로, 그다음 행동 하나면 충분한 답변이 된다.'),
    ('prompt-routine-2041', '학습자는 짧은 휴식에서 개선하고 싶은 점 하나를 말해야 하며, 계획은 직접 요청되지 않았으므로 목표만으로 충분하다.'),
    ('prompt-routine-2042', '잠시 조용히 앉아 있는 조건이 주어졌고, 문항은 그동안 학습자가 평소 하는 행동만 묻고 있다.'),
    ('prompt-routine-2043', '요청된 내용은 상쾌함을 느끼기 위해 잠깐 쉬는 시간에 하는 행동이며, 상쾌해지는 결과는 질문의 문구에 이미 제시되어 있다.'),
    ('prompt-routine-2044', '오후의 졸림이 제시된 어려움이며, 학습자는 이에 대한 평소의 대처를 말해야 하므로 구체적인 해결 방법이 필요하다.'),
    ('prompt-routine-2045', '최근에 잘 보낸 잠깐의 휴식 사례와 함께, 그 시간이 잘된 이유를 실제로 말할 수 있도록 독립적인 행동, 결과 또는 세부 내용 하나를 제시해야 한다.'),
    ('prompt-routine-2046', '점심이나 간식 전에 무엇을 준비하는지 말해야 하며, 식사를 더 쉽게 만드는 것은 이미 제시된 목적이므로 추가 설명은 필요하지 않다.'),
    ('prompt-routine-2047', '혼자 점심을 먹는다는 조건이 명확하게 제시되어 있으며, 학습자는 그 상황에서 평소에 하는 활동만 말하면 된다.'),
    ('prompt-routine-2048', '친구와 점심을 먹을 때 평소에 무엇을 하는지 묻는 질문이므로, 사회적 행동이나 식사 중 행동 하나로 충분히 답할 수 있다.'),
    ('prompt-routine-2049', '도움이 되는 작은 점심 또는 간식 습관 하나를 직접 말해야 하므로, 습관적 행동만이 필수 답변 단위이다.'),
    ('prompt-routine-2050', '어떤 간단한 점심이나 간식을 선택하는지와 그 이유를 묻고 있으므로, 음식 선택과 선택 이유가 모두 명시적으로 필요하다.'),
    ('prompt-routine-2051', '서두르는 점심 또는 간식 시간이 주어진 문제이며, 학습자는 이를 다루기 위해 사용하는 마음을 진정시키는 대처를 제시해야 한다.'),
    ('prompt-routine-2052', '점심이나 간식 시간을 위해 무엇을 미리 준비하는지와 그 이유를 직접 묻고 있으므로, 준비 내용과 이유가 모두 필수이다.'),
    ('prompt-routine-2053', '점심 후 시간이 조금 있다는 조건이 과제를 구체화하므로, 평소에 하는 식후 행동 하나면 충분하다.'),
    ('prompt-routine-2054', '점심이나 간식 중 평소에 어떤 기분을 느끼는지와 그 이유를 말해야 하므로, 추가적인 깊이 없이 명시된 두 부분을 모두 충족해야 한다.'),
    ('prompt-routine-2055', '점심이나 간식 시간에 바라는 변화 하나를 말하는 과제이므로, 초급 학습자에게는 구체적인 개선 목표만으로 충분하다.'),
    ('prompt-routine-2056', '점심 후 작은 간식을 먹는 상황이 제시되어 있으며, 질문은 그때 학습자가 평소에 함께 하는 행동만 요구한다.'),
    ('prompt-routine-2057', '점심이나 간식 시간이 편안하게 느껴지도록 하는 요인을 밝혀야 하며, 그 구체적인 요인이 초급 수준의 직접적인 질문에 답한다.'),
    ('prompt-routine-2058', '최근에 잘 보낸 점심이나 간식 시간의 사례와 함께, 단순히 사례를 이름 붙이는 데 그치지 않고 그 일을 설명할 수 있는 독립적인 행동, 결과 또는 세부 내용 하나를 제시해야 한다.'),
    ('prompt-routine-2059', '어떤 점심이나 간식을 선택하는지 말하고 그것을 좋아하는 이유를 설명해야 하므로, 선택과 선호 이유가 모두 필요하다.'),
    ('prompt-routine-2060', '오후에 가벼운 간식을 먹고 싶을 때 평소에 무엇을 하는지 묻고 있으므로, 행동이 필수이며 구체적인 음식은 추가할 수 있다.'),
    ('prompt-routine-2061', '집에 도착했을 때 빠르게 안정을 찾기 위해 하는 행동을 말해야 하며, 원하는 결과는 이미 제시되어 있다.'),
    ('prompt-routine-2062', '집에 돌아온 뒤 도움이 되는 작은 습관 하나를 말하는 것이 직접적인 요구이므로, 습관적 행동만으로 이 간단한 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2063', '집에 가는 길의 피곤함이 제시된 어려움이며, 학습자는 그 상황에서 평소에 사용하는 대처를 말해야 한다.'),
    ('prompt-routine-2064', '집에 돌아온 뒤 처음 하는 행동과 그 이유를 묻고 있으므로, 행동과 이유가 모두 필요하다.'),
    ('prompt-routine-2065', '집에 도착한 뒤 서두르게 되는 것이 주어진 어려움이며, 이를 관리하기 위해 처음 사용하는 대처를 묻고 있으므로 해결 방법 하나면 충분하다.'),
    ('prompt-routine-2066', '집에 돌아온 뒤의 일과를 위해 무엇을 미리 준비하는지와 그 이유를 말해야 하므로, 요청된 두 부분이 모두 필요하다.'),
    ('prompt-routine-2067', '집에서 입을 옷으로 갈아입는 것이 앞선 단계로 제시되어 있으며, 학습자는 그다음에 평소에 하는 행동만 말하면 된다.'),
    ('prompt-routine-2068', '집에 돌아왔을 때 평소에 어떤 기분을 느끼는지와 그 이유를 직접 묻고 있으므로, 이 두 단위로 답변이 완성된다.'),
    ('prompt-routine-2069', '집에 돌아온 뒤의 일과에서 바라는 개선점 하나를 찾아야 하므로, 목표는 필요하지만 계획은 필요하지 않다.'),
    ('prompt-routine-2070', '하루가 바빠서 그 일을 뒤로하고 싶다는 것이 제시된 어려움이며, 질문은 평소에 긴장을 풀고 회복하기 위해 하는 대처를 묻는다.'),
    ('prompt-routine-2071', '집에 돌아온 뒤 어떤 행동이 휴식 상태로 전환하는 데 도움이 되는지 묻고 있으며, 그 의도된 결과는 이미 제시되어 있다.'),
    ('prompt-routine-2072', '최근에 잘 보낸 귀가 후 일과의 사례와 함께, 그 기억을 의미 있게 묘사할 수 있도록 뒷받침하는 행동, 결과 또는 세부 내용 하나를 제시해야 한다.'),
    ('prompt-routine-2073', '일이나 수업 후 조용히 잠시 있을 시간이 필요하다는 구체적인 조건이 제시되어 있으며, 학습자가 평소에 하는 행동만 직접적으로 요구된다.'),
    ('prompt-routine-2074', '집에서 먼저 무엇을 하는지와 그 이유를 명시적으로 묻고 있으므로, 첫 행동과 그 설명이 모두 필요하다.'),
    ('prompt-routine-2075', '질문은 집에 돌아왔을 때 보통 가장 먼저 하는 행동과 그 순서인 이유를 요구하므로, 이 두 가지 명시적 요소로 충분하다.'),
    ('prompt-routine-2076', '학습자는 간단한 집안일이나 주방 일을 하기 전에 무엇을 준비하는지와 그 이유를 말해야 하므로, 준비와 이유가 필수이다.'),
    ('prompt-routine-2077', '직접적인 요구 사항은 집안일이나 주방 일을 돕는 작은 습관 하나이므로, 습관적 행동만으로 I 난이도에서 충분하다.'),
    ('prompt-routine-2078', '탁자 닦기가 주어진 과업이며, 학습자는 그 일을 하면서 보통 사용하는 행동이나 방법을 말하면 된다.'),
    ('prompt-routine-2079', '학습자는 집에서 하는 첫 번째 간단한 집안일을 밝히고 왜 먼저 하는지 설명해야 하므로, 행동과 이유가 모두 필요하다.'),
    ('prompt-routine-2080', '서두르는 집안일이나 주방 일이 제시된 문제이며, 학습자는 이를 처리하기 위해 사용하는 진정 방법을 말해야 한다.'),
    ('prompt-routine-2081', '질문은 책상을 정리할 때 학습자가 보통 하는 행동이나 방법을 묻고 있으며, 구체적인 행동 하나로 제한된 과업이 완성된다.'),
    ('prompt-routine-2082', '문구는 집안일이나 주방 일을 위해 미리 무엇을 준비하는지와 그 이유를 각각 묻고 있으므로, 두 가지 요구 요소가 모두 필요하다.'),
    ('prompt-routine-2083', '학습자는 간단한 집안일이나 주방 일을 할 때 보통 어떤 기분인지 설명하고 그 원인을 말해야 하므로, 두 가지 필수 요소를 통해 충분한 깊이가 확보된다.'),
    ('prompt-routine-2084', '식료품을 냉장고에 넣는 구체적인 상황이 제시되어 있으며, 학습자는 그때 보통 사용하는 행동이나 방법만 말하면 된다.'),
    ('prompt-routine-2085', '질문은 집안일이나 주방 일과 관련해 바라는 개선점 하나를 요구하므로, 개선 목표만으로 직접 답할 수 있다.'),
    ('prompt-routine-2086', '학습자는 가장 쉽게 느껴지는 집안일이나 주방 일을 선택하고 그 판단의 이유를 설명해야 하므로, 선택과 이유가 필요하다.'),
    ('prompt-routine-2087', '질문은 최근에 성공적으로 해낸 집안일이나 주방 일의 사례와 함께, 그 일을 실제로 설명할 수 있도록 행동, 결과 또는 구체적인 세부 내용 하나를 요구한다.'),
    ('prompt-routine-2088', '집에서 빠르게 식사해야 하는 상황이 구체적으로 제시되어 있으며, 학습자가 보통 취하는 대응 행동만으로 답할 수 있다.'),
    ('prompt-routine-2089', '학습자는 집안일이나 주방 일에 어떤 도구를 사용하는지와 그 이유를 말해야 하므로, 도구의 선택과 이유가 모두 명시적인 필수 요소이다.'),
    ('prompt-routine-2090', '학습자는 보통 가장 먼저 하는 집안일이나 주방 행동을 말하고 왜 먼저 하는지 설명해야 하므로, 이 두 요소로 질문을 충분히 다룬다.'),
    ('prompt-routine-2091', '저녁에 소파에 앉아 있는 상황이 주어져 있으며, 질문은 그때 학습자가 보통 하는 활동만 묻는다.'),
    ('prompt-routine-2092', '학습자는 저녁 휴식을 더 편안하게 느끼도록 돕는 요소를 밝히고 그것이 도움이 되는 이유를 설명해야 하므로, 세부 내용과 이유가 필요하다.'),
    ('prompt-routine-2093', '질문은 저녁 휴식을 위한 작은 습관 하나를 직접 요구하므로, 습관적 행동만으로 충분하며 그 효과는 선택 사항으로 남을 수 있다.'),
    ('prompt-routine-2094', '조용히 쉬고 싶은 상황이 제한된 일상 맥락을 형성하므로, 학습자는 보통 사용하는 행동만 말하면 된다.'),
    ('prompt-routine-2095', '질문은 학습자가 저녁에 쉬기 위해 무엇을 하는지와 그 이유를 각각 묻고 있으므로, 행동과 이유가 필수이며 이 두 요소로 충분하다.'),
    ('prompt-routine-2096', '서두르는 저녁이 제시된 문제이며, 학습자는 긴장을 풀기 위해 사용하는 대응을 말해야 하므로 해결 방법이 필수 내용이다.'),
    ('prompt-routine-2097', '밤에 잠깐 독서하는 구체적인 조건이 제시되어 있으며, 질문은 그 시간에 보통 하는 행동만 묻는다.'),
    ('prompt-routine-2098', '학습자는 저녁 휴식을 위해 미리 준비하는 것을 밝히고 그것을 준비하는 이유를 설명해야 하므로, 명시된 두 절을 모두 다룬다.'),
    ('prompt-routine-2099', '질문은 저녁에 쉴 때 학습자가 보통 어떤 기분인지와 그 이유를 묻고 있으므로, 기분과 이유만으로 완전한 답변이 된다.'),
    ('prompt-routine-21', '넓은 질문은 토요일을 보통 어떻게 시작하는지 묻고 있으므로, 단순한 활동만 말하지 않고 일과를 의미 있게 설명하려면 시간, 세부 내용 또는 이유 중 독립적인 요소 하나가 더 필요하다.'),
    ('prompt-routine-2100', '차분한 저녁을 보내고 싶은 구체적인 상황이 주어져 있으며, 이를 만들기 위해 보통 하는 행동 하나로 초급 질문에 직접 답할 수 있다.'),
    ('prompt-routine-2101', '학습자는 저녁 휴식에 대해 바라는 개선점 하나를 말해야 하므로, 개선 목표가 필수이고 계획은 선택 사항이다.'),
    ('prompt-routine-2102', '질문은 학습자가 보통 사용하는 저녁 휴식 방법과 그 방법이 자신에게 효과적인 이유를 요구하므로, 행동과 이유가 필요하다.'),
    ('prompt-routine-2103', '조용한 집이라는 상황이 주어져 있으며, 학습자는 그때 보통 하는 행동만 제시하면 된다.'),
    ('prompt-routine-2104', '학습자는 최근 저녁 휴식이 잘 이루어진 사례를 밝히고, 그 성공을 설명할 수 있도록 독립적인 행동, 결과 또는 세부 내용 하나를 더해야 한다.'),
    ('prompt-routine-2105', '질문은 저녁에 긴장을 푸는 행동과 그 이유를 직접 묻고 있으므로, 이 두 가지 필수 요소로 충분하다.'),
    ('prompt-routine-2106', '질문은 집에서 보내는 평소 일요일 아침에 대해 폭넓게 묻고 있으므로, 단순한 행동만 말하지 말고 독립적인 세부 내용, 시간 단서 또는 이유가 하나 더 필요하다.'),
    ('prompt-routine-2107', '느긋한 토요일 오후에는 가능한 일과가 다양하므로, 적절한 답변을 위해 평소 하는 행동에 독립적인 뒷받침 세부 내용이 하나 필요하다.'),
    ('prompt-routine-2108', '계획이 없는 주말에 대한 질문은 범위가 넓어 활동 하나만으로는 내용이 부족하므로, 요구된 행동을 별도의 세부 내용, 이유, 느낌 또는 결과 하나로 뒷받침해야 한다.'),
    ('prompt-routine-2109', '학습자는 집에서 편안한 주말을 보내기 위해 무엇을 계획하는지 말하고 이유를 설명해야 하므로, 계획과 이유만으로도 충분한 깊이가 제공된다.'),
    ('prompt-routine-2110', '질문은 집에서 보내는 주말에 도움이 되는 작은 습관 하나를 요구하며, 이 초급 과제에서는 습관의 행동 자체로 충분하다.'),
    ('prompt-routine-2111', '잠옷을 입고 있는 상황이 구체적인 주말 조건을 제공하므로, 학습자는 그때 보통 하는 활동만 말하면 된다.'),
    ('prompt-routine-2112', '학습자는 집에서 하는 주말 활동을 말하고 그 활동을 좋아하는 이유를 설명해야 하므로, 행동과 이유가 명시된 두 조건을 모두 충족한다.'),
    ('prompt-routine-2113', '집에서 보내는 주말에 서두르는 느낌이 든다는 문제가 제시되며, 학습자는 속도를 늦추기 위해 사용하는 방법을 답해야 한다.'),
    ('prompt-routine-2114', '조용한 주말 저녁을 원한다는 좁은 맥락이 제공되므로, 평소 하는 행동 하나만으로 질문에 답하기에 충분하다.'),
    ('prompt-routine-2115', '질문은 집에서 보내는 주말을 위해 무엇을 미리 준비하는지와 그 이유를 묻기 때문에, 준비 행동과 이유가 모두 필요하다.'),
    ('prompt-routine-2116', '학습자는 집에서 보내는 주말에 보통 어떤 느낌을 받는지와 그 이유를 말해야 하므로, 직접 요구된 두 항목으로 과제가 완성된다.'),
    ('prompt-routine-2117', '혼자 주말을 보내는 상황에서도 일과에 대한 질문의 범위는 넓으므로, 요구된 활동 외에 독립적인 세부 내용, 이유, 느낌 또는 결과가 하나 필요하다.'),
    ('prompt-routine-2118', '질문은 집에서 보내는 주말에 바라는 개선점 하나를 묻고 있으므로, 구체적인 목표가 간단한 질문에 직접 부합한다.'),
    ('prompt-routine-2119', '질문은 집에서 보내는 주말에 선호하는 활동과 그 이유를 명시적으로 묻으므로, 이 두 가지 필수 내용만으로 초급 수준에 적절한 깊이가 제공된다.'),
    ('prompt-routine-2120', '질문은 특히 여유로운 주말에 학습자가 보통 무엇을 하는지 묻으므로, 습관적인 행동을 뒷받침할 맥락이나 설명이 하나 필요하다.'),
    ('prompt-routine-2121', '학습자는 휴대전화 사용을 단순하게 하기 위해 하는 행동과 그 행동을 사용하는 이유를 말해야 하므로, 추가적인 깊이 항목은 필요하지 않다.'),
    ('prompt-routine-2122', '이 집중된 난이도 I 질문은 도움이 되는 작은 휴대전화 습관 하나를 요구하므로, 필수 선택 세부 내용 없이 습관의 행동 자체로 충분한 답변이 된다.'),
    ('prompt-routine-2123', '달력 앱을 여는 상황이 좁게 설정되어 있으므로, 평소 하는 앱 사용 행동 하나만으로 이 난이도 I 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2124', '학습자는 자주 사용하는 휴대전화 기능과 그 기능을 사용하는 이유를 밝혀야 하므로, 선택한 기능과 이유만으로 이 간단한 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2125', '질문에 서두르는 휴대전화 사용 상황이 제시되어 있으므로, 집중을 유지하는 구체적인 방법 하나만으로 이 집중된 난이도 I 과제에 충분히 답할 수 있다.'),
    ('prompt-routine-2126', '지도 앱을 확인하는 상황이 구체적으로 한정되어 있으므로, 난이도 I에서는 평소 하는 행동 하나만으로 충분하다.'),
    ('prompt-routine-2127', '학습자는 휴대전화 사용을 위해 무엇을 습관적으로 미리 준비하는지와 그 이유를 설명해야 하므로, 준비 행동과 이유만으로 이 수준에서 충분하다.'),
    ('prompt-routine-2128', '질문은 휴대전화를 사용할 때 학습자가 보통 느끼는 감정과 그 이유를 직접 묻고 있으므로, 완전한 필수 항목 두 가지가 마련되어 있다.'),
    ('prompt-routine-2129', '배터리가 부족하다는 문제가 이미 제시되어 있으므로, 평소의 대응 하나만으로 초급 수준의 완전한 해결책이 된다.'),
    ('prompt-routine-2130', '학습자는 자신의 휴대전화 습관에서 바라는 개선점 하나만 밝히면 되므로, 요구된 목표가 이 간단한 개인 질문에 충분하다.'),
    ('prompt-routine-2131', '질문은 도움이 되는 휴대전화 습관 하나를 직접 묻고 있으므로, 그 습관을 말하는 것만으로 집중된 난이도 I 과제가 충분히 완성된다.'),
    ('prompt-routine-2132', '간단한 메모를 복습하는 상황이 좁게 설정되어 있으므로, 평소 하는 복습 행동 하나만으로 이 난이도 I 질문에 충분하다.'),
    ('prompt-routine-2133', '학습자는 최근의 한 사례를 이야기해야 하므로, 단순히 사례를 밝히는 것 외에 행동, 결과, 느낌, 시간 또는 세부 내용이 하나 필요하다.'),
    ('prompt-routine-2134', '도움이 되는 휴대전화 사용 방법과 그 방법을 사용하는 명시적인 이유가 모두 필요하므로, 추가적인 뒷받침 내용은 선택 사항이다.'),
    ('prompt-routine-2135', '기억하고자 하는 결과가 이미 제시되어 있으므로, 단어를 기억하기 위해 평소 하는 행동 하나만으로 이 집중된 난이도 I 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-22', '질문은 토요일을 시작할 때의 평소 행동을 묻고 있으므로, 상급 초급 수준에서는 여기에 독립적인 시간, 순서, 장소, 이유 또는 결과 세부 내용이 하나 더 따라야 한다.'),
    ('prompt-routine-23', '토요일을 시작하는 일과를 설명하려면 적어도 습관적인 행동 하나가 필요하며, 실제 설명이 되려면 추가 행동이나 맥락 세부 내용이 하나 더 필요하다.'),
    ('prompt-routine-24', '학습자에게 토요일 초반에 보통 무엇을 하는지 묻고 있으므로, 답변이 단순히 한 가지 활동을 말하는 데서 끝나지 않도록 뒷받침하는 세부 내용 하나가 필요하다.'),
    ('prompt-routine-2401', '날씨가 바뀔 때 무엇을 확인하는지 말하고 그 이유를 설명해야 하므로, 확인하는 행동과 이유가 질문의 요구를 충족한다.'),
    ('prompt-routine-2402', '날씨 변화에 대비하는 작은 습관 하나가 요구된 내용의 전부이므로, 이 난이도 1의 집중형 질문에는 추가적인 뒷받침 내용을 요구하지 않아야 한다.'),
    ('prompt-routine-2403', '날씨가 바뀔 때 어떤 준비 행동을 하는지 묻고 그 이유를 명시적으로 요구하므로, 두 필수 절이 충분한 깊이를 제공한다.'),
    ('prompt-routine-2404', '출발 전에 비가 오는 상황이 제시된 문제이므로, 평소의 대응 하나면 이 좁은 범위의 난이도 1 과제를 충분히 해결한다.'),
    ('prompt-routine-2405', '갑작스러운 날씨 변화와 마음을 가라앉히려는 목표가 제시되어 있으므로, 구체적인 진정 방법 하나면 난이도 1에서 충분하다.'),
    ('prompt-routine-2406', '비 오는 날이나 추운 날을 대비해 평소 무엇을 미리 준비하는지와 그 이유를 묻고 있으므로, 준비 행동과 이유가 답변을 완성한다.'),
    ('prompt-routine-2407', '날씨 변화로 인해 보통 어떤 감정을 느끼는지와 그 이유를 직접 묻고 있으므로, 이 두 요소만으로 충분하다.'),
    ('prompt-routine-2408', '비 오는 날이나 추운 날과 관련해 바라는 개선점 하나만 요구하므로, 개인적인 목표를 말하는 것만으로 이 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2409', '특정한 날씨 상황에서 편안함을 높이는 행동 하나를 묻고 있으므로, 다른 필수 세부 내용 없이도 완전한 난이도 1 답변이 된다.'),
    ('prompt-routine-2410', '갑작스러운 날씨 변화가 제시된 문제이고, 평소의 대응 하나면 이 집중형 초급 질문에 충분하다.'),
    ('prompt-routine-2411', '최근 비가 오거나 추웠던 날에 대해 말하려면, 그 상황을 단순히 밝히는 것 외에 독립적인 사건 세부 내용 하나가 필요하다.'),
    ('prompt-routine-2412', '가져간 물건을 말하고 그 이유를 설명해야 한다. 물건은 행동이 아니라 선택한 사물이며, 다음 선택적 뒷받침 내용으로는 시점보다 결과가 더 유용하다.'),
    ('prompt-routine-2413', '날씨 변화에 대한 첫 번째 평소 대응과 그 행동을 하는 이유를 명시적으로 요구하므로, 선택적인 후속 행동이나 결과 세부 내용은 필수가 아니다.'),
    ('prompt-routine-2414', '제시된 안정된 느낌을 만들어 내는 하루의 마지막 행동 하나가 이 좁은 범위의 난이도 1 질문에 충분히 답한다.'),
    ('prompt-routine-2415', '날씨가 바뀔 때 무엇을 피하는지와 그 이유를 밝혀야 하므로, 피하는 행동과 그 이유가 모두 포함된다.'),
    ('prompt-routine-2416', '빠른 심부름을 하기 전에 평소 어떤 준비 행동을 하는지 말하고, 그 행동을 하는 이유를 별도로 설명해야 하므로 질문에 충분히 답하게 된다.'),
    ('prompt-routine-2417', '도움이 되는 작은 심부름 습관 하나를 묻고 있으므로, 그 행동만으로 난이도 1에서 충분하다.'),
    ('prompt-routine-2418', '더 빠른 심부름이라는 결과가 질문에 제시되어 있으므로, 그 결과를 이루기 위해 사용하는 행동 하나면 완전한 초급 답변이 된다.'),
    ('prompt-routine-2419', '서두르는 심부름 상황이 이미 제시되어 있으므로, 그 상황에 대한 첫 번째 대응 하나면 이 집중형 난이도 1 해결 방법 질문에 충분하다.'),
    ('prompt-routine-2420', '심부름이나 가게에 들르기 위해 평소 무엇을 미리 준비하는지와 그 이유를 묻고 있으므로, 미래 계획이 아니라 행동과 그 이유가 필요하다.'),
    ('prompt-routine-2421', '한두 가지만 필요하다는 조건이 좁게 제시되어 있으므로, 평소의 행동 하나면 이 난이도 1 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2422', '빠른 심부름을 할 때 보통 어떤 감정을 느끼는지와 그 이유를 직접 요구하므로, 두 요소가 충분한 깊이를 제공한다.'),
    ('prompt-routine-2423', '빠른 심부름이나 가게에 들르는 일을 개선하고 싶은 점 하나를 묻고 있으므로, 목표를 분명히 말하는 것만으로 간단한 요구를 충족한다.'),
    ('prompt-routine-2424', '무엇이 도움이 되는지 묻는 표현이므로, 행동이 아니라 도움 도구나 목록 또는 다른 특징일 수 있으며, 그러한 구체적인 요소는 DETAIL에 해당한다.'),
    ('prompt-routine-2425', '최근 심부름에 대해 말하라는 지시는 한 가지 예를 밝히는 것 외에 독립적인 행동, 결과, 시간, 감정 또는 세부 내용 하나를 요구한다.'),
    ('prompt-routine-2426', '빠른 심부름 전에 평소 어떤 준비 행동을 하는지와 그 이유를 묻고 있으므로, 더 넓은 계획 구조는 필요하지 않다.'),
    ('prompt-routine-2427', '집에 가는 길에 가게에 들르는 구체적인 상황이 제시되어 있으므로, 평소의 행동 하나면 난이도 1 과제를 완성한다.'),
    ('prompt-routine-2428', '심부름이나 가게에 들를 때 하는 첫 번째 평소 행동과 그 이유를 명시적으로 요구하므로, 추가적인 순서 세부 내용은 선택 사항이다.'),
    ('prompt-routine-2429', '심부름 후의 좁게 정해진 전환 상황에서 하는 행동 하나를 묻고 있으므로, 난이도 1에서는 추가적인 뒷받침 내용을 선택 사항으로 남겨야 한다.'),
    ('prompt-routine-2430', '짧은 쇼핑 목록을 만드는 상황이 집중적으로 제시되어 있으므로, 평소 목록을 만드는 행동 하나면 초급 답변에 충분하다.'),
    ('prompt-routine-2431', '카페나 빵집에서 주문할 것을 어떻게 결정하는지와 그 방법을 사용하는 이유를 묻고 있으므로, 과정과 이유가 모두 필수이다.'),
    ('prompt-routine-2432', '도움이 되는 작은 카페나 빵집 습관 하나가 요청된 내용의 전부이므로, 이 난이도 I 항목에서 다른 세부 사항을 요구해서는 안 된다.'),
    ('prompt-routine-2433', '학습자는 첫 번째 카페나 빵집 행동을 말하고 그것이 먼저인 이유를 설명해야 하므로, 다른 필수 세부 사항 없이도 충분한 깊이를 제공한다.'),
    ('prompt-routine-2434', '붐비는 장소가 제시된 문제이며, 첫 번째 대응 하나면 이 초점이 분명한 난이도 I 문제 해결 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2435', '학습자는 카페나 빵집 방문을 위해 평소 미리 준비하는 것을 설명하고 그 이유를 말해야 하므로, 미래 계획이 아닌 행동과 이유가 필요하다.'),
    ('prompt-routine-2436', '오후에 빵집에 들르는 상황이 구체적으로 제시되어 있으므로, 평소 행동 하나면 난이도 I 답변으로 충분하다.'),
    ('prompt-routine-2437', '학습자는 카페나 빵집 방문 중 평소 느끼는 감정을 설명하고 그 이유를 말해야 하므로, 두 가지 직접적인 요구만으로 충분한 깊이를 제공한다.'),
    ('prompt-routine-2438', '질문은 카페나 빵집 방문에서 바라는 개선점 하나를 요구하므로, 개선 목표 자체로 이 간단한 개인 과제에 충분히 답할 수 있다.'),
    ('prompt-routine-2439', '학습자는 카페나 빵집 방문에서 좋아하는 점을 하나 밝히고 그 이유를 설명해야 하므로, 선호하는 점과 이유만으로 충분하다.'),
    ('prompt-routine-2440', '최근 카페나 빵집 방문에 대해 말하려면 단순히 방문 시기를 언급하는 것 외에 독립적인 설명 단위 하나가 필요하다.'),
    ('prompt-routine-2441', '평소 카페나 빵집에서 주문하는 것은 선택한 항목이며, 질문은 학습자가 그것을 좋아하는 이유를 명시적으로 묻고 있으므로 이 두 단위로 질문에 완전히 답할 수 있다.'),
    ('prompt-routine-2442', '카페나 빵집에 들어갔을 때 평소 가장 먼저 하는 행동과 그 이유가 모두 명시적인 요구 사항이므로, 이후 행동이나 결과는 선택 사항이다.'),
    ('prompt-routine-2443', '퇴근 후나 수업 후 빵집에 들르는 상황이 구체적으로 한정되어 있으므로, 평소 행동 하나면 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2444', '장소를 떠나기 전에 하는 행동 하나면 이 범위가 좁은 난이도 I 질문에 직접적이고 충분히 답할 수 있다.'),
    ('prompt-routine-2445', '학습자는 카페나 빵집 방문 중 피하는 것을 하나 밝히고 그 이유를 설명해야 하므로, 요청된 두 절을 모두 충족한다.'),
    ('prompt-routine-2446', '질문은 산책이나 가벼운 운동 전에 정기적으로 준비하는 것과 그 이유를 묻고 있으므로, 필요한 구조는 일상적인 행동과 그 이유이다.'),
    ('prompt-routine-2447', '학습자에게 도움이 되는 작은 산책이나 운동 습관 하나를 요구하므로, 난이도 I에서는 그것만으로 충분하다.'),
    ('prompt-routine-2448', '학습자는 산책이나 가벼운 운동 전에 평소 준비하는 행동을 말하고 그 행동을 하는 이유를 설명해야 하므로, 이 두 가지 요구만으로 충분하다.'),
    ('prompt-routine-2449', '서두르는 느낌이 문제로 제시되어 있으며, 속도를 늦추는 방법 하나면 이 난이도 I 과제의 완전한 해결책이 된다.'),
    ('prompt-routine-2450', '질문은 산책이나 가벼운 운동을 위해 평소 미리 준비하는 것과 그 이유를 묻고 있으므로, 미래의 의도가 아닌 행동과 이유가 필요하다.'),
    ('prompt-routine-2451', '앉아 있은 후 스트레칭을 하고 싶은 상황이 초점이 분명하게 제시되어 있으므로, 평소 스트레칭 행동 하나면 난이도 I 질문에 완전히 답할 수 있다.'),
    ('prompt-routine-2452', '학습자는 산책이나 가벼운 운동 중 평소 느끼는 감정과 그 원인을 설명해야 하므로, 완전한 필수 요소 두 가지를 제공한다.'),
    ('prompt-routine-2453', '산책이나 가벼운 운동에서 바라는 개선점 하나만 요구되므로, 초급 수준의 답변에는 구체적인 목표 하나면 충분하다.'),
    ('prompt-routine-2454', '학습자는 제시된 기분 좋은 효과를 주는 산책이나 가벼운 운동의 부분을 밝히기만 하면 되므로, 이는 선호가 아닌 초점이 분명한 사실 설명이다.'),
    ('prompt-routine-2455', '최근 산책이나 운동 경험에 대해 말하려면 사례를 밝히는 것 외에 독립적인 설명 세부 사항 하나가 필요하다.'),
    ('prompt-routine-2456', '공원에서 짧게 걷는 상황이 구체적으로 한정되어 있으므로, 평소 행동 하나면 이 난이도 I 답변에 충분하다.'),
    ('prompt-routine-2457', '학습자는 산책을 위해 가져가거나 착용하는 것을 하나 밝히고 그것을 선택하는 이유를 설명해야 하므로, 물건의 선택과 이유만으로 답변이 완성된다.'),
    ('prompt-routine-2458', '평소 산책이나 운동에서 가장 먼저 하는 행동과 그것이 먼저인 이유가 직접적으로 요구되므로, 추가적인 순서나 효과에 관한 세부 사항은 선택 사항이다.'),
    ('prompt-routine-2459', '10분이라는 제한으로 과제가 구체화되어 있으므로, 운동 행동 하나면 초급 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2460', '질문은 운동 후 정리 운동 행동 하나를 직접 요구하므로, 난이도 I에서는 그것만으로 충분하다.'),
    ('prompt-routine-2461', '더 쉬운 밤의 일상이 제시된 목적이며, 잠자리에 들기 전 행동 하나면 이 초점이 분명한 난이도 I 과제에 완전히 답할 수 있다.'),
    ('prompt-routine-2462', '도움이 되는 작은 취침 습관 하나가 난이도 I 질문이 정확히 요구하는 내용이므로, 다른 세부 사항을 필수로 요구해서는 안 된다.'),
    ('prompt-routine-2463', '질문은 취침 준비를 더 쉽게 만드는 행동과 그에 대한 명시적인 이유를 요구하므로, 이 두 가지 내용만으로 충분한 깊이를 제공한다.'),
    ('prompt-routine-2464', '제시된 문제는 서두른 취침 준비이며, 난이도 I에서는 차분하게 만드는 대응 하나가 충분한 해결책이다.'),
    ('prompt-routine-2465', '씻는 일과 준비 완료라는 목표가 제시되어 있으므로, 이를 따르는 행동 하나면 이 좁은 범위의 난이도 I 질문에 답할 수 있다.'),
    ('prompt-routine-2466', '취침을 위해 미리 준비하는 일이 반복적인 개인 행동으로 설명되어 있으며, 명시적인 이유절이 해당 행동의 이유를 요구한다. 미래의 계획은 요구되지 않는다.'),
    ('prompt-routine-2467', '잠자리에 들 준비를 하는 동안의 평소 느낌과 그 이유를 모두 직접 요구하므로, 초급자에게 충분한 깊이를 제공한다.'),
    ('prompt-routine-2468', '학습자는 잠자리에 들 준비에서 개선하고 싶은 점 하나만 식별하면 되므로, 제시된 목표만으로 질문의 요구를 충족한다.'),
    ('prompt-routine-2469', '도움이 되는 것은 행동이 아니라 보조 수단, 조건 또는 다른 요인일 수 있으므로, 필수 내용은 구체적인 DETAIL이며 행동은 선택 사항으로 두어야 한다.'),
    ('prompt-routine-2470', '학습자는 최근에 잠자리에 들 준비를 했던 일을 이야기해야 하므로, 그 일을 식별하는 것 외에 독립적인 서술 단위 하나가 필요하다.'),
    ('prompt-routine-2471', '원하는 깨끗한 느낌과 잠자리에 들기 전의 상황이 제시되어 있으므로, 집중된 초급 질문에는 평소 행동 하나면 충분하다.'),
    ('prompt-routine-2472', '질문은 수면을 개선하기 위해 잠자리에 들기 전에 하는 행동과 그 행동을 하는 이유를 요구하므로, 행동과 설명만으로 충분하다.'),
    ('prompt-routine-2473', '잠자리에 들 준비를 할 때의 첫 번째 평소 단계와 그 단계부터 시작하는 이유가 명시적인 필수 내용이므로, 이 두 가지로 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-2474', '질문은 샤워 후 도움이 되는 요인과 그 이유를 요구한다. 해당 요인은 보조 수단이나 조건일 수 있으므로 ACTION이 아니라 DETAIL이 필요하다.'),
    ('prompt-routine-2475', '질문은 잠자리에 들기 전 마지막 행동과 그 행동이 어떻게 긴장을 풀어 주는지를 직접 묻으므로, 행동과 그 효과가 모두 필요하며 이 둘이면 충분하다.'),
    ('prompt-routine-25', '표현상 토요일의 시작을 학습자가 보통 어떻게 보내는지를 묻고 있으므로, 활동을 뒷받침할 시간, 순서, 장소, 설명 또는 결과에 관한 세부 내용 하나가 필요하다.'),
    ('prompt-routine-26', '이 간단한 난이도 I 질문은 잠자리에 들기 전에 하는 평소 행동 하나만 요구하므로, 필수적인 보충 내용 없이 그 행동만으로 충분하다.'),
    ('prompt-routine-27', '질문은 잠자리에 들기 전에 자주 반복하는 행동을 요구하므로, 이 수준에서는 일상을 구체화할 보충 내용 하나가 적절하다.'),
    ('prompt-routine-28', '잠자리에 들기 전 일상을 설명하려면 습관적인 행동이 필요하며, 의미 있는 설명이 되려면 추가 단계나 상황에 관한 세부 내용 하나가 더 필요하다.'),
    ('prompt-routine-29', '학습자는 잠자리에 들기 전의 평소 행동 하나를 제시하고 그 이유를 설명해야 하므로, 이 두 가지 필수 내용이면 상위 초급 과제에 충분하다.'),
    ('prompt-routine-30', '시간 표현이 다소 어색하지만, 질문은 학습자가 보통 잠자리에 들기 전에 무엇을 하는지를 묻는다. 행동과 함께 독립적인 보충 내용 하나가 필요하다.'),
    ('prompt-routine-31', '질문은 평소 통근할 때 하는 행동을 요구하므로, 초급자 답변을 발전시키려면 경로 또는 장소, 시간, 이유, 느낌이나 결과에 관한 세부 내용 하나가 필요하다.'),
    ('prompt-routine-32', '통근 중 자주 반복하는 행동이 필요하며, 깊이를 더하려면 장소, 시간, 설명, 느낌 또는 결과에 관한 독립적인 세부 내용 하나가 필요하다.'),
    ('prompt-routine-33', '통근 일상을 설명하려면 반복적인 행동이 하나 이상 필요하고, 단순한 이름 제시에 그치지 않으려면 추가 행동이나 상황에 관한 세부 내용 하나가 더 필요하다.'),
    ('prompt-routine-34', '질문은 평소 통근 행동 하나와 그 행동을 하는 이유를 직접 요구하므로, 이 두 필수 절만으로도 충분한 깊이를 제공한다.'),
    ('prompt-routine-35', '질문의 핵심은 통근하면서 학습자가 보통 무엇을 하는지이므로, 습관적인 행동을 뒷받침할 독립적인 상황이나 설명 하나가 필요하다.'),
    ('prompt-routine-36', '학습자는 점심시간을 보통 어떻게 보내는지 말해야 하므로, 일상을 구체화할 장소, 시간, 추가 활동, 이유 또는 느낌 중 하나가 필요하다.'),
    ('prompt-routine-37', '자주 반복하는 점심시간 행동이 직접적인 답이며, 상위 초급 수준의 깊이를 제공하려면 독립적인 상황이나 결과 하나가 더 필요하다.'),
    ('prompt-routine-38', '점심시간 일상을 설명하려면 습관적인 행동과 적어도 하나의 추가 단계나 상황에 관한 세부 내용이 있어야 설명이 충실해진다.'),
    ('prompt-routine-39', '평소 점심시간 행동 하나와 그 명시적인 이유가 모두 필요하므로, 이 두 내용만으로도 이 수준에 필요한 충분한 깊이를 제공한다.'),
    ('prompt-routine-40', '표현은 다소 어색하지만 학습자의 평소 점심시간 행동을 묻고 있으므로, 이를 뒷받침할 장소, 시간, 순서, 설명 또는 결과에 관한 세부 내용 하나가 필요하다.'),
    ('prompt-routine-41', '질문은 비 오는 날 집에서 학습자가 보통 무엇을 하는지를 묻는다. 깊이를 더하려면 독립적인 세부 내용, 추가 활동, 이유, 느낌 또는 결과 중 하나가 필요하다.'),
    ('prompt-routine-42', '비 오는 날 집에서 자주 반복하는 행동이 필요하며, 상위 초급 답변이 활동 하나에 그치지 않도록 보충 내용 하나가 더 필요하다.'),
    ('prompt-routine-43', '비 오는 날 집에서의 일상을 설명하려면 반복적인 행동과 추가 행동이나 상황에 관한 세부 내용 하나가 있어야 충분히 전개된다.'),
    ('prompt-routine-44', '질문은 비 오는 날 집에서 하는 평소 행동 하나와 그 행동을 선택하는 이유를 직접 요구하므로, 행동과 이유만으로 충분한 깊이를 제공한다.'),
    ('prompt-routine-45', '의도된 과제는 비 오는 날 집에서 학습자가 평소에 하는 행동을 말하는 것이다. 이를 뒷받침하는 한 가지 세부 내용, 추가 활동, 설명, 느낌 또는 결과가 필요하다.'),
    ('prompt-routine-46', '잠에서 바로 깬 직후는 범위가 명확히 제한된 시간이므로, 평소에 하는 첫 행동 하나만으로도 이 단순한 초급 I 수준의 질문에 충분히 답할 수 있다.'),
    ('prompt-routine-47', '잠에서 바로 깬 직후에 자주 반복하는 행동이 필요하며, 초급 상위 수준의 답변을 위해 독립적인 순서나 상황 세부 내용 하나가 추가로 필요하다.'),
    ('prompt-routine-48', '잠에서 바로 깬 직후의 일과를 설명하려면 습관적인 행동과 의미 있는 설명을 위한 추가 단계 또는 상황 세부 내용 하나가 필요하다.'),
    ('prompt-routine-49', '학습자는 잠에서 바로 깬 직후 평소에 하는 행동 하나를 말하고 그 행동을 하는 이유를 설명해야 하므로, 필요한 두 요소만으로 충분하다.'),
    ('prompt-routine-50', '질문의 표현이 다소 어색하더라도, 잠에서 바로 깬 직후의 평소 행동을 묻는 질문이다. 이를 뒷받침하는 독립적인 순서, 시간, 장소, 설명 또는 결과에 관한 세부 내용 하나가 필요하다.');
